INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori", "slug", "backdrop_url", "trailer_url") VALUES
(143, 'Lo squalo 3', 1983, 'Joe Alves', 'Horror, Thriller, Avventura', 'Un enorme grande squalo bianco s''introduce nel parco acquatico di SeaWorld in Florida poco prima dell''inaugurazione di una nuova attrazione subacquea. Quando il cucciolo dello squalo muore all''interno della struttura, la gigantesca madre comincia a seminare il terrore e la distruzione, intrappolando i visitatori e il personale nei tunnel e nelle gallerie sottomarine.', 'https://image.tmdb.org/t/p/w500/kqDXj53F9paqVGJLGfHtz7giJ3s.jpg', '2026-09-27T19:48:40.064399', 'Dennis Quaid, Bess Armstrong, Simon MacCorkindale, Louis Gossett Jr.', NULL, NULL, NULL),
(135, 'Rocky V', 1990, 'John G. Avildsen', 'Drammatico, Sportivo', 'Costretto al ritiro dai combattimenti a causa dei danni cerebrali riportati contro Ivan Drago e finito in rovina finanziaria, Rocky Balboa torna con la famiglia nel suo vecchio quartiere a Philadelphia. Qui comincia ad allenare un giovane e promettente pugile, Tommy Gunn, trascurando il proprio figlio. L''ambizione e l''avidità spingeranno però Tommy a voltare le spalle a Rocky, portando i due a uno scontro finale in una rissa di strada.', 'https://image.tmdb.org/t/p/w500/tevHaVxtrMTaUi8f3YjLWYSSY8A.jpg', '2026-09-19T22:20:24.685429', 'Sylvester Stallone, Talia Shire, Burt Young, Sage Stallone, Tommy Morrison, Richard Gant', NULL, NULL, NULL),
(138, 'Jackie Brown', 1997, 'Quentin Tarantino', 'Crime, Thriller, Noir', 'Una hostess di volo di mezza età, che contrabbanda denaro sporco per un trafficante d''armi, viene incastrata dall''FBI. Per salvarsi, decide di fare il doppio gioco, ideando un piano rischioso per truffare sia i federali che il suo boss e fuggire con mezzo milione di dollari.', 'https://image.tmdb.org/t/p/w500/rOUx7qg4KmEh1juEDwqzbDSL1Nr.jpg', '2026-09-26T14:35:51.485995', 'Pam Grier, Samuel L. Jackson, Robert Forster, Bridget Fonda, Michael Keaton, Robert De Niro', NULL, NULL, NULL),
(145, 'Le iene', 1992, 'Quentin Tarantino', 'Crime, Thriller', 'Dopo che una rapina a una gioielleria sfocia in un sanguinoso scontro a fuoco con la polizia, i sopravvissuti di una banda di criminali sconosciuti tra loro si rifugiano in un capannone abbandonato, convinti che tra di loro ci sia un infiltrato.', 'https://image.tmdb.org/t/p/w500/xi8Iu6qyTfyZVDVy60raIOYJJmk.jpg', '2026-09-28T17:15:18.136647', 'Harvey Keitel, Tim Roth, Michael Madsen, Chris Penn, Steve Buscemi, Lawrence Tierney', NULL, NULL, NULL),
(149, '...altrimenti ci arrabbiamo!', 1974, 'Marcello Fondato', 'Commedia, Azione', 'Ben e Kid, un meccanico e un camionista appassionati di autocross, vincono a pari merito una fantastica Dune Buggy rossa con cappottina gialla. Non potendola dividere, decidono di giocarsela in una sfida a birra e salsicce. La gara viene però interrotta dagli scagnozzi di un gangster speculatore edilizio chiamato ''il Capo'', che distruggono il locale e danno fuoco alla macchina. I due si recano dal boss per pretendere una Dune Buggy nuova identica a quella distrutta, avvertendolo con un chiaro ''...altrimenti ci arrabbiamo!'': di fronte al rifiuto, scateneranno l''inferno a suon di memorabili scazzottate.', 'https://image.tmdb.org/t/p/w500/oERikPHC3cr9UDCale6YrQxkyNW.jpg', '2026-09-29T16:30:07.421745', 'Bud Spencer, Terence Hill, Donald Pleasence, John Sharp, Patty Shepard', NULL, NULL, NULL),
(4, 'Ace Ventura - L''acchiappanimali', 1994, 'Tom Shadyac', 'Commedia', 'Ace Ventura è un eccentrico e stravagante investigatore privato specializzato nel ritrovare animali scomparsi. Alla vigilia del Super Bowl, viene ingaggiato per ritrovare Snowflake, il delfino mascotta dei Miami Dolphins, finito al centro di un misterioso complotto di vendetta legato all''ex giocatore Ray Finkle.', 'https://image.tmdb.org/t/p/w500/pqiRuETmuSybfnVZ7qyeoXhQyN1.jpg', '2026-09-13T14:44:03.51454', 'Jim Carrey, Courteney Cox, Sean Young, Tone Loc, Dan Marino', NULL, NULL, NULL),
(158, 'Batman Begins', 2005, 'Christopher Nolan', 'Azione, Fantascienza', 'Dopo aver assistito all''omicidio dei suoi genitori, il giovane erede Bruce Wayne viaggia per il mondo alla ricerca di un modo per combattere le ingiustizie. Tornato a Gotham City, crea l''iconico alter ego di Batman per salvare la città dalla corruzione e dalle minacce del temibile Ra''s al Ghul e dello Spaventapasseri.', 'https://image.tmdb.org/t/p/w500/sPX89Td70IDDjVr85jdSBb4rWGr.jpg', '2026-09-30T18:34:58.428467', 'Christian Bale, Michael Caine, Liam Neeson, Katie Holmes, Gary Oldman, Cillian Murphy, Morgan Freeman', NULL, NULL, NULL),
(159, 'Il cavaliere oscuro', 2008, 'Christopher Nolan', 'Azione, Thriller, Crime', 'Con l''aiuto del tenente Jim Gordon e del determinato procuratore distrettuale Harvey Dent, Batman continua a combattere il crimine organizzato che affligge Gotham City. La tregua apparente viene però spezzata dall''ascesa del Joker, una mente criminale psicopatica e anarchica che sprofonda la metropoli nel terrore e costringe il Cavaliere Oscuro a camminare sul filo sottile che divide l''eroe dal vigilante.', 'https://image.tmdb.org/t/p/w500/qJ2tW6WMUDux911r6m7haRef0WH.jpg', '2026-09-30T18:52:59.049885', 'Christian Bale, Heath Ledger, Aaron Eckhart, Michael Caine, Maggie Gyllenhaal, Gary Oldman, Morgan Freeman', NULL, NULL, NULL),
(163, 'Digger', 2020, 'Georgis Grigorakis', 'Drammatico', 'Nikitas è un padre che vive solitario in una foresta incontaminata nel nord della Grecia, resistendo con tenacia all''espansione di un colosso minerario che minaccia il suo ambiente. La sua isolata routine viene sconvolta dal ritorno improvviso di suo figlio Johnny dopo vent''anni di assenza, intenzionato a reclamare la sua parte di eredità.', 'https://image.tmdb.org/t/p/w500/rm4UZ9DLXF06npLZMOTNTBNpWhk.jpg', '2026-10-03T07:26:57.834873', 'Vangelis Mourikis, Argyris Pandazaras, Sofia Kokkali, Theo Alexander', NULL, NULL, NULL),
(165, 'Digger', 2026, 'Alejandro González Iñárritu', 'Drammatico, Avventura', 'Incentrato sulla storia dell''uomo più potente del mondo, il quale intraprende una missione frenetica per dimostrare di essere il salvatore dell''umanità prima che la catastrofe scatenata da lui stesso distrugga ogni cosa.', 'https://image.tmdb.org/t/p/w500/1ATXKrIPJyKNwnJ6lcG088Sa6zi.jpg', '2026-10-03T07:38:16.94161', 'Tom Cruise, Sandra Hüller, Jesse Plemons, John Goodman, Riz Ahmed', NULL, NULL, NULL),
(132, 'Spider-Man: Brand New Day', 2026, 'Destin Daniel Cretton', 'Azione, Fantascienza, Avventura', 'Dopo gli eventi di ''Spider-Man: No Way Home'', Peter Parker cerca di rifarsi una vita in una New York che ha dimenticato la sua vera identità. Dovrà bilanciare la sua nuova e solitaria quotidianità con le responsabilità di essere un supereroe di quartiere, affrontando nuove minacce.', 'https://image.tmdb.org/t/p/w500/bjiS5ipwxb9JFy3XRRN4OAilSeX.jpg', '2026-09-19T18:05:53.341805', 'Tom Holland, Zendaya', NULL, NULL, NULL),
(6, 'Il Padrino', 1972, 'Francis Ford Coppola', 'Drammatico, Crime', 'A New York, nel 1945, Don Vito Corleone è il capo di una potente famiglia mafiosa. Dopo aver rifiutato di entrare nel business della droga proposto da un clan rivale, Don Vito subisce un grave attentato. Suo figlio minore Michael, un eroe di guerra fino ad allora estraneo alle attività criminali della famiglia, decide di intervenire per proteggere il padre e vendicarsi. Questo evento darà inizio alla sua inesorabile ascesa e trasformazione nel nuovo spietato Padrino.', 'https://image.tmdb.org/t/p/w500/3bhkrj58Vtu7enYsRolD1fZdja1.jpg', '2026-09-13T14:48:17.858553', 'Marlon Brando, Al Pacino, James Caan, Robert Duvall, Diane Keaton', NULL, NULL, NULL),
(67, 'Robin Hood - Un uomo in calzamaglia', 1993, 'Mel Brooks', 'Commedia, Parodia, Avventura', 'Tornato in Inghilterra dopo essere fuggito da una prigione a Gerusalemme durante le crociate, il nobile Robin di Locksley trova il suo castello confiscato e il paese sotto il giogo oppressivo del vile principe Giovanni e del goffo sceriffo di Ruttingham. Deciso a ristabilire la giustizia, Robin recluta un improbabile gruppo di fuorilegge nella foresta di Sherwood, gli ''Uomini in calzamaglia''. Tra frecce telecomandate, numeri musicali e situazioni demenziali, Robin tenterà di rovesciare il tiranno e conquistare il cuore della bella Lady Marian, la quale custodisce gelosamente la propria virtù protetta da una quasi indistruttibile cintura di castità.', 'https://image.tmdb.org/t/p/w500/woexOLEkUlYsPLLuZRK6LjZaF38.jpg', '2026-09-15T18:04:05.851255', 'Cary Elwes, Richard Lewis, Roger Rees, Amy Yasbeck, Dave Chappelle, Isaac Hayes, Mel Brooks', NULL, NULL, NULL),
(56, 'Rocky II', 1979, 'Sylvester Stallone', 'Drammatico, Sportivo', 'Dopo il durissimo incontro con il campione dei pesi massimi Apollo Creed, Rocky Balboa decide di ritirarsi dal pugilato, sposa l''amata Adriana e cerca di costruirsi una vita tranquilla lontano dal ring. Ben presto però, a causa dell''inesperienza nella gestione del denaro e delle difficoltà a trovare un impiego stabile, Rocky si ritrova in gravi difficoltà economiche. Nel frattempo, Creed, tormentato dalle critiche dei tifosi e dalla stampa che insinuano che il verdetto del precedente match sia stato immeritato, lo provoca ripetutamente per convincerlo a salire di nuovo sul ring per una rivincita. Spinto dal bisogno e dal desiderio di riscatto, e confortato dal supporto di Adriana dopo un periodo critico, Rocky riprende gli allenamenti con Mickey per affrontare un drammatico secondo scontro.', 'https://image.tmdb.org/t/p/w500/nMaiiu0CzT77U4JZkUYV7KqdAjK.jpg', '2026-09-14T13:54:32.775259', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Burgess Meredith', NULL, NULL, NULL),
(139, 'Bullet Train', 2022, 'David Leitch', 'Azione, Commedia, Thriller', 'Un sfortunato assassino di nome Ladybug vuole svolgere una semplice missione a bordo del treno ad alta velocità più veloce del mondo in Giappone. Tuttavia, si ritrova a doversela vedere con diversi killer professionisti provenienti da tutto il mondo, tutti con obiettivi interconnessi e contrastanti.', 'https://image.tmdb.org/t/p/w500/j8szC8OgrejDQjjMKSVXyaAjw3V.jpg', '2026-09-26T15:21:16.969652', 'Brad Pitt, Joey King, Aaron Taylor-Johnson, Brian Tyree Henry, Andrew Koji, Hiroyuki Sanada, Sandra Bullock', NULL, NULL, NULL),
(13, 'Indiana Jones e il quadrante del destino', 2023, 'James Mangold', 'Avventura, Azione, Fantastico', 'Nel 1969, l''archeologo Indiana Jones è ormai prossimo al pensionamento e vive una vita tranquilla. Tutto cambia quando viene visitato dalla sua figlioccia Helena Shaw, che è alla ricerca di un raro e potente manufatto che suo padre aveva affidato a Indy anni prima: il Quadrante di Archimede, un dispositivo capace di individuare fessure temporali. Helena ruba l''oggetto per venderlo al miglior offerente, costringendo Indy a mettersi al suo inseguimento. Nel frattempo, anche Jürgen Voller, un ex scienziato nazista che ora lavora per la NASA, è sulle tracce del Quadrante con l''obiettivo di riscrivere la storia.', 'https://image.tmdb.org/t/p/w500/Af4bXE63pVsb2FtbW8uYIyPBadD.jpg', '2026-09-13T14:53:51.980462', 'Harrison Ford, Phoebe Waller-Bridge, Mads Mikkelsen, Antonio Banderas, John Rhys-Davies, Toby Jones', NULL, NULL, NULL),
(31, 'Indiana Jones e i predatori dell''arca perduta', 1981, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1936, l''archeologo e avventuriero Indiana Jones viene incaricato dai servizi segreti dell''esercito statunitense di trovare la leggendaria Arca dell''Alleanza, lo scrigno sacro contenente i Dieci Comandamenti, prima che cada nelle mani delle forze naziste di Adolf Hitler, intenzionate a sfruttarne il presunto potere sovrannaturale per dominare il mondo. Affiancato dalla sua fiera ex compagna Marion Ravenwood e dal fidato amico Sallah, Jones affronta una pericolosa caccia al tesoro tra le montagne del Nepal e le sabbie dell''Egitto, sfidando trappole mortali e il suo rivale senza scrupoli, l''archeologo francese René Belloq.', 'https://image.tmdb.org/t/p/w500/ceG9VzoRAVGwivFU403Wc3AHRys.jpg', '2026-09-13T15:08:13.656802', 'Harrison Ford, Karen Allen, Paul Freeman, John Rhys-Davies, Ronald Lacey', NULL, NULL, NULL),
(161, 'Lucy', 2014, 'Luc Besson', 'Fantascienza, Azione, Thriller', 'Lucy è una giovane studentessa che vive a Taipei. Viene costretta a fare da corriere della droga da un cartello coreano. Le viene inserito chirurgicamente nel ventre un pacchetto contenente una nuova droga sintetica, il CPH4. A causa di un pestaggio, il pacchetto si rompe e la sostanza viene assorbita dal suo corpo, permettendole di sbloccare progressivamente le capacità del suo cervello fino al 100%.', 'https://image.tmdb.org/t/p/w500/kRbpUTRNm6QbLQFPFWUcNC4czEm.jpg', '2026-09-30T19:35:00.986208', 'Scarlett Johansson, Morgan Freeman, Choi Min-sik, Amr Waked', NULL, NULL, NULL),
(164, 'Il patriota', 2000, 'Roland Emmerich', 'Azione, Drammatico, Storico, Guerra', 'Nel 1776, in Carolina del Sud, il veterano di guerra Benjamin Martin decide di non prendere parte alla guerra d''indipendenza americana per accudire i suoi sette figli. Tuttavia, quando un spietato ufficiale britannico uccide uno dei suoi ragazzi e dà alle fiamme la sua casa, Benjamin prende di nuovo le armi guidando una milizia di volontari contro l''esercito inglese.', 'https://image.tmdb.org/t/p/w500/fWZd815QxUCUcrWQZwUkAp9ljG.jpg', '2026-10-03T07:28:11.755314', 'Mel Gibson, Heath Ledger, Joely Richardson, Jason Isaacs, Chris Cooper', NULL, NULL, NULL),
(120, 'Spider-Man: Far From Home', 2019, 'Jon Watts', 'Azione, Fantascienza, Avventura', 'Peter Parker decide di unirsi ai suoi migliori amici per una vacanza in Europa. Tuttavia, il piano di Peter di lasciarsi i superpoteri alle spalle per qualche settimana viene sventato quando accetta di aiutare Nick Fury a svelare il mistero degli attacchi di diverse creature elementali.', 'https://image.tmdb.org/t/p/w500/4q2NNj4S5dG2RLF9CpXsej7yXl.jpg', '2026-09-18T13:15:40.475072', 'Tom Holland, Samuel L. Jackson, Zendaya, Jake Gyllenhaal, Cobie Smulders', NULL, NULL, NULL),
(119, 'Spider-Man: Homecoming', 2017, 'Jon Watts', 'Azione, Fantascienza, Avventura', 'Il giovane Peter Parker, entusiasta della sua esperienza con gli Avengers, torna a casa dove vive con la zia May. Sotto l''occhio vigile del suo mentore Tony Stark, Peter cerca di trovare un equilibrio tra la sua vita da normale studente e la sua identità segreta di Spider-Man, ma l''arrivo del villain Avvoltoio metterà tutto a rischio.', 'https://image.tmdb.org/t/p/w500/c24sv2weTHPsmDa7jEMN0m2P3RT.jpg', '2026-09-18T13:15:40.380686', 'Tom Holland, Michael Keaton, Zendaya, Robert Downey Jr., Marisa Tomei', NULL, NULL, NULL),
(121, 'Spider-Man: No Way Home', 2021, 'Jon Watts', 'Azione, Fantascienza, Avventura', 'Per la prima volta nella storia cinematografica di Spider-Man, viene rivelata l''identità del nostro amichevole eroe di quartiere. Quando Peter chiede aiuto al Dottor Strange per ripristinare il suo segreto, l''incantesimo squarcia un buco nel loro mondo, liberando i più potenti nemici mai affrontati da uno Spider-Man in qualsiasi universo.', 'https://image.tmdb.org/t/p/w500/or6XJBVpcEbIkma0V9zshnbEtx4.jpg', '2026-09-18T13:15:40.579867', 'Tom Holland, Zendaya, Benedict Cumberbatch, Jacob Batalon, Jon Favreau', NULL, NULL, NULL),
(140, 'C''era una volta a New York', 2013, 'James Gray', 'Drammatico, Storico', 'Nel 1921, le sorelle polacche Ewa e Magda arrivano a Ellis Island in cerca di una vita migliore. Quando Magda viene messa in quarantena per tubercolosi, Ewa si ritrova sola e vulnerabile, finendo sotto il controllo di un ambiguo impresario che la avvia alla prostituzione.', 'https://image.tmdb.org/t/p/w500/ArWRRQYeXL3nG4jYpMOPoBvgmy9.jpg', '2026-09-27T17:50:02.764654', 'Marion Cotillard, Joaquin Phoenix, Jeremy Renner', NULL, NULL, NULL),
(69, 'Robin Hood', 2010, 'Ridley Scott', 'Azione, Avventura, Storico, Drammatico', 'Nell''Inghilterra del XIII secolo, dopo la morte di re Riccardo Cuor di Leone, l''arciere Robin Longstride torna in patria dalla Francia. Giunto a Nottingham, assume l''identità del defunto cavaliere Robert Loxley e si innamora della vedova Marion. Di fronte alla minaccia di un''invasione francese e alla tirannia del nuovo re Giovanni, Robin unisce i baroni ribelli e il popolo per difendere il paese, gettando le basi per la nascita della leggenda di Robin Hood.', 'https://image.tmdb.org/t/p/w500/9NS5QGOfck24yL3bZqWeW06PgPC.jpg', '2026-09-15T18:14:13.404964', 'Russell Crowe, Cate Blanchett, Mark Strong, Oscar Isaac, William Hurt', NULL, NULL, NULL),
(63, 'Robin Hood', 1922, 'Allan Dwan', 'Avventura, Azione, Muto', 'Il Conte di Huntingdon parte per la Terza Crociata insieme a Re Riccardo Cuor di Leone. Durante la loro assenza, il perfido Principe Giovanni usurpa il trono d''Inghilterra instaurando un regime di terrore ed estorsione ai danni del popolo. Informato delle ingiustizie, il Conte torna in patria sotto le spoglie del fuorilegge Robin Hood e si rifugia nella foresta di Sherwood. Insieme alla sua banda di fedeli compagni, comincia a rubare ai ricchi per dare ai poveri, combattendo il tiranno per proteggere la sua amata Lady Marian e attenderne il ritorno del legittimo re.', 'https://image.tmdb.org/t/p/w500/baqMnZbAFPsfbaAOPRU1eJlCRdj.jpg', '2026-09-15T18:04:05.143269', 'Douglas Fairbanks, Wallace Beery, Sam De Grasse, Enid Bennett, Alan Hale', NULL, NULL, NULL),
(90, 'Rambo: Last Blood', 2019, 'Adrian Grunberg', 'Azione', 'Ormai anziano, John Rambo cerca di condurre una vita tranquilla nel ranch di famiglia in Arizona. Quando la sua giovane nipote viene rapita in Messico da un cartello della droga, Rambo si reca oltre confine scatendando un''ultima, spietata vendetta.', 'https://image.tmdb.org/t/p/w500/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg', '2026-09-16T10:28:14.334618', 'Sylvester Stallone, Paz Vega, Sergio Peris-Mencheta', NULL, NULL, NULL),
(146, 'Blade Runner', 1982, 'Ridley Scott', 'Fantascienza, Noir', 'In una Los Angeles distopica e piovosa del 2019, l''ex poliziotto Rick Deckard viene richiamato in servizio come ''blade runner''. Il suo compito è rintracciare e ''ritirare'' quattro replicanti della serie Nexus-6, androidi indistinguibili dagli umani, fuggiti dalle colonie extra-terrestri e giunti illegalmente sulla Terra alla ricerca del loro creatore per prolungare la propria breve vita.', 'https://image.tmdb.org/t/p/w500/63N9uy8nd9j7Eog2axPQ8lbr3Wj.jpg', '2026-09-29T13:49:10.170972', 'Harrison Ford, Rutger Hauer, Sean Young, Edward James Olmos, Daryl Hannah', NULL, NULL, NULL),
(150, 'Dune', 2021, 'Denis Villeneuve', 'Fantascienza, Avventura, Drammatico', 'In un lontano futuro dell''umanità, il duca Leto Atreides accetta la gestione del pericoloso pianeta desertico Arrakis, noto anche come Dune, l''unica fonte della sostanza più preziosa dell''universo, la "spezia". Paul Atreides, il giovane erede della dinastia, dovrà viaggiare verso il pianeta più pericoloso dell''universo per assicurare il futuro della sua famiglia e del suo popolo.', 'https://image.tmdb.org/t/p/w500/v1tRXZ4JtD2Iv6fjkPvT4GiwslV.jpg', '2026-09-29T16:32:47.707379', 'Timothée Chalamet, Rebecca Ferguson, Oscar Isaac, Josh Brolin, Zendaya, Jason Momoa', NULL, NULL, NULL),
(153, 'Toy Story - Il mondo dei giocattoli', 1995, 'John Lasseter', 'Animazione, Avventura, Commedia', 'Woody, un classico pupazzo da cowboy, è il giocattolo preferito del piccolo Andy e il leader riconosciuto di tutti gli altri giochi della cameretta. La sua posizione viene però minacciata quando per il compleanno di Andy arriva Buzz Lightyear, un supertecnologico astronauta giocattolo convinto di essere un vero spaziotraversatore. Inizialmente rivali, Woody e Buzz si ritroveranno accidentalmente divisi da Andy e dovranno unire le forze per affrontare mille pericoli e tornare a casa.', 'https://image.tmdb.org/t/p/w500/uXDfjJbdP4ijW5hWSBrPrlKpxab.jpg', '2026-09-30T18:28:22.395285', 'Tom Hanks, Tim Allen, Don Rickles, Jim Varney, Wallace Shawn', NULL, NULL, NULL),
(154, 'Toy Story 2 - Woody e Buzz alla riscossa', 1999, 'John Lasseter, Lee Unkrich, Ash Brannon', 'Animazione, Avventura, Commedia', 'Mentre Andy è via per il campeggio estivo, Woody viene rapito da Al McWhiggin, un gordo e avido collezionista di giocattoli deciso a venderlo a un museo di Tokyo insieme ai membri della classica serie TV ''Woody''s Roundup''. Buzz Lightyear e gli altri giocattoli di Andy partono immediatamente per una coraggiosa missione di salvataggio per riportare l''amico a casa.', 'https://image.tmdb.org/t/p/w500/4rbcp3ng8n1MKHjpeqW0L7Fnpzz.jpg', '2026-09-30T18:28:42.612191', 'Tom Hanks, Tim Allen, Joan Cusack, Kelsey Grammer, Don Rickles', NULL, NULL, NULL),
(50, 'Avengers: Age of Ultron', 2015, 'Joss Whedon', 'Azione, Fantascienza, Avventura', 'Quando Tony Stark e Bruce Banner cercano di avviare un programma di mantenimento della pace inattivo chiamato Ultron, le cose vanno terribilmente storte e il sistema intelligenza artificiale sviluppa una coscienza divina, decidendo che l''unico modo per salvare la Terra è sterminare l''umanità. Gli Avengers devono riunirsi e stringere imprevedibili alleanze per fermare il temibile Ultron e i suoi piani di distruzione globale.', 'https://image.tmdb.org/t/p/w500/4ssDuvEDkSArWEdyBl2X5EHvYKU.jpg', '2026-09-14T13:51:07.184214', 'Robert Downey Jr., Chris Hemsworth, Mark Ruffalo, Chris Evans, Scarlett Johansson, Jeremy Renner', NULL, NULL, NULL),
(49, 'The Avengers', 2012, 'Joss Whedon', 'Azione, Fantascienza, Avventura', 'Quando Loki, il malvagio fratellastro di Thor, minaccia la sicurezza della Terra impossessandosi del potente Tesseract, Nick Fury, direttore dell''agenzia di spionaggio S.H.I.E.L.D., decide di attivare il protocollo Avengers. Per sconfiggere la minaccia aliena, Fury riunisce una squadra di supereroi straordinari, tra cui Iron Man, Captain America, Thor, Hulk, Vedova Nera e Occhio di Falco. Nonostante le iniziali incomprensioni e i conflitti interni, il gruppo dovrà unire le forze per salvare l''umanità.', 'https://image.tmdb.org/t/p/w500/RYMX2wcKCBAr24UyPD7xwmjaTn.jpg', '2026-09-14T13:51:06.242759', 'Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth, Scarlett Johansson, Jeremy Renner, Tom Hiddleston, Samuel L. Jackson', NULL, NULL, NULL),
(83, 'Interstellar', 2014, 'Christopher Nolan', 'Fantascienza, Avventura, Drammatico', 'In un futuro non lontano, un''inarrestabile piaga sta distruggendo i raccolti terrestri, condannando l''umanità alla fame. Un gruppo di esploratori e scienziati, guidati dall''ex pilota della NASA Cooper, intraprende una missione interstellare attraverso un wormhole recentemente scoperto nei pressi di Saturno, nel disperato tentativo di trovare un nuovo pianeta abitabile per salvare la specie umana.', 'https://image.tmdb.org/t/p/w500/yQvGrMoipbRoddT0ZR8tPoR7NfX.jpg', '2026-09-15T19:39:43.339888', 'Matthew McConaughey, Anne Hathaway, Jessica Chastain, Michael Caine, John Lithgow, Ellen Burstyn', NULL, NULL, NULL),
(136, 'La storia del generale Custer', 1941, 'Raoul Walsh', 'Western, Biografico, Drammatico', 'La vita romanzata di George Armstrong Custer, dalla sua giovinezza all''accademia militare di West Point, attraverso le sue eroiche imprese durante la Guerra di Secessione, fino alla sua tragica morte nella celebre battaglia di Little Bighorn.', 'https://image.tmdb.org/t/p/w500/gx8jknFwZRuQwTPooe14Dsx5uTO.jpg', '2026-09-21T20:27:04.54815', 'Errol Flynn, Olivia de Havilland, Arthur Kennedy, Charley Grapewin', NULL, NULL, NULL),
(147, 'Mr. Crocodile Dundee', 1986, 'Peter Faiman', 'Commedia, Avventura', 'Sue Charlton, una giornalista di New York, si reca nell''outback australiano per incontrare Michael J. "Crocodile" Dundee, un leggendario cacciatore di coccodrilli. Affascinata dal suo stile di vita, lo invita a New York, dove Dundee dovrà adattarsi alla caotica vita della metropoli.', 'https://image.tmdb.org/t/p/w500/pduPduL1ub5kok3lPYT15ryC9L6.jpg', '2026-09-29T14:21:36.286935', 'Paul Hogan, Linda Kozlowski, John Meillon, David Gulpilil', NULL, NULL, NULL),
(57, 'Pirati dei Caraibi - La maledizione della prima luna', 2003, 'Gore Verbinski', 'Avventura, Azione, Fantastico', 'Caraibi, XVII secolo. La vita del pacifico fabbro Will Turner viene sconvolta quando l''amore della sua vita, Elizabeth Swann, figlia del governatore, viene rapita dal malvagio Capitan Barbossa e dalla sua ciurma di pirati a bordo della misteriosa nave Perla Nera. Per salvarla, Will si allea con l''eccentrico e stravagante pirata Jack Sparrow, ex capitano della Perla Nera desideroso di vendetta. I due scopriranno che Barbossa e i suoi uomini sono colpiti da una terribile maledizione azteca che li condanna a vivere come non-morti, rivelando il loro vero aspetto di scheletri solo sotto la luce della luna.', 'https://image.tmdb.org/t/p/w500/poHwCZeWzJCShH7tOjg8RIoyjcw.jpg', '2026-09-14T14:11:05.971925', 'Johnny Depp, Orlando Bloom, Keira Knightley, Geoffrey Rush', NULL, NULL, NULL),
(151, 'Dune - Parte due', 2024, 'Denis Villeneuve', 'Fantascienza, Avventura, Azione', 'Paul Atreides si unisce a Chani e ai Fremen sul sentiero della vendetta contro i cospiratori che hanno distrutto la sua famiglia. Di fronte alla scelta tra l''amore della sua vita e il destino dell''universo conosciuto, Paul intraprende una missione per impedire un futuro terribile che solo lui è in grado di prevedere.', 'https://image.tmdb.org/t/p/w500/6izwz7rsy95ARzTR3poZ8H6c5pp.jpg', '2026-09-29T16:33:43.786172', 'Timothée Chalamet, Zendaya, Rebecca Ferguson, Josh Brolin, Austin Butler, Florence Pugh, Dave Bautista, Christopher Walken, Léa Seydoux, Javier Bardem', NULL, NULL, NULL),
(155, 'Toy Story 3 - La grande fuga', 2010, 'Lee Unkrich', 'Animazione, Avventura, Commedia, Fantastico', 'Andy, ormai cresciuto, sta per partire per il college. Woody, Buzz e gli altri giocattoli vengono accidentalmente donati a un asilo nido, il Sunnyside, che si rivelerà essere tutt''altro che un paradiso, sotto il controllo del malvagio orsetto Lotso. I giocattoli dovranno pianificare una grande fuga per tornare a casa.', 'https://image.tmdb.org/t/p/w500/AbbXspMOwdvwWZgVN0nabZq03Ec.jpg', '2026-09-30T18:29:06.156918', 'Tom Hanks, Tim Allen, Joan Cusack, Ned Beatty, Don Rickles', NULL, NULL, NULL),
(156, 'Toy Story 4', 2019, 'Josh Cooley', 'Animazione, Avventura, Commedia, Fantastico', 'Woody, Buzz e il resto della banda vivono felici con la loro nuova bambina, Bonnie. Quando Bonnie crea un nuovo riluttante giocattolo di nome Forky da un cucchiaio-forchetta usa e getta, Woody si assume il compito di proteggerlo. Durante un viaggio di famiglia on-the-road, Woody ritrova la sua vecchia amica Bo Peep, scoprendo una nuova prospettiva su cosa significhi essere un giocattolo.', 'https://image.tmdb.org/t/p/w500/w9kR8qbmQ01HwnvK4alvnQ2ca0L.jpg', '2026-09-30T18:29:34.3281', 'Tom Hanks, Tim Allen, Annie Potts, Tony Hale', NULL, NULL, NULL),
(157, 'Toy Story 5', 2026, 'Andrew Stanton', 'Animazione, Avventura, Commedia', 'In questo nuovo capitolo della celebre saga Pixar, i giocattoli si trovano ad affrontare una sfida del tutto moderna: la competizione con la tecnologia e i dispositivi elettronici, che catturano sempre di più l''attenzione dei bambini di oggi.', 'https://image.tmdb.org/t/p/w500/sfQtVlIHljToOwYjhe21KPGzZWK.jpg', '2026-09-30T18:29:50.711642', 'Tom Hanks, Tim Allen', NULL, NULL, NULL),
(122, 'Matrix', 1999, 'Lana Wachowski, Lilly Wachowski', 'Fantascienza, Azione', 'Un programmatore e hacker di nome Neo scopre che la realtà che vive è una simulazione virtuale creata da macchine senzienti, unendosi a un gruppo di ribelli per liberare l''umanità.', 'https://image.tmdb.org/t/p/w500/dXNAPwY7VrqMAo51EKhhCJfaGb5.jpg', '2026-09-18T18:40:18.760253', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving', NULL, NULL, NULL),
(123, 'Matrix Reloaded', 2003, 'Lana Wachowski, Lilly Wachowski', 'Fantascienza, Azione', 'Mentre l''esercito delle macchine prepara un attacco contro Zion, Neo scopre maggiori dettagli sul suo destino come l''Eletto e affronta una minaccia crescente rappresentata dall''Agente Smith.', 'https://image.tmdb.org/t/p/w500/8xEVAe84zlL9rkfYT6dZXero4KK.jpg', '2026-09-18T18:40:18.899672', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving', NULL, NULL, NULL),
(124, 'Matrix Revolutions', 2003, 'Lana Wachowski, Lilly Wachowski', 'Fantascienza, Azione', 'L''assedio a Zion raggiunge il culmine mentre Neo stringe un patto con la città delle macchine per fermare l''Agente Smith, divenuto un virus capace di distruggere entrambi i mondi.', 'https://image.tmdb.org/t/p/w500/qEWiBXJGXK28jGBAm8oFKKTB0WD.jpg', '2026-09-18T18:40:19.005755', 'Keanu Reeves, Laurence Fishburne, Carrie-Anne Moss, Hugo Weaving', NULL, NULL, NULL),
(125, 'Matrix Resurrections', 2021, 'Lana Wachowski', 'Fantascienza, Azione', 'Neo vive una vita ordinaria a San Francisco sotto l''identità di Thomas Anderson, finché non viene risvegliato da un nuovo gruppo di ribelli per liberare Trinity da una versione aggiornata di Matrix.', 'https://image.tmdb.org/t/p/w500/8c4a8kE7PizaGQQnditMmI1xbRp.jpg', '2026-09-18T18:40:19.107857', 'Keanu Reeves, Carrie-Anne Moss, Yahya Abdul-Mateen II, Jonathan Groff', NULL, NULL, NULL),
(22, 'Il gladiatore invincibile', 1961, 'Antonio Momplet', 'Peplum', 'Il gladiatore Rezius viene inviato in una provincia imperiale per sedare una ribellione, ma scopre che i ribelli stanno lottando contro un tiranno corrotto. Deciderà di schierarsi dalla parte degli oppressi per riportare la giustizia.', 'https://image.tmdb.org/t/p/w500/zela8yXh9bWUBab7911vSLb9OGm.jpg', '2026-09-13T15:01:44.852302', 'Richard Harrison, Isabelle Corey, Livio Lorenzon, Leo Anchóriz, Edoardo Nevola', NULL, NULL, NULL),
(23, 'Il gladiatore che sfidò l''impero', 1965, 'Domenico Paolella', 'Peplum, Avventura, Storico', 'Durante l''impero di Marco Aurelio, il corrotto senatore Lucio Quintilio trama per impossessarsi di un leggendario tesoro e usurpare il potere. A contrastare i suoi piani diabolici si erge il valoroso gladiatore Marco che, alleatosi con i ribelli e i fedeli all''imperatore, affronterà duri scontri e insidie nell''arena per ristabilire la giustizia e salvare l''impero.', 'https://image.tmdb.org/t/p/w500/keKrpGdwvxRPHOyKPnlrVu5dQiU.jpg', '2026-09-13T15:01:45.162067', 'Peter Lupus, Massimo Serato, Gloria Milland, Piero Lulli, Walter Brandi', NULL, NULL, NULL),
(141, 'Lo squalo', 1975, 'Steven Spielberg', 'Thriller, Horror, Avventura', 'Un grande squalo bianco terrorizza le acque di una cittadina balneare. Per fermare il predatore, il capo della polizia locale stringe un''alleanza con un giovane biologo marino e un eccentrico cacciatore di squali.', 'https://image.tmdb.org/t/p/w500/lxM6kqilAdpdhqUl2biYp5frUxE.jpg', '2026-09-27T19:10:54.826059', 'Roy Scheider, Robert Shaw, Richard Dreyfuss, Lorraine Gary', NULL, NULL, NULL),
(113, 'The Cloverfield Paradox', 2018, 'Julius Onah', 'Fantascienza, Horror, Thriller', 'Un gruppo di scienziati a bordo di una stazione spaziale testa un acceleratore di particelle per risolvere una crisi energetica globale, ma si ritrova in una dimensione alternativa.', 'https://image.tmdb.org/t/p/w500/vJi2ExTcWdJR3150VPKqqtdGxsT.jpg', '2026-09-17T16:00:28.606117', 'Gugu Mbatha-Raw, David Oyelowo, Daniel Brühl, Elizabeth Debicki', NULL, NULL, NULL),
(15, 'Le avventure di Bianca e Bernie', 1977, 'Wolfgang Reitherman, John Lounsbery, Art Stevens', 'Animazione, Avventura, Commedia, Famiglia', 'All''interno delle Nazioni Unite ha sede la Società Internazionale di Salvataggio, un''organizzazione segreta composta da topi da tutto il mondo incaricata di prestare soccorso a chi ne ha bisogno. Quando viene ritrovato un messaggio in bottiglia inviato da Penny, una bambina orfana rapita, la determinata topina ungherese Bianca si offre volontaria per salvarla e sceglie come compagno di viaggio il timido e superstizioso usciere Bernie. I due scoprono che Penny è stata rapita dalla spietata Madame Medusa, intenzionata a usarla per farsi strada nelle strette cavità sotterranee della Baia del Diavolo e recuperare il diamante più grande del mondo, ''L''Occhio del Diavolo''. Con l''aiuto dell''albatros Orville, della libellula Evinrude e degli stravaganti abitanti della palude, Bianca e Bernie affronteranno alligatori e insidie per liberare la bambina.', 'https://image.tmdb.org/t/p/w500/9jpDjrRyvv9Nw0piXOpHHQTfxw9.jpg', '2026-09-13T14:58:31.623317', 'Bob Newhart, Eva Gabor, Geraldine Page, Joe Flynn, Jim Jordan', NULL, NULL, NULL),
(37, 'Arancia Meccanica', 1971, 'Stanley Kubrick', 'Drammatico, Fantascienza, Grottesco', 'In una Gran Bretagna distopica e futuristica, il giovane Alex DeLarge è il leader dei Drughi, una banda di criminali dedita ad atti brutali di ''ultraviolenza''. Dopo essere stato arrestato per omicidio e condannato al carcere, Alex accetta di sottoporsi alla ''Cura Ludovico'', un innovativo e controverso trattamento di condizionamento psicologico promosso dal governo. Il trattamento lo rende fisicamente incapace di compiere o persino di pensare ad azioni violente, ma al contempo lo priva del suo libero arbitrio, lasciandolo del tutto indifeso di fronte alla società e alla vendetta delle sue vecchie vittime.', 'https://image.tmdb.org/t/p/w500/4sHeTAp65WrSSuc05nRBKddhBxO.jpg', '2026-09-13T15:23:44.98867', 'Malcolm McDowell, Patrick Magee, Michael Bates, Warren Clarke', NULL, NULL, NULL),
(126, 'Il buono, il brutto, il cattivo', 1966, 'Sergio Leone', 'Western', 'Durante la guerra di secessione americana, tre cinici fuorilegge - il ''Buono'' (Joe), il ''Brutto'' (Tuco) e il ''Cattivo'' (Sentenza) - cercano un tesoro nascosto contenente 200.000 dollari in oro confederato, muovendosi tra alleanze precarie, inganni e scontri mortali.', 'https://image.tmdb.org/t/p/w500/bX2xnavhMYjWDoZp1VM6VnU1xwe.jpg', '2026-09-18T18:50:54.001858', 'Clint Eastwood, Eli Wallach, Lee Van Cleef', NULL, NULL, NULL),
(82, 'Mai dire mai', 1983, 'Irvin Kershner', 'Azione, Spionaggio, Avventura, Thriller', 'James Bond, ormai vicino all''età pensionabile e mandato in una clinica per rimettersi in forma, scopre una cospirazione ordita dall''organizzazione criminale SPECTRE. Guidato dal malvagio Maximilian Largo sotto gli ordini di Ernst Stavro Blofeld, il gruppo riesce a rubare due testate nucleari cruise della NATO per ricattare il mondo. L''agente 007 viene richiamato in servizio d''urgenza da M e si mette sulle tracce delle armi, scontrandosi con la letale assassina Fatima Blush e cercando di conquistare la fiducia della bellissima Domino Petachi, amante di Largo, per sventare l''olocausto nucleare.', 'https://image.tmdb.org/t/p/w500/zhoAL4o1STGgLbLxJ9r1ijfyHC9.jpg', '2026-09-15T19:25:47.259973', 'Sean Connery, Klaus Maria Brandauer, Kim Basinger, Barbara Carrera, Max von Sydow', NULL, NULL, NULL),
(18, 'La nave bianca', 1941, 'Roberto Rossellini', 'Drammatico, Guerra', 'Durante la seconda guerra mondiale, un giovane marinaio imbarcato su una nave da guerra italiana rimane ferito all''addome durante uno scontro navale nel Mediterraneo. Dopo essere stato operato d''urgenza a bordo, viene trasferito sulla nave ospedale ''Arno'' (la nave bianca del titolo) per le cure successive. A bordo della nave troverà assistenza e conforto grazie alle cure di un''infermiera volontaria della Croce Rossa, la quale scoprirà essere proprio la ragazza con cui il giovane intratteneva una romantica corrispondenza epistolare senza averla mai incontrata prima.', 'https://image.tmdb.org/t/p/w500/8NdHt1zvhy249pOMbK9aiw8IHvp.jpg', '2026-09-13T14:58:32.748006', 'Augusto Basso, Equipaggio della Regia Marina', NULL, NULL, NULL),
(148, 'Master & Commander - Sfida ai confini del mare', 2003, 'Peter Weir', 'Avventura, Azione, Storico, Drammatico', 'Durante le guerre napoleoniche, la fregata britannica HMS Surprise, guidata dal carismatico capitano Jack Aubrey, riceve l''ordine di intercettare e catturare la nave corsara francese Acheron. Dopo un devastante attacco a sorpresa da parte di quest''ultima, Aubrey decide di inseguire il nemico attraverso gli oceani, spingendosi fino a Capo Horn e alle isole Galápagos, in una caccia ossessiva che metterà a dura prova la lealtà e la sopravvivenza del suo equipaggio.', 'https://image.tmdb.org/t/p/w500/7ZUHF6P0vcA5v1Gm8NbRYyd9w4N.jpg', '2026-09-29T15:09:03.31573', 'Russell Crowe, Paul Bettany, James D''Arcy, Edward Woodall, Chris Larkin', NULL, NULL, NULL),
(61, 'Pirati dei Caraibi - La vendetta di Salazar', 2017, 'Joachim Rønning, Espen Sandberg', 'Avventura, Fantastico, Azione, Commedia', 'Il capitano Jack Sparrow si ritrova al centro di una nuova e mortale caccia quando il terrificante capitano Armando Salazar e la sua ciurma di marinai fantasma fuggono dal Triangolo del Diavolo, decisi a sterminare tutti i pirati dei sette mari e a vendicarsi proprio di Jack. L''unica speranza di salvezza per Sparrow risiede nel leggendario Tridente di Poseidone, un potente artefatto capace di conferire il controllo totale sui mari e spezzare ogni maledizione. Per trovarlo, Jack stringe un''alleanza con Henry Turner, un giovane marinaio della Royal Navy intenzionato a liberare suo padre Will dalla maledizione dell''Olandese Volante, e Carina Smyth, una brillante e coraggiosa astronoma ingiustamente accusata di stregoneria.', 'https://image.tmdb.org/t/p/w500/6lAPOAFYFWIO3SQRemEY2wInQMC.jpg', '2026-09-14T14:11:06.775662', 'Johnny Depp, Javier Bardem, Geoffrey Rush, Brenton Thwaites, Kaya Scodelario, Kevin McNally', NULL, NULL, NULL),
(58, 'Pirati dei Caraibi - La maledizione del forziere fantasma', 2006, 'Gore Verbinski', 'Avventura, Azione, Fantastico', 'Il capitano Jack Sparrow scopre di avere un debito di sangue con il temibile Davy Jones, sovrano degli abissi e capitano del fantasmagorico Olandese Volante. Se non riuscirà a trovare una via d''uscita, Jack sarà condannato alla servitù eterna nell''equipaggio dei dannati. Per salvarsi, Jack deve rintracciare il leggendario forziere fantasma, contenente il cuore pulsante di Jones, l''unica debolezza del capitano dei mari. Nel frattempo, il matrimonio di Will Turner ed Elizabeth Swann viene interrotto dall''arresto da parte della Compagnia delle Indie Orientali guidata da Lord Cutler Beckett, il quale ricatta Will affinché rintracci Sparrow e si impossessi della sua bussola magica. I destini dei tre protagonisti si intrecciano nuovamente in una pericolosa caccia al tesoro, minacciata dalla mostruosa creatura marina al servizio di Jones: il Kraken.', 'https://image.tmdb.org/t/p/w500/uXEqmloGyP7UXAiphJUu2v2pcuE.jpg', '2026-09-14T14:11:06.153625', 'Johnny Depp, Orlando Bloom, Keira Knightley, Bill Nighy, Jack Davenport, Stellan Skarsgård', NULL, NULL, NULL),
(142, 'Lo squalo 2', 1978, 'Jeannot Szwarc', 'Thriller, Horror, Avventura', 'Quattro anni dopo i tragici eventi dell''isola di Amity, la cittadina cerca di tornare alla normalità. Tuttavia, quando iniziano a verificarsi nuove e misteriose sparizioni in acqua, il capo della polizia Martin Brody si convince che un altro grande squalo bianco stia terrorizzando la zona. Nonostante lo scetticismo delle autorità locali, Brody dovrà agire in fretta per salvare un gruppo di giovani velisti, tra cui i suoi stessi figli, finiti nel mirino del predatore.', 'https://image.tmdb.org/t/p/w500/cN3ijEwsn4kBaRuHfcJpAQJbeWe.jpg', '2026-09-27T19:21:15.792586', 'Roy Scheider, Lorraine Gary, Murray Hamilton, Joseph Mascolo', NULL, NULL, NULL),
(144, 'Bastardi senza gloria', 2009, 'Quentin Tarantino', 'Guerra, Drammatico, Azione', 'Nella Francia occupata dai nazisti durante la seconda guerra mondiale, un gruppo di soldati ebrei americani guidati dal tenente Aldo Raine, noti come ''I Bastardi'', viene paracadutato per seminare il terrore tra le truppe tedesche. Le loro strade si incroceranno con quelle di Shosanna Dreyfus, una giovane ebrea sopravvissuta all''eccidio della sua famiglia per mano del spietato colonnello SS Hans Landa, che pianifica una clamorosa vendetta all''interno del proprio cinema a Parigi.', 'https://image.tmdb.org/t/p/w500/aupnPtagH9JVBuMrGEanf4iqXEQ.jpg', '2026-09-28T08:43:56.799523', 'Brad Pitt, Christoph Waltz, Mélanie Laurent, Diane Kruger, Michael Fassbender, Eli Roth, Daniel Brühl', NULL, NULL, NULL),
(24, 'I sette gladiatori', 1962, 'Pedro Lazaga', 'Peplum, Avventura, Storico', 'Marcus, un valoroso gladiatore, fugge da Roma per fare ritorno a Sparta, la sua terra natale. Al suo arrivo scopre che il suo popolo è sottomesso alla tirannia di un governatore spietato. Per liberare la sua gente, Marcus decide di reclutare altri sei abili e forti gladiatori, unendo le forze per guidare una rivolta contro l''oppressore.', 'https://image.tmdb.org/t/p/w500/jAQg4h3AhSgOH3jLRlcRCzagFXW.jpg', '2026-09-13T15:01:45.454339', 'Richard Harrison, Loredana Nusciak, Livio Lorenzon, Gérard Tichy', NULL, NULL, NULL),
(128, 'Giù la testa', 1971, 'Sergio Leone', 'Western / Storico', 'Durante la rivoluzione messicana, un ingenuo bandito locale e un tormentato dinamitardo irlandese uniscono le forze in una serie di rapine che si trasformeranno in gesta eroiche.', 'https://image.tmdb.org/t/p/w500/nWmAtZf83qpOai0fzehf7Hn1S3R.jpg', '2026-09-18T18:57:49.329857', 'Rod Steiger, James Coburn, Romolo Valli', NULL, NULL, NULL),
(152, 'Poseidon', 2006, 'Wolfgang Petersen', 'Azione, Avventura, Catastrofico', 'Durante la notte di Capodanno, una gigantesca onda anomala travolge e capovolge la lussuosa nave da crociera Poseidon. Un piccolo gruppo di sopravvissuti decide di non aspettare i soccorsi e tenta una disperata fuga verso la salvezza attraverso lo scafo capovolto.', 'https://image.tmdb.org/t/p/w500/fDPdjGc8SUEDWfTwMaZlCE6NSi3.jpg', '2026-09-30T13:28:17.9258', 'Josh Lucas, Kurt Russell, Jacinda Barrett, Richard Dreyfuss, Emmy Rossum', NULL, NULL, NULL),
(127, 'C''era una volta il West', 1968, 'Sergio Leone', 'Western', 'Una giovane vedova difende la propria terra dalle mire di un magnate delle ferrovie, aiutata da un misterioso uomo con l''armonica e da un fuorilegge romantico.', 'https://image.tmdb.org/t/p/w500/qbYgqOczabWNn2XKwgMtVrntD6P.jpg', '2026-09-18T18:57:49.249802', 'Claudia Cardinale, Henry Fonda, Charles Bronson, Jason Robards', NULL, NULL, NULL),
(129, 'C''era una volta in America', 1984, 'Sergio Leone', 'Drammatico / Noir', 'La complessa epopea di un gruppo di gangster ebrei a New York, dall''infanzia nel ghetto negli anni ''20 fino al drammatico bilancio esistenziale negli anni ''60.', 'https://image.tmdb.org/t/p/w500/i0enkzsL5dPeneWnjl1fCWm6L7k.jpg', '2026-09-18T18:57:49.435519', 'Robert De Niro, James Woods, Elizabeth McGovern, Joe Pesci', NULL, NULL, NULL),
(8, 'Il Padrino - Parte III', 1990, 'Francis Ford Coppola', 'Drammatico, Poliziesco', 'Ormai anziano e tormentato dai sensi di colpa per i crimini del passato, in particolare per l''omicidio del fratello Fredo, Michael Corleone cerca di legalizzare le attività della famiglia e di ripulire il proprio nome attraverso una colossale donazione alla Chiesa Cattolica. Mentre tenta di districarsi dalle trame di potere e corruzione all''interno del Vaticano, Michael deve anche gestire la successione dinastica, designando come suo erede l''irrequieto e violento nipote Vincent Mancini, figlio naturale di suo fratello Sonny.', 'https://image.tmdb.org/t/p/w500/lm3pQ2QoQ16pextRsmnUbG2onES.jpg', '2026-09-13T14:48:18.540802', 'Al Pacino, Andy García, Diane Keaton, Talia Shire, Sofia Coppola, Eli Wallach, Joe Mantegna', NULL, NULL, NULL),
(7, 'Il Padrino - Parte II', 1974, 'Francis Ford Coppola', 'Drammatico, Poliziesco', 'Il film sviluppa due linee narrative parallele: da un lato segue la giovinezza di Vito Corleone, dalla fuga dalla Sicilia ai primi del Novecento fino alla sua ascesa come ''Padrino'' a New York; dall''altro racconta le vicende del figlio Michael negli anni ''50, intenzionato ad espandere l''impero di famiglia a Las Vegas e a Cuba, affrontando tradimenti interni, indagini governative e una progressiva disgregazione morale e familiare.', 'https://image.tmdb.org/t/p/w500/8a1lJs7mFyGhGhZZDT1azJUoQiZ.jpg', '2026-09-13T14:48:18.23254', 'Al Pacino, Robert De Niro, Robert Duvall, Diane Keaton, John Cazale, Talia Shire', NULL, NULL, NULL),
(130, 'Love Happens - Qualcosa di speciale (noto anche come Brand New Day)', 2009, 'Brandon Camp', 'Drammatico, Sentimentale', 'Un autore di bestseller sul superamento del lutto, rimasto vedovo, tiene un seminario a Seattle. Qui incontra una fiorista disillusa dall''amore, che lo costringerà a fare i conti con il fatto che non ha ancora realmente superato la morte della moglie.', 'https://image.tmdb.org/t/p/w500/ijRJlhAZ7QMkTIVAUkIY8stWfk1.jpg', '2026-09-19T18:03:10.842143', 'Aaron Eckhart, Jennifer Aniston, Dan Fogler, Martin Sheen, Judy Greer', NULL, NULL, NULL),
(17, 'Bianca come il latte, rossa come il sangue', 2013, 'Giacomo Campiotti', 'Drammatico, Romantico', 'Leo è un sedicenne che vive la scuola e la vita con passione, associando le sue emozioni ai colori: il bianco rappresenta il vuoto e la paura, mentre il rosso è il colore dell''amore e della passione per Beatrice, la ragazza di cui è innamorato. Quando scopre che Beatrice è gravemente malata di leucemia, il mondo di Leo crolla. Nel tentativo di aiutarla e di farla sorridere, il ragazzo intraprende un percorso di crescita personale affrontando la sofferenza, sostenuto dall''amica di sempre Silvia e da un professore di filosofia che lo stimola a trovare il proprio posto nel mondo.', 'https://image.tmdb.org/t/p/w500/eZQFj0tgsErtr6CcIkyLFXGNBGa.jpg', '2026-09-13T14:58:32.437498', 'Filippo Scicchitano, Aurora Ruffino, Gaia Weiss, Luca Argentero', NULL, NULL, NULL),
(20, 'Gladiator', 1992, 'Rowdy Herrington', 'Drammatico', 'Un giovane di Chicago si trasferisce in un quartiere difficile e si ritrova coinvolto nel giro delle scommesse clandestine di pugilato per saldare i debiti del padre. Per uscire dal tunnel dovrà affrontare sul ring il suo amico più caro e un promotore privo di scrupoli.', 'https://image.tmdb.org/t/p/w500/w0YjBWVfu689txEXZG3xa4Aev3i.jpg', '2026-09-13T15:01:44.238371', 'James Marshall, T.E. Russell, Cuba Gooding Jr., Robert Loggia, Brian Dennehy', NULL, NULL, NULL),
(134, 'Rocky III', 1982, 'Sylvester Stallone', 'Drammatico, Sportivo', 'Rocky Balboa, ormai campione del mondo dei pesi massimi e ricco, perde il titolo contro il brutale sfidante Clubber Lang e subisce la dolorosa perdita del suo storico allenatore Mickey. Sarà l''ex rivale Apollo Creed ad aiutarlo a ritrovare la "fame" e lo "sguardo della tigre" per prepararsi alla rivincita.', 'https://image.tmdb.org/t/p/w500/uqw16i2kmwVqkJHzjzbDU4xZ0Pl.jpg', '2026-09-19T22:19:08.502985', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Burgess Meredith, Mr. T, Hulk Hogan', NULL, NULL, NULL),
(137, 'Ronin', 1998, 'John Frankenheimer', 'Azione, Thriller', 'Un gruppo di ex agenti segreti e mercenari provenienti da diversi paesi viene ingaggiato a Parigi per recuperare una misteriosa e pesantemente custodita valigetta. Tra tradimenti, doppi giochi e mozzafiato inseguimenti automobilistici, la squadra dovrà scoprire di chi potersi davvero fidare.', 'https://image.tmdb.org/t/p/w500/AirrhRJjHwytOV0pdLu7YZ4DEyr.jpg', '2026-09-25T20:39:37.027542', 'Robert De Niro, Jean Reno, Natascha McElhone, Stellan Skarsgård, Sean Bean, Jonathan Pryce', NULL, NULL, NULL),
(21, 'Gladiatori di Roma', 2012, 'Iginio Straffi', 'Animazione', 'Rimasto orfano dopo l''eruzione di Pompei, il piccolo Timo viene adottato dal generale Chirone e cresciuto nell''accademia di gladiatori più famosa di Roma. Senza alcuna passione per il combattimento, dovrà trasformarsi in un vero eroe per conquistare il cuore della bella Lucilla.', 'https://image.tmdb.org/t/p/w500/9Qyx97TwsPQ1uR82wwQ2dzY0wOU.jpg', '2026-09-13T15:01:44.534361', 'Luca Argentero, Laura Chiatti, Belén Rodríguez, Massimo Corvo, Fabrizio De Flaviis', NULL, NULL, NULL),
(10, 'Indiana Jones e il tempio maledetto', 1984, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1935, l''archeologo Indiana Jones sfugge a un agguato della malavita a Shanghai e si ritrova precipitato in India insieme alla cantante Willie Scott e al piccolo Short Round. Raggiunto un povero villaggio oppresso dalla sfortuna, accetta di aiutare gli abitanti a recuperare una pietra sacra Sankara rubata e a liberare tutti i bambini rapiti. La sua missione lo porterà al palazzo di Pankot, nascondiglio della spietata setta dei Thuggee, dedita a sacrifici umani e al culto della dea Kali.', 'https://image.tmdb.org/t/p/w500/gpdVNUaa4LhRMLfJOPj1AZdhAZ3.jpg', '2026-09-13T14:53:50.633983', 'Harrison Ford, Kate Capshaw, Ke Huy Quan, Amrish Puri, Roshan Seth', NULL, NULL, NULL),
(14, 'Bianca', 1984, 'Nanni Moretti', 'Commedia, Drammatico, Grottesco', 'Michele Apicella, un giovane e nevrotico professore di matematica con numerose manie ossessive, viene assunto presso l''atipico liceo sperimentale ''Marilyn Monroe''. Michele tende a spiare e giudicare la vita dei suoi vicini e amici, cercando una perfezione ideale nei rapporti umani. Quando inizia una storia d''amore con la nuova collega di francese, Bianca, la sua stabilità mentale viene messa a dura prova. Contemporaneamente, un commissario di polizia indaga su una serie di misteriosi omicidi che colpiscono le persone vicine a Michele.', 'https://image.tmdb.org/t/p/w500/lnXZLkJ3MFgAFAiyVJGfTUykNkU.jpg', '2026-09-13T14:58:31.211468', 'Nanni Moretti, Laura Morante, Roberto Vezzosi, Dario Cantarelli, Vincenzo Salemme', NULL, NULL, NULL),
(28, 'Il gladiatore di Roma', 1962, 'Mario Costa', 'Peplum', 'Nell''antica Roma sotto Caracalla, la giovane erede al trono di Cilicia viene protetta da uno schiavo gladiatore che difenderà la sua vita dai traditori e dai pretendenti al trono.', 'https://image.tmdb.org/t/p/w500/bnYYCgn7hBtV6Xq4PF8GttGMvI3.jpg', '2026-09-13T15:01:46.694395', 'Gordon Scott, Wandisa Guida, Roberto Risso, Eleonora Vargas, Ombretta Colli', NULL, NULL, NULL),
(27, 'Spartacus e i 10 gladiatori', 1964, 'Nick Nostro', 'Peplum', 'Dieci gladiatori inviati per dare la caccia al ribelle Spartacus scoprono la nobiltà della sua causa. Decideranno di unire le forze con gli schiavi in rivolta contro le legioni romane.', 'https://image.tmdb.org/t/p/w500/gZsGyRcXRCICiSlnBfyH5SecIad.jpg', '2026-09-13T15:01:46.378904', 'Dan Vadis, Helga Liné, Ursula Davis, Giovanni Di Benedetto, Giovanni Vari', NULL, NULL, NULL),
(45, 'Agente 007 - Missione Goldfinger', 1964, 'Guy Hamilton', 'Azione, Spionaggio, Avventura', 'L''agente segreto James Bond viene incaricato di indagare sui loschi affari di Auric Goldfinger, un magnate ossessionato dal metallo prezioso. Bond scopre un diabolico piano denominato ''Operazione Grand Slam'': Goldfinger intende far esplodere una bomba atomica all''interno del deposito aureo di Fort Knox per contaminare l''oro degli Stati Uniti e far schizzare alle stelle il valore del proprio monopolio. Tra insidiosi nemici come il letale scagnozzo Oddjob e l''affascinante pilota Pussy Galore, 007 dovrà fare di tutto per sventare il catastrofico piano.', 'https://image.tmdb.org/t/p/w500/aKNFzaqQgPzsGXnsMc4kJH5hFIV.jpg', '2026-09-14T13:48:36.347752', 'Sean Connery, Honor Blackman, Gert Fröbe, Shirley Eaton, Bernard Lee', NULL, NULL, NULL),
(34, 'Il Signore degli Anelli - Le due torri', 2002, 'Peter Jackson', 'Fantasy', 'La Compagnia si è divisa: Frodo e Sam proseguono verso Mordor guidati dalla subdola creatura Gollum, mentre Aragorn, Legolas e Gimli accorrono in aiuto del regno di Rohan. Insieme dovranno affrontare le schiere oscure di Saruman nella leggendaria battaglia del Fosso di Helm.', 'https://image.tmdb.org/t/p/w500/5VTN0pR8gcqV3EPUHHfMGnJYN9L.jpg', '2026-09-13T15:13:21.973278', 'Christopher Guard, William Squire, Michael Scholes, John Hurt, Simon Chandler', NULL, NULL, NULL),
(32, 'Il gladiatore II', 2024, 'Ridley Scott', 'Azione, Drammatico, Storico, Avventura', 'Anni dopo aver assistito alla tragica morte del venerato eroe Massimo Decimo Meridio per mano del suo perfido zio, Lucio si ritrova costretto a fare il suo ingresso nel Colosseo. La sua patria è stata infatti conquistata dai tirannici imperatori che ora governano Roma con il pugno di ferro. Con la rabbia nel cuore e il destino dell''Impero in bilico, Lucio deve scavare nel proprio passato per trovare la forza e l''orgoglio necessari a restituire la gloria di Roma al suo popolo.', 'https://image.tmdb.org/t/p/w500/2cxhvwyEwRlysAmRH4iodkvo0z5.jpg', '2026-09-13T15:10:37.320908', 'Paul Mescal, Pedro Pascal, Denzel Washington, Connie Nielsen, Joseph Quinn, Fred Hechinger', NULL, NULL, NULL),
(29, 'Ursus il gladiatore ribelle', 1962, 'Domenico Paolella', 'Peplum', 'Ursus accetta di combattere come gladiatore per salvare la vita della donna che ama, prigioniera di un governatore crudele. La sua forza sovrumana scatenerà una rivolta nell''arena.', 'https://image.tmdb.org/t/p/w500/hfsSMECtejxQOwJkzE1WjKqMWUw.jpg', '2026-09-13T15:01:46.997779', 'Dan Vadis, Gloria Milland, José Greci, Sergio Ciani, Andrea Aureli', NULL, NULL, NULL),
(35, 'Il Signore degli Anelli - Il ritorno del re', 2003, 'Peter Jackson', 'Fantasy', 'L''epico scontro finale per la salvaguardia della Terra di Mezzo ha inizio. Mentre Aragorn reclami il suo trono e conduce l''esercito dei popoli liberi ai Cancelli Nero per distrarre le armate oscure, Frodo e Sam affrontano il massacrante tratto finale del viaggio verso il Monte Fato.', 'https://image.tmdb.org/t/p/w500/rCzpDGLbOoPwLjy3OAm5NUPOTrC.jpg', '2026-09-13T15:13:22.217261', 'Elijah Wood, Ian McKellen, Viggo Mortensen, Sean Astin, Andy Serkis', NULL, NULL, NULL),
(36, 'Il Signore degli Anelli', 1978, 'Ralph Bakshi', 'Animazione', 'Adattamento animato classico realizzato tramite la tecnica del rotoscopio che ripercorre le vicende della Compagnia dell''Anello. Frodo e i suoi compagni intraprendono un lungo viaggio per sconfiggere l''oscurità che minaccia la Terra di Mezzo.', 'https://image.tmdb.org/t/p/w500/liW0mjvTyLs7UCumaHhx3PpU4VT.jpg', '2026-09-13T15:13:22.520759', 'Christopher Guard, William Squire, Michael Scholes, John Hurt, Simon Chandler', NULL, NULL, NULL),
(33, 'Il Signore degli Anelli - La Compagnia dell''Anello', 2001, 'Peter Jackson', 'Fantasy', 'Un giovane hobbit di nome Frodo Baggins eredita un anello magico di inestimabile potere dal suo zio Bilbo. Per evitare che il Signore Oscuro Sauron lo riconquisti e sottometta la Terra di Mezzo, Frodo deve intraprendere un periglioso viaggio verso il Monte Fato insieme a una variegata compagnia di eroi.', 'https://image.tmdb.org/t/p/w500/6oom5QYQ2yQTMJIbnvbkBL9cHo6.jpg', '2026-09-13T15:13:21.613148', 'Christopher Guard, William Squire, Michael Scholes, John Hurt, Simon Chandler', NULL, NULL, NULL),
(46, 'Casino', 1995, 'Martin Scorsese', 'Crime / Drammatico', 'Sam ''Ace'' Rothstein viene incaricato dalla mafia di gestire il casinò Tangiers a Las Vegas negli anni ''70. La sua gestione efficace viene però minacciata dall''amico d''infanzia e gangster Nikki Santoro e dalla tempestosa relazione con la moglie Ginger. Tra cupidigia, inganni e declino dell''impero mafioso, la storia ripercorre l''ascesa e la caduta dei boss nella capitale del gioco d''azzardo.', 'https://image.tmdb.org/t/p/w500/gziIkUSnYuj9ChCi8qOu2ZunpSC.jpg', '2026-09-14T13:49:13.384199', 'Robert De Niro, Sharon Stone, Joe Pesci, James Woods, Don Rickles', NULL, NULL, NULL),
(25, 'L''ultimo gladiatore', 1964, 'Umberto Lenzi', 'Peplum, Storico, Avventura', 'Nell''antica Roma, oppressa dalla follia e dal dispotismo dell''imperatore Caligola, il valoroso gladiatore Cassio Cherone decide di ribellarsi alla tirannia. Coinvolto negli intrighi di palazzo e nelle congiure senatorie, Cassio affronta pericoli nell''arena e scontri mortali, lottando per rovesciare il sovrano crudele, proteggere la donna che ama e restituire dignità e pace al popolo romano.', 'https://image.tmdb.org/t/p/w500/lSpPctLSS2F0W4XgQCzTWrtEMl9.jpg', '2026-09-13T15:01:45.76594', 'Richard Harrison, Marilù Tolo, Philippe Hersent, Livio Lorenzon, Lisa Gastoni, Gianni Solaro', NULL, NULL, NULL),
(26, 'Il magnifico gladiatore', 1964, 'Alfonso Brescia', 'Peplum', 'Attalo, gladiatore da tutti stimato, si trova vittima degli intrighi di palazzo dell''imperatore Gallieno. Dovrà far valere il suo valore sia nell''arena che contro i cospiratori politicamente corrotti.', 'https://image.tmdb.org/t/p/w500/7iJtohz1AiSKaV8uOp23smvnO3J.jpg', '2026-09-13T15:01:46.066865', 'Mark Forest, Marilù Tolo, Paolo Gozlino, Jolanda Modio, Franco Cobianchi', NULL, NULL, NULL),
(48, 'Sátántangó', 1994, 'Béla Tarr', 'Drammatico', 'In un desolate e piovoso villaggio ungherese dopo la chiusura di una fattoria collettiva, gli abitanti vivono nell''apatia e nel sospetto reciproco. Il presunto ritorno del carismatico Irimiás, ritenuto morto da tutti, riaccende una labile speranza che si trasforma presto in una complessa danza di manipolazione e inganno.', 'https://image.tmdb.org/t/p/w500/y38z0v4HJ12MHiKddLEoFlvPiBt.jpg', '2026-09-14T13:49:44.315657', 'Mihály Víg, Putyi Horváth, Székely B. Miklós, Erika Bók, László feLugossy', NULL, NULL, NULL),
(62, 'The Wolf of Wall Street', 2013, 'Martin Scorsese', 'Biografico / Drammatico / Commedia', 'Jordan Belfort è un giovane e ambizioso broker di New York che fonda la Stratton Oakmont, diventando rapidamente milionario grazie a truffe e speculazioni finanziarie spregiudicate. Immerso in un vortice di edonismo, droga e avidità sfrenata, la sua vita di eccessi attira presto l''attenzione dell''FBI. La sua inarrestabile ascesa nel mondo della finanza rischia così di trasformarsi in una rovinosa e inevitabile caduta.', 'https://image.tmdb.org/t/p/w500/kW9LmvYHAaS9iA0tHmZVq8hQYoq.jpg', '2026-09-15T17:10:35.932269', 'Leonardo DiCaprio, Jonah Hill, Margot Robbie, Matthew McConaughey, Kyle Chandler', NULL, NULL, NULL),
(53, 'Highlander: Endgame', 2000, 'Douglas Aarniokoski', 'Azione / Fantastico', 'Duncan MacLeod e suo cugino Connor uniscono le forze per affrontare Jacob Kell, un malvagio immortale che ha accumulato un potere immenso eliminando centinaia di rivali nel corso dei secoli. Per sconfiggere un nemico apparentemente invincibile, i due guerrieri scozzesi dovranno affrontare il proprio passato e compiere la scelta più difficile della loro vita.', 'https://image.tmdb.org/t/p/w500/8Z8dptJEypuLoOQro1WugD855YE.jpg', '2026-09-14T13:51:54.04989', 'Christopher Lambert, Roxanne Hart, Clancy Brown, Sean Connery, Beatie Edney', NULL, NULL, NULL),
(52, 'Avengers: Endgame', 2019, 'Anthony Russo, Joe Russo', 'Azione, Avventura, Fantascienza', 'Dopo gli eventi devastanti di Avengers: Infinity War, l''universo è in rovina a causa delle azioni di Thanos. Con l''aiuto degli alleati rimasti, gli Avengers superstiti si riuniscono ancora una volta per annullare le azioni del Titano Pazzo. Attraverso un rischioso viaggio nel tempo nel Regno Quantico, il gruppo tenta di recuperare le Gemme dell''Infinito nel passato per riportare in vita tutti coloro che sono scomparsi e ripristinare l''ordine nell''universo.', 'https://image.tmdb.org/t/p/w500/bR8ISy1O9XQxqiy0fQFw2BX72RQ.jpg', '2026-09-14T13:51:52.958142', 'Robert Downey Jr., Chris Evans, Mark Ruffalo, Chris Hemsworth, Scarlett Johansson, Jeremy Renner, Paul Rudd, Josh Brolin', NULL, NULL, NULL),
(55, 'Rocky IV', 1985, 'Sylvester Stallone', 'Drammatico, Sportivo, Azione', 'Rocky Balboa accompagna l''amico fraterno ed ex rivale Apollo Creed in un match di esibizione contro il temibile e glaciale pugile sovietico Ivan Drago. Quando Apollo muore tragicamente sul ring a causa dei colpi brutali di Drago, Rocky decide di vendicare l''amico sfidando il gigante russo a Mosca il giorno di Natale. Per prepararsi, Rocky si sottopone a un durissimo allenamento tra i ghiacci della Siberia, culminando in uno scontro epico che va oltre lo sport, diventando un simbolo della Guerra Fredda.', 'https://image.tmdb.org/t/p/w500/2MHUit4H6OK5adcOjnCN6suCKOl.jpg', '2026-09-14T13:53:58.395769', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Brigitte Nielsen, Dolph Lundgren', NULL, NULL, NULL),
(66, 'Robin Hood - Principe dei ladri', 1991, 'Kevin Reynolds', 'Avventura, Azione, Drammatico', 'Robin di Locksley ritorna in Inghilterra dopo essere fuggito dalla prigionia a Gerusalemme durante le Crociate. Trova la sua terra natale oppressa dal tirannico Sceriffo di Nottingham, che ha fatto assassinare suo padre. Rifugiatosi nella foresta di Sherwood, Robin si unisce a una banda di fuorileggi e, affiancato dal fedele amico saraceno Azeem, assume la guida della ribellione per sconfiggere lo Sceriffo, salvare la bella Lady Marian e restituire la giustizia al popolo oppresso.', 'https://image.tmdb.org/t/p/w500/hbRnWUNJkKKVN5mkcuC5ooqjE4e.jpg', '2026-09-15T18:04:05.742081', 'Kevin Costner, Morgan Freeman, Alan Rickman, Mary Elizabeth Mastrantonio, Christian Slater', NULL, NULL, NULL),
(60, 'Pirati dei Caraibi - Oltre i confini del mare', 2011, 'Rob Marshall', 'Avventura, Azione, Fantastico', 'Jack Sparrow incontra Angelica, una donna del suo passato che lo costringe a imbarcarsi sulla Queen Anne''s Revenge, la nave del temibile pirata Barbanera. Jack si ritrova così coinvolto in una pericolosa ricerca della leggendaria Fonte della Giovinezza, dovendo fare i conti con spietate sirene, zombie e la flotta rivale spagnola e inglese guidata da Barbossa, ora al servizio del Re.', 'https://image.tmdb.org/t/p/w500/keGfSvCmYj7CvdRx36OdVrAEibE.jpg', '2026-09-14T14:11:06.59801', 'Johnny Depp, Penélope Cruz, Ian McShane, Geoffrey Rush, Kevin McNally', NULL, NULL, NULL),
(64, 'La leggenda di Robin Hood', 1938, 'Michael Curtiz, William Keighley', 'Avventura, Azione, Romantico', 'Robin di Locksley, un nobile sassone, si ribella contro l''usurpatore Principe Giovanni, che ha preso il controllo dell''Inghilterra approfittando della prigionia di Re Riccardo Cuor di Leone. Rifugiatosi nella foresta di Sherwood con una banda di fuorilegge, Robin ruba ai ricchi normanni per dare ai poveri sassoni oppressi, conquistando anche il cuore di Lady Marian e lottando per il ritorno del legittimo sovrano.', 'https://image.tmdb.org/t/p/w500/c7LX3GMf9uXQTgVm3uxpm7E6Woc.jpg', '2026-09-15T18:04:05.337906', 'Errol Flynn, Olivia de Havilland, Basil Rathbone, Claude Rains', NULL, NULL, NULL),
(54, 'Rocky', 1976, 'John G. Avildsen', 'Drammatico, Sportivo', 'Rocky Balboa, un pugile di poco conto di Filadelfia che vive riscuotendo crediti per un usuraio locale, ottiene una straordinaria ed inaspettata occasione: sfidare il campione del mondo dei pesi massimi, Apollo Creed. Con il duro allenamento dell''anziano Mickey e il supporto dell''amata Adriana, Rocky cercherà di riscattare la propria vita e dimostrare di non essere solo un fantoccio sul ring.', 'https://image.tmdb.org/t/p/w500/xSI0dbKLDETwhiVUy6hGE8KXUln.jpg', '2026-09-14T13:53:57.043684', 'Sylvester Stallone, Talia Shire, Burt Young, Carl Weathers, Burgess Meredith', NULL, NULL, NULL),
(59, 'Pirati dei Caraibi - Ai confini del mondo', 2007, 'Gore Verbinski', 'Avventura, Azione, Fantastico', 'Il capitano Barbossa, Will Turner e Elizabeth Swann si alleano per liberare Jack Sparrow dalla prigionia nello Scrigno di Davy Jones. Nel frattempo, la Compagnia delle Indie Orientali, guidata da Lord Cutler Beckett e con il controllo dell''Olandese Volante, minaccia di eliminare per sempre la pirateria dai mari.', 'https://image.tmdb.org/t/p/w500/jGWpG4YhpQwVmjyHEGkxEkeRf0S.jpg', '2026-09-14T14:11:06.373565', 'Johnny Depp, Orlando Bloom, Keira Knightley, Geoffrey Rush, Chow Yun-fat, Bill Nighy', NULL, NULL, NULL),
(86, 'Rambo', 1982, 'Ted Kotcheff', 'Azione', 'John Rambo, un reduce della guerra del Vietnam psicologicamente segnato, arriva in una piccola città alla ricerca di un vecchio amico. Ingiustamente perseguitato dallo sceriffo locale, Rambo si rifugia nei boschi scatenando una caccia all''uomo senza tregua.', 'https://image.tmdb.org/t/p/w500/a9sa6ERZCpplbPEO7OMWE763CLD.jpg', '2026-09-16T10:28:13.415074', 'Sylvester Stallone, Brian Dennehy, Richard Crenna', NULL, NULL, NULL),
(2, 'Il Gladiatore', 2000, 'Ridley Scott', 'Storico, Azione, Drammatico', 'Il generale romano Massimo Decimo Meridio viene tradito dal perfido Commodo, figlio dell''imperatore Marco Aurelio, che usurpa il trono e fa sterminare la famiglia di Massimo. Catturato e ridotto in schiavitù, Massimo viene addestrato come gladiatore dal lanista Prossimo. La sua straordinaria abilità nell''arena lo condurrà fino al Colosseo a Roma, dove cercherà la sua vendetta contro il nuovo imperatore.', 'https://image.tmdb.org/t/p/w500/wN2xWp1eIwCKOD0BHTcErTBv1Uq.jpg', '2026-09-13T14:42:52.023756', 'Russell Crowe, Joaquin Phoenix, Connie Nielsen, Oliver Reed, Richard Harris', NULL, NULL, NULL),
(68, 'Robin Hood - L''origine della leggenda', 2018, 'Otto Bathurst', 'Azione, Avventura', 'Tornato in Inghilterra dopo aver combattuto nelle Crociate, il nobile Robin di Loxley scopre che la sua casa è stata confiscata e che la contea di Nottingham è caduta sotto il giogo del corrotto Sceriffo. Insieme a Little John, un comandante moro conosciuto in guerra, Robin decide di combattere le ingiustizie. Addestrato nel combattimento furtivo e nell''uso dell''arco, Robin assume l''identità dell''incappucciato ''Robin Hood'' per rubare il denaro dello Sceriffo, guidare una rivolta popolare e riconquistare il suo amore, Marian.', 'https://image.tmdb.org/t/p/w500/AiRfixFcfTkNbn2A73qVJPlpkUo.jpg', '2026-09-15T18:04:06.155966', 'Taron Egerton, Jamie Foxx, Ben Mendelsohn, Eve Hewson, Jamie Dornan', NULL, NULL, NULL),
(85, '2001: Odissea nello spazio', 1968, 'Stanley Kubrick', 'Fantascienza', 'Un misterioso monolite nero guida ed influenza i passaggi chiave dell''evoluzione umana dalla preistoria al futuro. Nel 2001, una missione spaziale diretta verso Giove a bordo della Discovery One entra in rotta di collisione con la propria intelligenza artificiale, l''infallibile e inquietante computer HAL 9000.', 'https://image.tmdb.org/t/p/w500/ve72VxNqjGM69Uky4WTo2bK6rfq.jpg', '2026-09-16T09:54:13.411935', 'Keir Dullea, Gary Lockwood, William Sylvester', NULL, NULL, NULL),
(73, 'Star Wars: Episodio I - La minaccia fantasma', 1999, 'George Lucas', 'Fantascienza', 'Due cavalieri Jedi scoprono il giovane e straordinariamente dotato Anakin Skywalker mentre tentano di sventare l''invasione del pacifico pianeta Naboo. Nel frattempo, una minaccia creduta estinta da millenni, i Sith, fa la sua ricomparsa.', 'https://image.tmdb.org/t/p/w500/iHitEFiK8udC0GcsWUU6szWzc5K.jpg', '2026-09-15T19:21:49.355409', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness', NULL, NULL, NULL);
INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori", "slug", "backdrop_url", "trailer_url") VALUES
(74, 'Star Wars: Episodio II - L''attacco dei cloni', 2002, 'George Lucas', 'Fantascienza', 'Anakin Skywalker, ormai cresciuto, viene incaricato di proteggere la senatrice Padmé Amidala da una serie di attentati, mentre tra i due sboccia un amore proibito. Nel frattempo, Obi-Wan Kenobi scopre la creazione di un misterioso esercito di cloni pronto a combattere i separatisti.', 'https://image.tmdb.org/t/p/w500/zW4eR9utiKPnTHcIP4xuy0t09nT.jpg', '2026-09-15T19:21:49.562672', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness', NULL, NULL, NULL),
(81, 'Guerre stellari: Episodio VI - Il ritorno dello Jedi', 1983, 'Richard Marquand', 'Fantascienza', 'Luke Skywalker e i suoi compagni salvano Han Solo dalla fortezza del malvagio Jabba the Hutt prima di affrontare la minaccia definitiva dell''Impero. I Ribelli pianificano un attacco coordinato contro una seconda e più potente Morte Nera in costruzione nei pressi della luna boscosa di Endor. Nel frattempo, Luke deve confrontarsi direttamente con l''Imperatore Palpatine e tentare di redimere suo padre Dart Fener.', 'https://image.tmdb.org/t/p/w500/fai0rspsNeJCS69wHNjOdWxcI7P.jpg', '2026-09-15T19:22:13.937672', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness', NULL, NULL, NULL),
(100, 'Nosferatu il vampiro (Nosferatu eine Symphonie des Grauens)', 1922, 'Friedrich Wilhelm Murnau', 'Horror, Espressionismo tedesco', 'Il misterioso Conte Orlok decide di acquistare una casa a Wisborg, portando con sé la peste e il terrore. Il giovane Thomas Hutter e sua moglie Ellen cercheranno di fermare la letale minaccia.', 'https://image.tmdb.org/t/p/w500/zv7J85D8CC9qYagAEhPM63CIG6j.jpg', '2026-09-16T12:04:39.019959', 'Max Schreck, Gustav von Wangenheim, Greta Schröder', NULL, NULL, NULL),
(72, 'Star Wars: Episodio VI - Il ritorno dello Jedi', 1983, 'Richard Marquand', 'Fantascienza', 'I Ribelli intraprendono una missione decisiva per distruggere la seconda Morte Nera e sconfiggere l''Imperatore. Luke affronta per l''ultima volta Darth Vader nel tentativo di redimere il padre caduto nel Lato Oscuro.', 'https://image.tmdb.org/t/p/w500/rMcCqpaWEUBmATmpZilDTKOyVbL.jpg', '2026-09-15T19:21:49.142052', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness', NULL, NULL, NULL),
(75, 'Star Wars: Episodio III - La vendetta dei Sith', 2005, 'George Lucas', 'Fantascienza', 'Le Guerre dei Cloni giungono al termine e il Cancelliere Palpatine seduce Anakin con le promesse del Lato Oscuro. Traditi i Jedi, la Repubblica crolla, dando vita al tirannico Impero Galattico e alla nascita di Darth Vader.', 'https://image.tmdb.org/t/p/w500/xfSAoBEm9MNBjmlNcDYLvLSMlnq.jpg', '2026-09-15T19:21:49.766037', 'Hayden Christensen, Ewan McGregor, Natalie Portman, Ian McDiarmid, Samuel L. Jackson', NULL, NULL, NULL),
(71, 'Star Wars: Episodio V - L''Impero colpisce ancora', 1980, 'Irvin Kershner', 'Fantascienza', 'Mentre l''Impero contrattacca duramente contro l''Alleanza Ribelle, Luke Skywalker inizia l''addestramento Jedi sotto la guida del maestro Yoda. Nel frattempo, i suoi amici vengono braccati da Darth Vader attraverso la galassia.', 'https://image.tmdb.org/t/p/w500/lGJDx7RCgyMMa3owtp150umMnnJ.jpg', '2026-09-15T19:21:48.946346', 'Peter Mayhew, Mark Hamill, Carrie Fisher, Harrison Ford, Anthony Daniels', NULL, NULL, NULL),
(77, 'Star Wars: Gli ultimi Jedi', 2017, 'Rian Johnson', 'Fantascienza', 'Rey sviluppa le sue abilità con l''aiuto di un riluttante Luke Skywalker, tormentato dagli errori passati. Nel frattempo, la Resistenza è sull''orlo dell''annientamento totale sotto il fuoco implacabile della flotta del Primo Ordine.', 'https://image.tmdb.org/t/p/w500/kOVEVeg59E0wsnXmF9nrh6OmWII.jpg', '2026-09-15T19:21:50.17562', 'Mark Hamill, Carrie Fisher, Adam Driver, Daisy Ridley, John Boyega', NULL, NULL, NULL),
(87, 'Rambo 2 - La vendetta', 1985, 'George P. Cosmatos', 'Azione', 'Fatto uscire di prigione per una missione ricognitiva in Vietnam, Rambo ha il compito di fotografare un campo di prigionieri americani. Violando gli ordini ricevuti, il veterano decide di intervenire per liberarli affrontando le forze nemiche.', 'https://image.tmdb.org/t/p/w500/fVwRtWqEPdsCH21BVDGqgkAQcff.jpg', '2026-09-16T10:28:13.617162', 'Sylvester Stallone, Richard Crenna, Charles Napier', NULL, NULL, NULL),
(88, 'Rambo III', 1988, 'Peter MacDonald', 'Azione', 'Ritiratosi in un monastero in Thailandia, Rambo viene a sapere che il suo ex comandante Trautman è stato catturato dai sovietici in Afghanistan. L''ex berretto verde parte da solo per un''audace missione di salvataggio nel territorio nemico.', 'https://image.tmdb.org/t/p/w500/1eSQvGuD25ezKaiaQsyDDG3e9iN.jpg', '2026-09-16T10:28:13.815476', 'Sylvester Stallone, Richard Crenna, Marc de Jonge', NULL, NULL, NULL),
(89, 'John Rambo', 2008, 'Sylvester Stallone', 'Azione', 'Rambo vive isolato nel nord della Thailandia finché un gruppo di missionari non lo ingaggia per guidarli in Birmania. Quando i missionari vengono catturati dalle truppe militari locali, il veterano guida un gruppo di mercenari in una sanguinosa operazione di recupero.', 'https://image.tmdb.org/t/p/w500/3mInub5c8o00H7EJ1TrjAqOzIuc.jpg', '2026-09-16T10:28:14.130412', 'Sylvester Stallone, Julie Benz, Matthew Marsden', NULL, NULL, NULL),
(93, 'Obsession', 1949, 'Edward Dmytryk', 'Thriller', 'Un medico londinese scopre che la moglie lo tradisce e decide di attuare una macabra vendetta. Rapisce l''amante della donna e lo tiene nascosto in un garage abbandonato, pianificando di scioglierlo gradualmente nell''acido.', 'https://image.tmdb.org/t/p/w500/rEOBZMcw29R0kGQJkrUDgtXCU2Z.jpg', '2026-09-16T11:23:04.758701', 'Robert Newton, Sally Gray, Phil Brown', NULL, NULL, NULL),
(98, 'Ben-Hur', 1959, 'William Wyler', 'Storico, Drammatico, Avventura', 'Giuda Ben-Hur, un ricco principe ebreo di Gerusalemme, viene tradito dall''amico d''infanzia Messala e inviato come schiavo sulle galere. Dopo essere sopravvissuto e aver salvato un console romano, torna in patria per vendicarsi sfidando Messala in un''epica corsa con i carri.', 'https://image.tmdb.org/t/p/w500/m4WQ1dBIrEIHZNCoAjdpxwSKWyH.jpg', '2026-09-16T12:02:51.909714', 'Charlton Heston, Jack Hawkins, Haya Harareet, Stephen Boyd, Hugh Griffith', NULL, NULL, NULL),
(99, 'Ben-Hur', 2016, 'Timur Bekmambetov', 'Azione, Avventura, Drammatico', 'Rivisitazione moderna del classico di Lew Wallace: Giuda Ben-Hur viene accusato ingiustamente di tradimento dal fratello adottivo Messala, ufficiale dell''esercito romano. Dopo anni trascorsi in mare come schiavo, torna per cercare la resa dei conti nella grande arena dei carri.', 'https://image.tmdb.org/t/p/w500/c9CoGrBA5yw8A7YBMz0hGzfzpNq.jpg', '2026-09-16T12:02:52.020983', 'Jack Huston, Toby Kebbell, Rodrigo Santoro, Morgan Freeman, Nazanin Boniadi', NULL, NULL, NULL),
(97, 'Ben-Hur: A Tale of the Christ', 1925, 'Fred Niblo', 'Drammatico, Storico', 'Un giovane principe ebreo viene ingiustamente accusato di aver attentato alla vita del governatore romano dal suo amico d''infanzia Messala. Ridotto in schiavitù, cercherà il riscatto e la vendetta.', 'https://image.tmdb.org/t/p/w500/aCohFCJNxPner7VzjzyNN7H8BgV.jpg', '2026-09-16T12:02:51.813455', 'Ramon Novarro, Francis X. Bushman, May McAvoy, Betty Bronson', NULL, NULL, NULL),
(103, 'L''ultimo dei mohicani', 1992, 'Michael Mann', 'Avventura, Storico, Drammatico, Azione', 'Durante la guerra franco-indiana nel 1757, tre cacciatori, tra cui l''inglese adottato dai Mohicani Occhio di Falco, si ritrovano a proteggere le figlie di un colonnello britannico dall''attacco dei feroci Uroni guidati dal vendicativo Magua.', 'https://image.tmdb.org/t/p/w500/qzJMPWRtZveBkxXOv3ucWhoJuyj.jpg', '2026-09-16T13:01:37.493946', 'Daniel Day-Lewis, Madeleine Stowe, Russell Means, Eric Schweig, Jodhi May, Wes Studi', NULL, NULL, NULL),
(102, 'Nosferatu', 2024, 'Robert Eggers', 'Horror, Gotico', 'Una rivisitazione gotica e terrificante della classica leggenda, incentrata sull''ossessione tra una giovane donna tormentata e il mostruoso vampiro infatuato di lei.', 'https://image.tmdb.org/t/p/w500/d0B8xDdqBZlzlPEzES8lu5LlNQn.jpg', '2026-09-16T12:04:39.222453', 'Bill Skarsgård, Nicholas Hoult, Lily-Rose Depp, Willem Dafoe', NULL, NULL, NULL),
(95, 'Obsession', 2026, 'Curry Barker', 'Thriller / Horror', 'Un thriller psicologico ad alta tensione che esplora i confini della mente umana, le relazioni tossiche e le conseguenze estreme del desiderio inconfessabile e del possesso.', 'https://image.tmdb.org/t/p/w500/bRwnj8WEKBCvmfeUNOukJPwB43K.jpg', '2026-09-16T11:30:56.929735', 'Cooper Koch, Charithra Chandran', NULL, NULL, NULL),
(101, 'Nosferatu, il principe della notte (Nosferatu: Phantom der Nacht)', 1979, 'Werner Herzog', 'Horror, Drammatico', 'In questo celebre remake del film di Murnau, il tormentato Conte Dracula viaggia dalla Transilvania a Wismar, diffondendo la peste e cercando ossessivamente l''amore della giovane Lucy Harker.', 'https://image.tmdb.org/t/p/w500/jHKzGYwf7P34vz8MhJBTN6cnaYD.jpg', '2026-09-16T12:04:39.122688', 'Klaus Kinski, Isabelle Adjani, Bruno Ganz', NULL, NULL, NULL),
(96, 'The Backrooms', 2026, 'Kane Parsons', 'Horror, Fantascienza', 'Un giovane precipita accidentalmente oltre i confini della realtà ritrovandosi intrappolato nelle Backrooms, una dimensione parallela costituita da uno sconfinato e inquietante labirinto di uffici vuoti, pareti gialle, moquette umida e luci al neon ronzanti. Mentre tenta disperatamente di trovare una via d''uscita, deve eludere spietate entità ostili che cacciano all''interno di questo spazio liminale.', 'https://image.tmdb.org/t/p/w500/rhGx6E3qRNMgj3i5su2oukNHwIQ.jpg', '2026-09-16T11:55:48.732409', 'Kane Parsons, Ashwin De Silva', NULL, NULL, NULL),
(92, 'Ossessione', 1943, 'Luchino Visconti', 'Drammatico', 'Gino, un girovago senza meta, si innamora ricambiato di Giovanna, una donna insoddisfatta sposata con il proprietario di una trattoria. La passione travolgente tra i due li spinge a eliminare il marito, ma il senso di colpa e il destino distruggeranno il loro legame.', 'https://image.tmdb.org/t/p/w500/dHB6NdsOxO0dc71ciP2hsv3nTPf.jpg', '2026-09-16T11:23:04.558884', 'Clara Calamai, Massimo Girotti, Dhia Cristiani', NULL, NULL, NULL),
(91, 'Obsession - Complesso di colpa', 1976, 'Brian De Palma', 'Thriller', 'Un uomo d''affari di New Orleans subisce un grave trauma quando la moglie e la figlia muoiono durante un tragico tentativo di riscatto. Anni dopo, durante un viaggio a Firenze, incontra una giovane donna identica alla defunta moglie, sprofondando in un vortice di ossessione e inganni.', 'https://image.tmdb.org/t/p/w500/a0bOKTldOJVJivmPNGBHfMYJU9x.jpg', '2026-09-16T11:23:04.358105', 'Cliff Robertson, Geneviève Bujold, John Lithgow', NULL, NULL, NULL),
(94, 'Obsession', 1997, 'Peter Sehr', 'Drammatico', 'Una giovane musicista si trova divisa tra l''amore per due uomini completamente differenti tra loro a Berlino. La situazione sfocia in un complesso triangolo amoroso guidato da passione, insicurezze e scelte dolorose.', 'https://image.tmdb.org/t/p/w500/5Z3Y42Duzwb51kIEeMnkBOgiuLk.jpg', '2026-09-16T11:23:04.967725', 'Daniel Craig, Heike Makatsch, Charles Berling', NULL, NULL, NULL),
(112, '10 Cloverfield Lane', 2016, 'Dan Trachtenberg', 'Thriller, Fantascienza, Drammatico', 'Dopo un incidente d''auto, una giovane donna si risveglia in un bunker sotterraneo insieme a un uomo che sostiene di averle salvato la vita da un attacco chimico apocalittico.', 'https://image.tmdb.org/t/p/w500/q8A39vcBDruhvoDTJd6L8a4lnTi.jpg', '2026-09-17T16:00:28.524163', 'Mary Elizabeth Winstead, John Goodman, John Gallagher Jr.', NULL, NULL, NULL),
(109, 'Ace Ventura - Missione Africa', 1995, 'Steve Oedekerk', 'Commedia, Avventura', 'L''acchiappanimali Ace Ventura si reca in Africa per ritrovare Chicca, un raro pipistrello bianco sacro alla tribù dei Ciakaka, la cui scomparsa rischia di scatenare una guerra tribale.', 'https://image.tmdb.org/t/p/w500/wcinCf1ov2D6M3P7BBZkzQFOiIb.jpg', '2026-09-17T12:47:38.61957', 'Jim Carrey, Ian McNeice, Simon Callow, Maynard Eziashi, Bob Gunton', NULL, NULL, NULL),
(3, 'Cloverfield', 2008, 'Matt Reeves', 'Fantascienza, Horror, Thriller', 'Durante una festa di addio a New York per Rob, un ragazzo in partenza per il Giappone, la città viene scossa dall''attacco improvviso di un mostro gigante di origine sconosciuta. Rob e i suoi amici si avventurano tra le rovine di Manhattan per salvare Beth, la ragazza di cui Rob è innamorato, rimasta intrappolata nel suo appartamento. L''intera vicenda è raccontata attraverso il punto di vista di una videocamera amatoriale che documenta in tempo reale il caos e la sopravvivenza del gruppo.', 'https://image.tmdb.org/t/p/w500/qIegUGJqyMMCRjkKV1s7A9MqdJ8.jpg', '2026-09-13T14:43:24.360095', 'Michael Stahl-David, Odette Yustman, T.J. Miller, Jessica Lucas, Lizzy Caplan, Mike Vogel', NULL, NULL, NULL),
(114, 'Il grande Lebowski', 1998, 'Joel Coen, Ethan Coen', 'Commedia, Noir', 'Jeffrey ''Drugo'' Lebowski, un fannullone pacifista di Los Angeles, viene scambiato per un miliardario suo omonimo. Dopo che dei sicari urinano sul suo tappeto preferito, Drugo si mette alla ricerca di un risarcimento, finendo invischiato in un bizzarro mistero tra rapimenti e nichilisti.', 'https://image.tmdb.org/t/p/w500/rRwaCTF777WaBlrVxtuBic43oqC.jpg', '2026-09-17T16:06:11.675105', 'Jeff Bridges, John Goodman, Julianne Moore, Steve Buscemi, John Turturro', NULL, NULL, NULL),
(110, 'Braveheart - Cuore impavido', 1995, 'Mel Gibson', 'Storico, Drammatico, Azione, Biografico', 'Nel XIII secolo, dopo l''uccisione della sua amata da parte dei soldati inglesi, il patriota scozzese William Wallace guida una sanguinosa ribellione contro il tirannico re Edoardo I d''Inghilterra per conquistare la libertà della Scozia.', 'https://image.tmdb.org/t/p/w500/or1gBugydmjToAEq7OZY0owwFk.jpg', '2026-09-17T13:02:53.469105', 'Mel Gibson, Sophie Marceau, Patrick McGoohan, Catherine McCormack, Angus Macfadyen', NULL, NULL, NULL),
(104, 'Coyote vs. Acme', 2026, 'Dave Green', 'Animazione, Commedia, Avventura', 'Wile E. Coyote decide di fare causa alla Acme Corporation per via dei suoi prodotti costantemente difettosi. Per farlo, assume un avvocato umano di scarso successo che si ritroverà a rappresentarlo in tribunale contro il potente CEO della Acme.', 'https://image.tmdb.org/t/p/w500/kYDCl2y0VPvhT5eYWbMRInPoB03.jpg', '2026-09-16T16:15:06.745926', 'Will Forte, John Cena, Lana Condor', NULL, NULL, NULL),
(108, 'La fine di Oak Street', 2026, 'David Robert Mitchell', 'Thriller, Mistero', 'In una tranquilla e apparentemente perfetta via residenziale chiamata Oak Street, una serie di eventi inspiegabili e sparizioni misteriose scatena la paranoia tra i residenti, costringendo una madre a fare i conti con un oscuro segreto del passato per salvare la sua famiglia.', 'https://image.tmdb.org/t/p/w500/hkPxuAMEqIqo1HCtIi4sqx0GRuP.jpg', '2026-09-17T11:15:13.20051', 'Anne Hathaway, Ewan McGregor', NULL, NULL, NULL),
(117, 'L''attimo fuggente', 1989, 'Peter Weir', 'Drammatico', 'In un rigido collegio maschile del Vermont nel 1959, l''arrivo di un nuovo professore di letteratura, John Keating, sconvolge le vite degli studenti. Con i suoi metodi d''insegnamento anticonformisti, Keating insegna ai ragazzi ad amare la poesia, a pensare con la propria testa e a cogliere l''attimo.', 'https://image.tmdb.org/t/p/w500/erzbMlcNHOdx24AXOcn2ZKA7R1q.jpg', '2026-09-18T06:39:52.384946', 'Robin Williams, Ethan Hawke, Robert Sean Leonard, Josh Charles, Gale Hansen', NULL, NULL, NULL),
(78, 'Star Wars: L''ascesa di Skywalker', 2019, 'J.J. Abrams', 'Fantascienza, Avventura, Azione', 'Un anno dopo gli eventi de ''Gli ultimi Jedi'', i sopravvissuti della Resistenza affrontano ancora una volta il Primo Ordine. Rey, Finn e Poe Dameron guidano la battaglia finale contro il Leader Supremo Kylo Ren e il redivivo Imperatore Palpatine, giungendo alla conclusione della storica saga degli Skywalker.', 'https://image.tmdb.org/t/p/w500/3drtqLOARQEuFgEmGRlMlWpV3Eb.jpg', '2026-09-15T19:21:50.386913', 'Daisy Ridley, Adam Driver, John Boyega, Oscar Isaac, Carrie Fisher, Mark Hamill, Ian McDiarmid, Billy Dee Williams, Lupita Nyong''o, Domhnall Gleeson', NULL, NULL, NULL),
(115, 'Pulp Fiction', 1994, 'Quentin Tarantino', 'Crime, Drammatico', 'Le vite di due killer della mafia, della moglie del loro capo, di un pugile in fuga e di una coppia di rapinatori si intrecciano in una serie di bizzarri e drammatici eventi a Los Angeles.', 'https://image.tmdb.org/t/p/w500/vQWk5YBFWF4bZaofAbv0tShwBvQ.jpg', '2026-09-17T17:53:00.977038', 'John Travolta, Samuel L. Jackson, Uma Thurman, Bruce Willis, Harvey Keitel, Tim Roth', NULL, NULL, NULL),
(107, 'Oak Street', 2026, 'Marcus Thorne', 'Thriller psicologico', 'Un intenso thriller psicologico ambientato in una tranquilla periferia americana. Quando un''intera famiglia scompare misteriosamente dal civico 42 di Oak Street senza lasciare alcuna traccia, un investigatore in pensione decide di condurre un''indagine autonoma. Con il passare dei giorni, l''uomo porterà alla luce una complessa rete di oscuri segreti e menzogne sepolte da decenni all''interno dell''apparentemente impeccabile comunità locale.', 'https://image.tmdb.org/t/p/w500/3iJpc2rV8uN434wdDTJBE2PQwvI.jpg', '2026-09-17T11:04:33.386995', 'Elena Rostova, David Miller, Sarah Jenkins', NULL, NULL, NULL),
(111, 'Titanic', 1997, 'James Cameron', 'Drammatico, Romance', 'Un giovane artista di umili origini e una ricca nobildonna promessa sposa si innamorano a bordo del transatlantico Titanic durante il suo tragico viaggio inaugurale nel 1912.', 'https://image.tmdb.org/t/p/w500/9xjZS2rlVxm8SFx8kPC3aIGCOYQ.jpg', '2026-09-17T13:06:24.095738', 'Leonardo DiCaprio, Kate Winslet, Billy Zane, Kathy Bates, Frances Fisher', NULL, NULL, NULL),
(160, 'Il cavaliere oscuro - Il ritorno', 2012, 'Christopher Nolan', 'Azione, Thriller, Fantascienza', 'Otto anni dopo la morte di Harvey Dent, Gotham City vive un periodo di pace grazie alle leggi speciali del Decreto Dent. Tuttavia, l''arrivo in città di Bane, un terrorista spietato e mascherato, e della misteriosa scassinatrice Selina Kyle, costringe un Bruce Wayne ormai ritirato e debilitato a indossare nuovamente il mantello di Batman per affrontare la minaccia definitiva alla sua città.', 'https://image.tmdb.org/t/p/w500/hr0L2aueqlP2BYUblTTjmtn0hw4.jpg', '2026-09-30T18:57:43.911449', 'Christian Bale, Tom Hardy, Anne Hathaway, Michael Caine, Gary Oldman, Marion Cotillard, Joseph Gordon-Levitt, Morgan Freeman', NULL, NULL, NULL),
(11, 'Indiana Jones e l''ultima crociata', 1989, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1938, l''archeologo Indiana Jones viene contattato dal magnate Walter Donovan per ritrovare il Santo Graal, la coppa che donerebbe la vita eterna. L''incarico assume una valenza personale quando Indy apprende che il precedente capo della spedizione, misteriosamente scomparso, è suo padre, il professor Henry Jones Sr., uno studioso da sempre ossessionato dalla reliquia. Raggiunta Venezia con l''aiuto dell''affascinante dottoressa Elsa Schneider, Indy ritrova il diario del genitore e scopre che l''uomo è tenuto prigioniero dai nazisti in un castello al confine tra Germania e Austria. Dopo aver liberato il padre, padre e figlio fuggono attraverso l''Europa e il Medio Oriente, affrontando tradimenti e letali trappole millenarie all''interno del tempio segreto di Alessandretta per impedire a Hitler di impadronirsi del potere del Graal.', 'https://image.tmdb.org/t/p/w500/sizg1AU8f8JDZX4QIgE4pjUMBvx.jpg', '2026-09-13T14:53:51.047148', 'Harrison Ford, Sean Connery, Alison Doody, Denholm Elliott, John Rhys-Davies, Julian Glover', NULL, NULL, NULL),
(12, 'Indiana Jones e il regno del teschio di cristallo', 2008, 'Steven Spielberg', 'Avventura, Azione', 'Nel 1957, in piena Guerra Fredda, l''anziano archeologo Indiana Jones viene rapito insieme al collega George McHale da agenti sovietici guidati dalla spietata Irina Spalko. Costretto ad aiutarli a penetrare in un magazzino segreto nell''Area 51 per recuperare i resti mummificati di un essere extraterrestre, Indy riesce a fuggire. Poco dopo viene avvicinato dal giovane ribelle Mutt Williams, il quale gli chiede aiuto per trovare il professor Harold Oxley e sua madre, misteriosamente rapiti in Perù. I due si mettono sulle tracce di un leggendario teschio di cristallo dai poteri sconosciuti, finendo per scontrarsi nuovamente con i sovietici lungo una pericolosa spedizione nella giungla amazzonica alla volta della mitica città di Akator.', 'https://image.tmdb.org/t/p/w500/56As6XEM1flWvprX4LgkPl8ii4K.jpg', '2026-09-13T14:53:51.55355', 'Harrison Ford, Cate Blanchett, Shia LaBeouf, Karen Allen, Ray Winstone, John Hurt', NULL, NULL, NULL),
(162, 'The Truman Show', 1998, 'Peter Weir', 'Drammatico, Fantascienza, Commedia', 'Truman Burbank è un uomo apparentemente comune che vive in una tranquilla cittadina isolana. In realtà, la sua intera vita è uno show televisivo trasmesso in diretta mondiale 24 ore su 24, popolato da attori e scenografie, a sua totale insaputa. Quando inizia a notare delle anomalie, Truman decide di scoprire la verità e fuggire.', 'https://image.tmdb.org/t/p/w500/vuza0WqY239yBXOadKlGwJsZJFE.jpg', '2026-09-30T19:53:15.331789', 'Jim Carrey, Laura Linney, Ed Harris, Noah Emmerich, Natascha McElhone', NULL, NULL, NULL),
(166, 'Il momento di uccidere', 1996, 'Joel Schumacher', 'Drammatico, Thriller', 'In una cittadina del Mississippi, un operaio afroamericano uccide i due uomini bianchi che hanno brutalmente violentato la sua figlioletta di dieci anni. Un giovane e ambizioso avvocato bianco decide di assumere la sua difesa, affrontando un processo ad altissima tensione razziale che risveglia le violenze del Ku Klux Klan.', 'https://image.tmdb.org/t/p/w500/w8UCke112E9jrhjKcwG32kyhTx5.jpg', '2026-10-03T07:51:04.334558', 'Matthew McConaughey, Sandra Bullock, Samuel L. Jackson, Kevin Spacey, Ashley Judd', NULL, NULL, NULL),
(167, 'Marty Supreme', 2025, 'Josh Safdie', 'Biografico, Drammatico, Sportivo', 'Liberamente ispirato alla vita del celebre e non convenzionale giocatore di tennistavolo Marty Reisman, il film racconta le vicende, le scommesse e l''ascesa di un eccentrico campione di ping pong nell''America degli anni Cinquanta.', 'https://image.tmdb.org/t/p/w500/lYWEXbQgRTR4ZQleSXAgRbxAjvq.jpg', '2026-10-03T13:16:07.853445', 'Timothée Chalamet, Gwyneth Paltrow, Tyler, The Creator, Odessa A''zion, Penn Jillette', NULL, NULL, NULL),
(168, 'Non è un paese per vecchi', 2007, 'Joel Coen, Ethan Coen', 'Thriller, Drammatico, Crime', 'Nel Texas del 1980, Llewelyn Moss si imbatte nei resti di uno scambio di droga finito male e decide di scappare con una valigetta contenente due milioni di dollari. Sulle sue tracce si mette Anton Chigurh, uno spietato e metodico killer psicopatico armato di un fucile da macello, mentre l''anziano sceriffo Ed Tom Bell cerca disperatamente di salvare Moss e riflette sull''inarrestabile evoluzione della violenza nel mondo moderno.', 'https://image.tmdb.org/t/p/w500/6d5XOczc226jECq0LIX0siKtgHR.jpg', '2026-10-03T13:23:23.059339', 'Tommy Lee Jones, Javier Bardem, Josh Brolin, Woody Harrelson, Kelly Macdonald', NULL, NULL, NULL),
(169, 'Full Metal Jacket', 1987, 'Stanley Kubrick', 'Drammatico, Guerra', 'Durante la guerra del Vietnam, un gruppo di reclute dei Marines affronta un disumanizzante e brutale addestramento nel campo di Parris Island, sotto la guida dello spietato sergente Hartman. Successivamente, il soldato Joker, diventato giornalista militare, viene inviato al fronte durante l''offensiva del Têt, toccando con mano la follia e la crudeltà del conflitto.', 'https://image.tmdb.org/t/p/w500/kMKyx1k8hWWscYFnPbnxxN4Eqo4.jpg', '2026-10-03T13:27:20.929286', 'Matthew Modine, Vincent D''Onofrio, R. Lee Ermey, Adam Baldwin, Arliss Howard', NULL, NULL, NULL),
(170, 'Independence Day', 1996, 'Roland Emmerich', 'Fantascienza, Azione', 'Alla vigilia del 4 luglio, enormi astronavi alieni posizionano sopra le principali metropoli della Terra e scatenano un attacco devastante. Un gruppo di sopravvissuti, tra cui un pilota di caccia della Marina e uno scienziato esperto in telecomunicazioni, elabora un piano disperato per sconfiggere gli invasori e salvare l''umanità dall''estinzione.', 'https://image.tmdb.org/t/p/w500/p0BPQGSPoSa8Ml0DAf2mB2kCU0R.jpg', '2026-10-03T15:02:29.959341', 'Will Smith, Bill Pullman, Jeff Goldblum, Mary McDonnell, Judd Hirsch', NULL, NULL, NULL),
(174, 'Il primo re', 2019, 'Matteo Rovere', 'Drammatico, Storico, Azione', 'Nell''VIII secolo a.C., i fratelli pastori Romolo e Remo vengono travolti dall''esondazione del Tevere e fatti prigionieri dagli abitanti di Alba Longa. Riusciti a fuggire guidando una rivolta insieme ad altri prigionieri, i due intraprendono un viaggio guidati da Remo, che sfida la volontà degli dei finendo per scontrarsi tragicamente con Romolo, destinato a fondare la città di Roma.', 'https://image.tmdb.org/t/p/w500/dqBU63M3cKy7pfVsmhrbgY5X8iv.jpg', '2026-10-05T17:14:16.232927', 'Alessandro Borghi, Alessio Lapice, Fabricio Rongione, Massimiliano Rossi', NULL, NULL, NULL),
(176, 'The Untouchables - Gli intoccabili', 1987, 'Brian De Palma', 'Crimine, Drammatico, Thriller', 'Durante il periodo del proibizionismo a Chicago, l''agente federale Eliot Ness crea una squadra speciale di uomini incorruttibili per fermare l''impero criminale del celebre boss mafioso Al Capone.', 'https://image.tmdb.org/t/p/w500/tPq0R4jTO4Ey8ZspFaWK9wGA4Ls.jpg', '2026-10-06T18:42:24.296083', 'Kevin Costner, Sean Connery, Robert De Niro, Andy Garcia, Charles Martin Smith', NULL, NULL, NULL),
(178, 'King Kong (King Kong)', 1933, 'Merian C. Cooper, Ernest B. Schoedsack', 'Avventura, Fantastico', 'Una troupe cinematografica si avventura su una misteriosa isola sconosciuta, Skull Island, dove scopre un gorilla gigante venerato come un dio dai nativi. La creatura si invaghisce dell''attrice Ann Darrow, ma viene catturata e portata a New York per essere esibita al pubblico.', 'https://image.tmdb.org/t/p/w500/lHlnxKL5GbgRibyRFI7n1Ey850i.jpg', '2026-10-06T19:12:53.048706', 'Fay Wray, Robert Armstrong, Bruce Cabot', NULL, NULL, NULL),
(180, 'King Kong (King Kong)', 2005, 'Peter Jackson', 'Avventura, Fantastico, Azione', 'Nel 1933, un regista di spettacoli sull''orlo del fallimento convince una troupe e una giovane attrice a salpare verso l''esotica e pericolosa Isola del Teschio. Lì si scontreranno con creature preistoriche e con King Kong, un gorilla gigantesco che svilupperà un profondo legame con la donna.', 'https://image.tmdb.org/t/p/w500/6a2HY6UmD7XiDD3NokgaBAXEsD2.jpg', '2026-10-06T19:12:53.434212', 'Naomi Watts, Jack Black, Adrien Brody', NULL, NULL, NULL),
(179, 'King Kong (King Kong)', 1976, 'John Guillermin', 'Avventura, Fantastico, Azione', 'Una compagnia petrolifera organizza una spedizione su un''isola perennemente avvolta dalla nebbia. Qui trovano una gigantesca creatura antropomorfa che si invaghisce di una naufraga. Il gorilla viene catturato per scopi pubblicitari e portato nella metropoli di New York.', 'https://image.tmdb.org/t/p/w500/paYKhEwUaxKA05vmOfU7FlleTln.jpg', '2026-10-06T19:12:53.233287', 'Jeff Bridges, Jessica Lange, Charles Grodin', NULL, NULL, NULL),
(184, 'Lo Hobbit - La battaglia delle cinque armate (The Hobbit: The Battle of the Five Armies)', 2014, 'Peter Jackson', 'Fantastico, Avventura, Azione', 'Mentre Smaug scatena la sua ira su Pontelagolungo, nani, elfi, umani e orchi si scontrano in una titanica battaglia ai piedi della Montagna Solitaria per il controllo del tesoro di Erebor.', 'https://image.tmdb.org/t/p/w500/xT98tLqatZPQApyRmlPL12LtiWp.jpg', '2026-10-09T15:04:32.343493', 'Martin Freeman, Ian McKellen, Richard Armitage, Evangeline Lilly, Luke Evans', NULL, NULL, NULL),
(181, 'Lo Hobbit (The Hobbit)', 1977, 'Arthur Rankin Jr., Jules Bass', 'Animazione, Fantastico, Avventura', 'Un pacifico hobbit di nome Bilbo Baggins viene reclutato dal mago Gandalf e da una compagnia di nani per recuperare un tesoro custodito dal drago Smaug.', 'https://image.tmdb.org/t/p/w500/2ohvyMPhvjftLrM6S6Ljr6QrL0u.jpg', '2026-10-09T15:04:31.981634', 'Orson Bean, Richard Boone, Hans Conried, John Huston', NULL, NULL, NULL),
(182, 'Lo Hobbit - Un viaggio inaspettato (The Hobbit: An Unexpected Journey)', 2012, 'Peter Jackson', 'Fantastico, Avventura', 'Bilbo Baggins viene convinto dal mago Gandalf a unirsi a tredici nani guidati da Thorin Scudodiquercia in un''epica impresa per riconquistare il regno perduto di Erebor dal drago Smaug.', 'https://image.tmdb.org/t/p/w500/yHA9Fc37VmpUA5UncTxxo3rTGVA.jpg', '2026-10-09T15:04:32.122765', 'Martin Freeman, Ian McKellen, Richard Armitage, Ken Stott', NULL, NULL, NULL),
(183, 'Lo Hobbit - La desolazione di Smaug (The Hobbit: The Desolation of Smaug)', 2013, 'Peter Jackson', 'Fantastico, Avventura', 'Bilbo Baggins e la compagnia di nani proseguono il loro viaggio verso la Montagna Solitaria, affrontando pericoli come ragni giganti, elfi silvani e infine il temibile drago Smaug.', 'https://image.tmdb.org/t/p/w500/xQYiXsheRCDBA39DOrmaw1aSpbk.jpg', '2026-10-09T15:04:32.239062', 'Martin Freeman, Ian McKellen, Richard Armitage, Orlando Bloom, Evangeline Lilly', NULL, NULL, NULL),
(185, 'Avvenne domani (It Happened Tomorrow)', 1944, 'René Clair', 'Commedia, Fantastico', 'Un giovane giornalista riceve da un anziano archivista defunto copie del giornale del giorno successivo. Grazie a questa straordinaria opportunità, riesce a realizzare scoop sensazionali, ma le cose si complicano quando legge la notizia della propria morte imminente.', 'https://image.tmdb.org/t/p/w500/byWjI8SYnATh0OdnaCCKhO9nY0R.jpg', '2026-10-09T15:06:19.335568', 'Dick Powell, Linda Darnell, Jack Oakie, Edgar Kennedy, John Philliber', NULL, NULL, NULL),
(187, 'Always (Ojik geudaeman)', 2011, 'Song Il-gon', 'Drammatico, Romantico', 'Un ex pugile dal passato tormentato, che ora lavora come guardiano di un parcheggio, incontra una ragazza non vedente ma piena di vitalità. Tra i due nasce un profondo legame d''amore, ma il passato dell''uomo tornerà a minacciare la loro felicità e la vista della donna.', 'https://image.tmdb.org/t/p/w500/7PaCGnjY87sc9088zxFf34Tamcz.jpg', '2026-10-09T15:11:20.402337', 'So Ji-sub, Han Hyo-joo, Kang Shin-il, Park Chul-min', NULL, NULL, NULL),
(186, 'Always - Per sempre (Always)', 1989, 'Steven Spielberg', 'Drammatico, Fantastico, Romantico', 'Un audace pilota di aerei antincendio muore in un incidente di volo, ma ritorna sulla Terra sotto forma di spirito guida per aiutare un giovane pilota alle prime armi e vegliare sulla donna che amava, faticando ad accettare che lei debba rifarsi una vita senza di lui.', 'https://image.tmdb.org/t/p/w500/r7LTwkgqUPPABnHpxceVylMf8M0.jpg', '2026-10-09T15:11:20.329203', 'Richard Dreyfuss, Holly Hunter, John Goodman, Audrey Hepburn, Brad Johnson', NULL, NULL, NULL),
(188, 'Always', 1985, 'Henry Jaglom', 'Commedia, Drammatico', 'Un regista e la sua ex moglie trascorrono insieme il fine settimana del Giorno dell''Indipendenza per formalizzare il loro divorzio, ma la convivenza temporanea riaccende vecchi sentimenti e costringe entrambi a confrontarsi con i motivi della fine del loro matrimonio.', 'https://image.tmdb.org/t/p/w500/rCYAMewiNpV6gabIK7x1ee141Y8.jpg', '2026-10-09T15:11:20.490167', 'Henry Jaglom, Patrice Townsend, Joanna Frank, Alan Rachins', NULL, NULL, NULL),
(189, 'Harry, ti presento Sally... (When Harry Met Sally...)', 1989, 'Rob Reiner', 'Commedia, Romantico', 'Harry Burns e Sally Albright si incontrano per la prima volta nel 1977 durante un viaggio in auto da Chicago a New York. Nel corso di dodici anni si ritrovano casualmente più volte, sviluppando una profonda amicizia che mette alla prova la teoria di Harry secondo cui un uomo e una donna non possono essere amici senza che il sesso si metta di mezzo.', 'https://image.tmdb.org/t/p/w500/rFOiFUhTMtDetqCGClC9PIgnC1P.jpg', '2026-10-09T15:26:15.168656', 'Billy Crystal, Meg Ryan, Carrie Fisher, Bruno Kirby', NULL, NULL, NULL),
(192, 'Il tempo delle mele 3 (L''étudiante)', 1988, 'Claude Pinoteau', 'Commedia, Sentimentale, Drammatico', 'Valentine è una studentessa universitaria determinata a superare i suoi esami di abilitazione all''insegnamento. La sua vita rigorosa viene sconvolta dall''incontro con Ned, un musicista jazz con ritmi di vita opposti ai suoi.', 'https://image.tmdb.org/t/p/w500/tDx9zW0Edb83qh9PAGrgP3Zh9RP.jpg', '2026-10-09T15:46:43.658535', 'Sophie Marceau, Vincent Lindon, Élisabeth Vitali, Jean-Claude Leguay', NULL, NULL, NULL),
(190, 'Il tempo delle mele (La Boum)', 1980, 'Claude Pinoteau', 'Commedia, Sentimentale, Drammatico', 'La quattordicenne Vic affronta i primi amori, le prime feste e le difficoltà dell''adolescenza nella Parigi degli anni ''80, mentre i suoi genitori attraversano una profonda crisi coniugale.', 'https://image.tmdb.org/t/p/w500/usGV1Q7KWR0Uq4dOIppGZ0ba8kz.jpg', '2026-10-09T15:46:43.450525', 'Sophie Marceau, Claude Brasseur, Brigitte Fossey, Denise Grey, Alexandre Sterling', NULL, NULL, NULL),
(191, 'Il tempo delle mele 2 (La Boum 2)', 1982, 'Claude Pinoteau', 'Commedia, Sentimentale', 'Vic ha ormai sedici anni e, di ritorno da un viaggio, incontra il giovane Philippe. Tra i due nasce una romantica storia d''amore che la porterà a confrontarsi con nuove gelosie e le prime vere scelte della maturità.', 'https://image.tmdb.org/t/p/w500/pbkccDoxH1H1VdqWcQYycZxHTIK.jpg', '2026-10-09T15:46:43.547859', 'Sophie Marceau, Claude Brasseur, Brigitte Fossey, Pierre Cosso, Lambert Wilson, Denise Grey', NULL, NULL, NULL),
(194, 'L''avvocato del diavolo (The Devil''s Advocate)', 1997, 'Taylor Hackford', 'Thriller, Drammatico, Horror', 'Un giovane e imbattuto avvocato della Florida viene ingaggiato da un imponente studio legale di New York. L''uomo si rende presto conto che il suo carismatico capo, John Milton, e la societa stessa nascondono un''oscura origine demoniaca.', 'https://image.tmdb.org/t/p/w500/5ZzBGpxy55OQzHxKVY11IpY6a0o.jpg', '2026-10-09T16:27:56.501666', 'Keanu Reeves, Al Pacino, Charlize Theron, Jeffrey Jones', NULL, NULL, NULL),
(195, 'Interceptor (Mad Max)', 1979, 'George Miller', 'Azione, Fantascienza, Thriller', 'In un''Australia distopica e violenta al collasso sociale, il poliziotto Max Rockatansky cerca vendetta contro una spietata banda di motociclisti che ha sterminato la sua famiglia.', 'https://image.tmdb.org/t/p/w500/5LrI4GiCSrChgkdskVZiwv643Kg.jpg', '2026-10-09T18:15:32.012949', 'Mel Gibson, Joanne Samuel, Hugh Keays-Byrne, Steve Bisley, Tim Burns', NULL, NULL, NULL),
(193, 'L''avvocato del diavolo (Des Teufels Advokat)', 1977, 'Guy Green', 'Drammatico', 'Un sacerdote affetto da un male incurabile viene inviato in un piccolo paese della Calabria per indagare sulla vita e sui presunti miracoli di un uomo giustiziato nel 1944.', 'https://image.tmdb.org/t/p/w500/AbPgcdruJ9ZfNOMWOf1kpyjCUKE.jpg', '2026-10-09T16:27:56.404287', 'John Mills, Stéphane Audran, Jason Miller, Timothy West', NULL, NULL, NULL),
(199, 'Furiosa: A Mad Max Saga', 2024, 'George Miller', 'Azione, Fantascienza, Avventura', 'Rapita da bambina dal Luogo Verde delle Molte Madri e finita nelle mani della brutale Orda di Motociclisti guidata dal Signore della Guerra Dementus, la giovane Furiosa combatte per anni per sopravvivere e trovare la via di casa.', 'https://image.tmdb.org/t/p/w500/iADOJ8Zymht2JPMoy3R7xceZprc.jpg', '2026-10-09T18:15:32.468179', 'Anya Taylor-Joy, Chris Hemsworth, Tom Burke, Alyla Browne, Lachy Hulme', NULL, NULL, NULL),
(198, 'Mad Max: Fury Road', 2015, 'George Miller', 'Azione, Fantascienza, Avventura', 'In fuga attraverso le distese desertiche controllate dal tiranno Immortan Joe, Max unisce le forze con l''Imperatrice Furiosa per scortare cinque donne verso la libertà a bordo di una potente autocisterna.', 'https://image.tmdb.org/t/p/w500/ulcAi4dKpAjHwYGS08vNyx9H6I9.jpg', '2026-10-09T18:15:32.314993', 'Tom Hardy, Charlize Theron, Nicholas Hoult, Hugh Keays-Byrne, Rosie Huntington-Whiteley', NULL, NULL, NULL),
(197, 'Mad Max oltre la sfera del tuono (Mad Max Beyond Thunderdome)', 1985, 'George Miller, George Ogilvie', 'Azione, Fantascienza, Avventura', 'Esiliato dall''avida dominatrice della città di Bartertown dopo essersi rifiutato di uccidere un gladiatore, Max viene salvato da una tribù di bambini sopravvissuti a un incidente aereo che lo credono il loro salvatore.', 'https://image.tmdb.org/t/p/w500/jJlxcEVVUHnrUeEkQ0077VeHQpb.jpg', '2026-10-09T18:15:32.209222', 'Mel Gibson, Tina Turner, Bruce Spence, Frank Thring, Angelo Rossitto', NULL, NULL, NULL),
(196, 'Interceptor - Il guerriero della strada (Mad Max 2)', 1981, 'George Miller', 'Azione, Fantascienza, Avventura', 'Divenuto un vagabondo solitario nelle desolate terre post-apocalittiche, Max accetta di difendere una comunità assediata che gestisce una preziosa raffineria di petrolio da un gruppo di predoni sanguinari.', 'https://image.tmdb.org/t/p/w500/l1KVEhkGDpWRzQ0VqIhZqDDuOim.jpg', '2026-10-09T18:15:32.117824', 'Mel Gibson, Bruce Spence, Michael Preston, Max Phipps, Vernon Wells', NULL, NULL, NULL),
(200, 'Quel pomeriggio di un giorno da cani (Dog Day Afternoon)', 1975, 'Sidney Lumet', 'Drammatico, Thriller, Biografico', 'A New York, tre rapinatori poco esperti tentano di svaligiare una filiale bancaria in un torrido pomeriggio estivo. Quando il colpo fallisce, la situazione si trasforma in un lungo assedio con ostaggi che cattura l''attenzione della polizia e dei media dell''intera nazione.', 'https://image.tmdb.org/t/p/w500/mavrhr0ig2aCRR8d48yaxtD5aMQ.jpg', '2026-10-09T21:17:12.809779', 'Al Pacino, John Cazale, Charles Durning, Chris Sarandon', NULL, NULL, NULL),
(201, 'Soldato blu (Soldier Blue)', 1970, 'Ralph Nelson', 'Western/Drammatico', 'Dopo un massacro compiuto dai Cheyenne, gli unici due sopravvissuti, una giovane donna bianca che ha vissuto a lungo con i nativi e un giovane soldato idealista, intraprendono un difficile viaggio per raggiungere la salvezza. Lungo il cammino, si scontreranno con le rispettive visioni del mondo, fino ad assistere al brutale e tragico massacro di un villaggio indiano inerme da parte dell''esercito statunitense.', 'https://image.tmdb.org/t/p/w500/2fRfVQpdrjAhvxwytG0scOqdQOJ.jpg', '2026-10-09T21:22:31.989748', 'Candice Bergen, Peter Strauss, Donald Pleasence, John Anderson, Jorge Rivero', NULL, NULL, NULL),
(206, 'Hunger Games - La ballata dell''usignolo e del serpente (The Hunger Games: The Ballad of Songbirds & Snakes)', 2023, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Decenni prima di diventare il tirannico presidente di Panem, il diciottenne Coriolanus Snow viene assegnato come mentore a Lucy Gray Baird, il tributo del Distretto 12 per i decimi Hunger Games.', 'https://image.tmdb.org/t/p/w500/mBaXZ95R2OxueZhvQbcEWy2DqyO.jpg', '2026-10-11T16:25:26.977381', 'Tom Blyth, Rachel Zegler, Peter Dinklage, Viola Davis, Jason Schwartzman, Hunter Schafer', NULL, NULL, NULL),
(203, 'Hunger Games: La ragazza di fuoco (The Hunger Games: Catching Fire)', 2013, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Dopo aver vinto i settantaquattresimi Hunger Games, Katniss e Peeta diventano il simbolo della ribellione contro Capitol City e vengono costretti a partecipare all''Edizione della Memoria degli Hunger Games.', 'https://image.tmdb.org/t/p/w500/vrQHDXjVmbYzadOXQ0UaObunoy2.jpg', '2026-10-11T16:25:26.673485', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Philip Seymour Hoffman', NULL, NULL, NULL),
(202, 'Hunger Games (The Hunger Games)', 2012, 'Gary Ross', 'Fantascienza, Azione, Avventura', 'In un futuro distopico, la sedicenne Katniss Everdeen si offre volontaria al posto della sorella minore per partecipare agli Hunger Games, un brutale reality show televisivo in cui ventiquattro adolescenti combattono all''ultimo sangue.', 'https://image.tmdb.org/t/p/w500/apa5G43Hha7kH7wJG0gkkHT7FA9.jpg', '2026-10-11T16:25:26.586082', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Donald Sutherland', NULL, NULL, NULL),
(209, 'Minions', 2015, 'Pierre Coffin, Kyle Balda', 'Animazione, Commedia, Avventura', 'Evolutisi da organismi unicellulari gialli, i Minions cercano disperatamente un padrone malvagio da servire. Nel 1968, Kevin, Stuart e Bob partono per una missione che li condurrà da Scarlet Sterminator.', 'https://image.tmdb.org/t/p/w500/dr02BdCNAUPVU07aOodwPYv6HCf.jpg', '2026-10-11T16:57:54.06741', 'Sandra Bullock, Jon Hamm, Michael Keaton, Pierre Coffin', NULL, NULL, NULL),
(207, 'Cattivissimo me (Despicable Me)', 2010, 'Pierre Coffin, Chris Renaud', 'Animazione, Commedia, Avventura', 'Il supercattivo Gru pianifica di rubare la Luna con l''aiuto dei suoi piccoli assistenti gialli, i Minions, ma il suo piano viene scompaginato dall''incontro con tre bambine orfane.', 'https://image.tmdb.org/t/p/w500/b1BT309QWjtFUlJPLmXmrcHOWEL.jpg', '2026-10-11T16:57:53.672317', 'Steve Carell, Jason Segel, Russell Brand, Pierre Coffin', NULL, NULL, NULL),
(208, 'Cattivissimo me 2 (Despicable Me 2)', 2013, 'Pierre Coffin, Chris Renaud', 'Animazione, Commedia, Avventura', 'Gru viene reclutato dalla Lega Anti-Cattivi per indagare sulla scomparsa di un laboratorio segreto e sulla trasformazione dei suoi Minions in mostri viola indistruttibili.', 'https://image.tmdb.org/t/p/w500/5Fh4NdoEnCjCK9wLjdJ9DJNFl2b.jpg', '2026-10-11T16:57:53.867978', 'Steve Carell, Kristen Wiig, Benjamin Bratt, Pierre Coffin', NULL, NULL, NULL),
(210, 'Cattivissimo me 3 (Despicable Me 3)', 2017, 'Pierre Coffin, Kyle Balda', 'Animazione, Commedia, Avventura', 'Dopo essere stato licenziato dalla Lega Anti-Cattivi, Gru scopre di avere un fratello gemello ricco e stravagante di nome Dru, mentre i Minions affrontano una breve ribellione.', 'https://image.tmdb.org/t/p/w500/e72KCMHNkbZ6USRJmABeqwmaJ5n.jpg', '2026-10-11T16:57:54.243381', 'Steve Carell, Kristen Wiig, Trey Parker, Pierre Coffin', NULL, NULL, NULL),
(205, 'Hunger Games: Il canto della rivolta - Parte 2 (The Hunger Games: Mockingjay - Part 2)', 2015, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Con Panem in guerra totale, Katniss guida la squadra d''assalto verso Capitol City per affrontare direttamente il Presidente Snow e porre fine alla tirannia.', 'https://image.tmdb.org/t/p/w500/aQvME1wpAZpjdyg5Xfe35lINmwt.jpg', '2026-10-11T16:25:26.877919', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Julianne Moore', NULL, NULL, NULL),
(211, 'Minions 2 - Come Gru diventa cattivissimo (Minions: The Rise of Gru)', 2022, 'Kyle Balda', 'Animazione, Commedia, Avventura', 'Negli anni ''70, il dodicenne Gru tenta di entrare a far parte di un gruppo di supercattivi chiamato I Malefici 6. Quando il suo colloquio va male, i Minions intervengono per aiutarlo.', 'https://image.tmdb.org/t/p/w500/j0w5tggQs0VVtXj5OF8kWqME2WG.jpg', '2026-10-11T16:57:54.450742', 'Steve Carell, Pierre Coffin, Taraji P. Henson, Michelle Yeoh', NULL, NULL, NULL),
(212, 'Cattivissimo me 4 (Despicable Me 4)', 2024, 'Chris Renaud', 'Animazione, Commedia, Avventura', 'Gru, Lucy e le loro figlie accolgono un nuovo membro in famiglia, Gru Jr., ma sono costretti alla fuga quando il supercriminale Maxime Le Mal evade di prigione per vendicarsi.', 'https://image.tmdb.org/t/p/w500/wWba3TaojhK7NdycRhoQpsG0FaH.jpg', '2026-10-11T16:57:54.635395', 'Steve Carell, Kristen Wiig, Will Ferrell, Sofia Vergara, Pierre Coffin', NULL, NULL, NULL),
(213, 'Heart of the Sea - Le origini di Moby Dick (In the Heart of the Sea)', 2015, 'Ron Howard', 'Avventura, Drammatico, Storico', 'Nel inverno del 1820, la baleniera del New England Essex viene assalita da una creatura incredibile: una balena dalle dimensioni e dalla forza mastodontiche, con un senso quasi umano di vendetta. Il disastro marittimo realmente accaduto avrebbe ispirato Herman Melville a scrivere Moby Dick.', 'https://image.tmdb.org/t/p/w500/weVvNPfk6FM9vBg3BXtRtNAmiYM.jpg', '2026-10-17T15:11:52.216085', 'Chris Hemsworth, Benjamin Walker, Cillian Murphy, Tom Holland, Brendan Gleeson, Ben Whishaw', NULL, NULL, NULL),
(214, 'Prisoners', 2013, 'Denis Villeneuve', 'Thriller, Drammatico, Mystery', 'Dopo la scomparsa della figlia di sei anni e della sua amica durante il Giorno del Ringraziamento, Keller Dover affronta il peggior incubo di ogni genitore. Il detective Loki guida le indagini e arresta l''unico sospettato, ma è costretto a rilasciarlo per mancanza di prove. Preso dalla disperazione e vedendo la polizia brancolare nel buio, Keller decide di farsi giustizia da solo, spingendosi oltre ogni limite pur di salvare le bambine.', 'https://image.tmdb.org/t/p/w500/uhviyknTT5cEQXbn6vWIqfM4vGm.jpg', '2026-10-17T17:44:48.655806', 'Hugh Jackman, Jake Gyllenhaal, Viola Davis, Maria Bello, Terrence Howard, Melissa Leo, Paul Dano', NULL, NULL, NULL),
(216, 'La leggenda del pianista sull''oceano (The Legend of 1900)', 1998, 'Giuseppe Tornatore', 'Drammatico, Musicale', 'La storia di Danny Boodmann T.D. Lemon Novecento, un pianista straordinario nato e cresciuto a bordo del transatlantico Virginian, senza mai mettere piede sulla terraferma. La sua vita e il suo incredibile talento vengono raccontati dal suo grande amico, il trombettista Max Tooney.', 'https://image.tmdb.org/t/p/w500/iOcbJ5pxokOPDRgieVDbsFMrCc6.jpg', '2026-10-17T23:29:21.408922', 'Tim Roth, Pruitt Taylor Vince, Mélanie Thierry, Bill Nunn, Peter Vaughan, Clarence Williams III', NULL, NULL, NULL),
(118, 'The Hateful Eight', 2015, 'Quentin Tarantino', 'Western, Giallo, Thriller', 'Qualche anno dopo la guerra civile americana, una diligenza si fa strada nel paesaggio innevato del Wyoming. I passeggeri, tra cui il cacciatore di taglie John Ruth e la sua prigioniera Daisy Domergue, cercano rifugio da una tempesta di neve in un emporio, dove si imbattono in altri loschi personaggi. La diffidenza e la tensione tra i presenti porteranno a una sanguinosa resa dei conti.', 'https://image.tmdb.org/t/p/w500/jIywvdPjia2t3eKYbjVTcwBQlG8.jpg', '2026-09-18T10:34:27.295046', 'Samuel L. Jackson, Kurt Russell, Jennifer Jason Leigh, Walton Goggins, Demián Bichir, Tim Roth, Michael Madsen, Bruce Dern', NULL, NULL, NULL),
(44, 'Agente 007 - Licenza di uccidere', 1962, 'Terence Young', 'Spionaggio, Azione, Avventura', 'L''agente segreto britannico James Bond, noto come 007, viene inviato in Giamaica per indagare sulla misteriosa scomparsa di un suo collega, lo chef della sezione di Kingston, e della sua segretaria. Con l''aiuto dell''agente della CIA Felix Leiter e del luogo Quarrel, Bond risale le tracce fino all''isola sotterranea di Crab Key. Lì fa la conoscenza della splendida Honey Ryder e scopre il covo del sinistro Dottor No, un genio del male affiliato all''organizzazione criminale SPECTRE. Dr. No intende utilizzare un''arma a raggi atomici per deviare la rotta dei missili spaziali americani lanciati da Cape Canaveral. 007 dovrà fare affidamento sulle sue abilità e sul suo fascino per distruggere la base segreta e sventare la minaccia globale.', 'https://image.tmdb.org/t/p/w500/9zCOLJmLNst0sCPZlkW1IRoH65E.jpg', '2026-09-14T13:48:35.238938', 'Sean Connery, Ursula Andress, Joseph Wiseman, Jack Lord, Bernard Lee', NULL, NULL, NULL),
(51, 'Avengers: Infinity War', 2018, 'Anthony e Joe Russo', 'Azione, Fantascienza, Avventura', 'Gli Avengers e i loro alleati supereroi devono essere pronti a sacrificare tutto nel tentativo di sconfiggere il potente Thanos, prima che il suo devastante attacco ponga fine all''universo. Il tiranno cosmico è alla ricerca delle sei Gemme dell''Infinito, manufatti di inimmaginabile potere, con l''obiettivo di dimezzare la popolazione dell''universo e portare un folle equilibrio.', 'https://image.tmdb.org/t/p/w500/7WsyChQLEftFiDOVTGkv3hFpyyt.jpg', '2026-09-14T13:51:08.090595', 'Robert Downey Jr., Chris Hemsworth, Mark Ruffalo, Chris Evans, Scarlett Johansson, Benedict Cumberbatch, Tom Holland, Chadwick Boseman, Josh Brolin, Zoe Saldana', NULL, NULL, NULL),
(133, 'C''era una volta a... Hollywood', 2019, 'Quentin Tarantino', 'Drammatico, Commedia', 'Nella Los Angeles del 1969, un attore televisivo in declino e la sua controfigura e migliore amico cercano di navigare nei cambiamenti dell''industria cinematografica, mentre sullo sfondo si consumano le vicende legate alla setta di Charles Manson.', 'https://image.tmdb.org/t/p/w500/8j58iEBw9pOXFD2L0nt0ZXeHviB.jpg', '2026-09-19T19:47:16.734724', 'Leonardo DiCaprio, Brad Pitt, Margot Robbie', NULL, NULL, NULL),
(16, 'Bianca e Bernie nella terra dei canguri', 1990, 'Hendel Butoy, Mike Gabriel', 'Animazione, Avventura, Commedia, Famiglia', 'Nell''Outback australiano, un ragazzino di nome Cody fa amicizia con Marahute, una gigantesca e rarissima aquila dorata. Quando il crudele bracconiere Percival McLeach lo scopre, rapisce Cody con l''intento di farsi rivelare l''ubicazione del nido dell''animale. La Società Internazionale di Salvataggio allerta immediatamente i due celebri agenti speciali a quattro zampe, Bianca e Bernie. Volando in Australia a bordo dell''albatros Wilbur e affiancati dalla guida locale Jake, un vivace topo saltatore, i due intraprenderanno una rischiosa missione per liberare Cody e salvare Marahute.', 'https://image.tmdb.org/t/p/w500/5koTDBmMAkJOgAe4PL4163UKjvG.jpg', '2026-09-13T14:58:32.038641', 'Bob Newhart, Eva Gabor, John Candy, George C. Scott, Tristan Rogers', NULL, NULL, NULL),
(220, 'Quo Vadis?', 1924, 'Gabriellino D''Annunzio, Georg Jacoby', 'Storico, Drammatico', 'Imponente kolossal muto che mette in scena la follia dell''imperatore Nerone e il tragico destino dei primi cristiani a Roma, intrecciato con la storia d''amore tra Marco Vinicio e la giovane Licia.', 'https://image.tmdb.org/t/p/w500/9XznF1gIXfgqzEs6La7vXMW46sM.jpg', '2026-10-18T02:03:26.62268', 'Emil Jannings, Elena Sangro, Lillian Hall-Davis, Alfons Fryland', NULL, NULL, NULL),
(222, 'Quo Vadis?', 1985, 'Franco Rossi', 'Storico, Drammatico', 'Adattamento televisivo del capolavoro di Henryk Sienkiewicz che racconta l''ascesa del cristianesimo nella Roma imperiale e la deriva tirannica e folle di Nerone.', 'https://www.themoviedb.org/t/p/w600_and_h900_face/4AD9VxrSItAjOUIdAkDwSD4xXDu.jpg', '2026-10-18T02:03:26.666969', 'Klaus Maria Brandauer, Frederic Forrest, Cristina Raines, Francesco Quinn', NULL, NULL, NULL),
(47, 'Casino Royale', 2006, 'Martin Campbell', 'Azione, Spionaggio, Thriller', 'Dopo aver ottenuto lo status di agente 00 e la licenza di uccidere, James Bond viene inviato in missione per fermare Le Chiffre, un brillante e spietato banchiere che finanzia organizzazioni terroristiche internazionali. Avendo perso ingenti somme di denaro appartenenti ai suoi pericolosi clienti a causa di un attentato sventato dallo stesso Bond, Le Chiffre organizza una partita di poker Texas Hold''em ad altissima posta al Casino Royale, in Montenegro, nel tentativo disperato di recuperare i fondi. L''MI6 affida a Bond il compito di batterlo al tavolo verde per costringerlo a chiedere asilo al governo britannico in cambio di informazioni cruciali. Affiancato dall''affascinante e riservata funzionaria del Tesoro Vesper Lynd, incaricata di monitorare i fondi statali della posta in gioco, l''agente 007 si ritrova invischiato in un mortale gioco di strategia, inganni e violenza, che lo porterà a scoprire il peso emotivo del proprio mestiere e il sapore del tradimento.', 'https://image.tmdb.org/t/p/w500/lMrxYKKhd4lqRzwUHAy5gcx9PSO.jpg', '2026-09-14T13:49:14.542444', 'Daniel Craig, Eva Green, Mads Mikkelsen, Judi Dench, Jeffrey Wright', NULL, NULL, NULL),
(116, 'Lei', 2013, 'Spike Jonze', 'Fantascienza, Drammatico, Sentimentale', 'In un futuro non troppo lontano, Theodore, un uomo solitario e introverso che scrive lettere d''amore per conto terzi, acquista un nuovo sistema operativo basato su un''intelligenza artificiale estremamente avanzata. Ben presto, tra Theodore e la voce del sistema operativo, che si autodefinisce Samantha, nasce una profonda e insolita relazione sentimentale.', 'https://image.tmdb.org/t/p/w500/8sSc94dznzIKuYMna2pWrGSW2c2.jpg', '2026-09-17T18:13:20.24262', 'Joaquin Phoenix, Scarlett Johansson, Amy Adams, Rooney Mara, Olivia Wilde', NULL, NULL, NULL),
(30, 'L''indiana bianca', 1953, 'Ray Nazarro', 'Western', 'Nel selvaggio West, Sharon Purcell, una giovane donna per metà bianca e per metà nativa americana, vive al confine tra le due culture affrontando il disprezzo e il pregiudizio di entrambe le comunità. La situazione degenera quando un potente e avido proprietario terriero tenta con ogni mezzo di sottrarre le terre alla tribù indiana locale per espandere il proprio dominio. In mezzo alle crescenti tensioni e allo scoppio delle ostilità, Sharon cercherà disperatamente di favorire la convivenza pacifica, aiutata da un coraggioso funzionario governativo determinato a ristabilire la giustizia e a far rispettare i trattati.', 'https://image.tmdb.org/t/p/w500/awt4WEDwcKuTw4oaiLwzfh7xnt7.jpg', '2026-09-13T15:08:13.288587', 'David Brian, May Wynn, William Bishop, Nancy Hale, Robert Lowery', NULL, NULL, NULL),
(84, 'Va'' e vedi', 1985, 'Elem Klimov', 'Guerra, Drammatico, Storico', 'Durante la seconda guerra mondiale, nella Bielorussia del 1943 occupata dalle forze naziste, il giovane Florya decide di unirsi alla resistenza partigiana contro l''invasore. Attraverso il suo tragico viaggio, il ragazzo sarà testimone diretto delle atrocità più disumane, dei massacri sistematici dei villaggi e della devastazione psicologica e fisica causata dalla guerra, perdendo prematuramente la propria innocenza in un crescendo di orrore.', 'https://image.tmdb.org/t/p/w500/qNbMsKVzigERgJUbwf8pKyZogpb.jpg', '2026-09-15T20:51:59.379926', 'Aleksej Kravčenko, Ol''ga Mironova, Liubomiras Laucevičius', NULL, NULL, NULL),
(65, 'Robin e Marian', 1976, 'Richard Lester', 'Avventura, Drammatico, Romantico', 'Un invecchiato Robin Hood ritorna in Inghilterra dopo vent''anni trascorsi a combattere nelle Crociate al seguito di Re Riccardo. Trova la sua amata Marian che, nel frattempo, si è ritirata in convento diventando badessa. Nonostante il tempo trascorso e le ferite della vita, il loro antico amore si riaccende. Tuttavia, Robin si ritrova ben presto a dover affrontare nuovamente il suo storico avversario, lo Sceriffo di Nottingham, in un ultimo e tragico scontro che segnerà il destino dei due amanti.', 'https://image.tmdb.org/t/p/w500/y2UlVt6U8mFeegVL42rZjD5y6c7.jpg', '2026-09-15T18:04:05.581875', 'Sean Connery, Audrey Hepburn, Robert Shaw, Richard Harris, Nicol Williamson', NULL, NULL, NULL),
(106, 'Farewell Oak Street', 1953, 'Grant McLean', 'Documentario', 'Questo documentario canadese analizza le degradate condizioni di vita nel quartiere di Regent Park a Toronto prima della sua ricostruzione. Attraverso il contrasto tra i vecchi slum di Oak Street e i nuovi complessi di edilizia popolare, l''opera illustra l''impatto positivo che una pianificazione urbana moderna e alloggi dignitosi hanno sulla salute, sulla sicurezza e sul benessere sociale delle famiglie.', 'https://image.tmdb.org/t/p/w500/1YHZU9dKVch25GChAg22hiYEdR9.jpg', '2026-09-17T11:01:31.104209', 'Lamont Tilden (voce narrante)', NULL, NULL, NULL),
(217, 'The Book of Boba Fett', 2021, 'Robert Rodriguez, Jon Favreau, Bryce Dallas Howard, Dave Filoni', 'Fantascienza, Azione, Avventura', 'Il leggendario cacciatore di taglie Boba Fett e la mercenaria Fennec Shand tornano sulle sabbie di Tatooine per rivendicare il territorio un tempo controllato da Jabba the Hutt e dal suo sindacato criminale.', 'https://www.themoviedb.org/t/p/w600_and_h900_face/lQqbnWsGt9RBGBWrmUKUOXZkl7N.jpg', '2026-10-18T00:57:36.992966', 'Temuera Morrison, Ming-Na Wen, Pedro Pascal', NULL, NULL, NULL),
(76, 'Star Wars: Il risveglio della Forza', 2015, 'J.J. Abrams', 'Fantascienza', 'Trent''anni dopo la caduta dell''Impero, sorge una nuova minaccia nota come Primo Ordine guidata da Kylo Ren. Una giovane orfana di nome Rey scopre la sua potente connessione con la Forza e parte alla ricerca dello scomparso Luke Skywalker.', 'https://image.tmdb.org/t/p/w500/uEDFRwKiTOsIsN5dkEPCj1laIAK.jpg', '2026-09-15T19:21:49.969942', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness', NULL, NULL, NULL),
(80, 'Guerre stellari: Episodio V - L''Impero colpisce ancora', 1980, 'Irvin Kershner', 'Fantascienza', 'Dopo la distruzione della Morte Nera, le forze imperiali inseguono implacabilmente i Ribelli attraverso la galassia. Mentre Han Solo e Leila sfuggono alla flotta nemica rifugiandosi nella Città delle Nuvole, Luke si reca sul pianeta Dagobah per addestrarsi con il maestro Yoda. Lo scontro imminente con Dart Fener porterà alla luce una sconvolgente verità sul suo passato.', 'https://image.tmdb.org/t/p/w500/nNAeTmF4CtdSgMDplXTDPOpYzsX.jpg', '2026-09-15T19:22:13.819762', 'Mark Hamill, Harrison Ford, Carrie Fisher, Billy Dee Williams, Anthony Daniels', NULL, NULL, NULL),
(204, 'Hunger Games: Il canto della rivolta - Parte 1 (The Hunger Games: Mockingjay - Part 1)', 2014, 'Francis Lawrence', 'Fantascienza, Azione, Avventura', 'Katniss si ritrova nel Distretto 13 dopo aver distrutto l''arena. Guidata dalla Presidente Coin, accetta di diventare la Ghiandaia Imitatrice, simbolo della rivoluzione contro Panem.', 'https://image.tmdb.org/t/p/w500/9LZSYohDOJkLU2TyRvPM1zIo62e.jpg', '2026-10-11T16:25:26.778038', 'Jennifer Lawrence, Josh Hutcherson, Liam Hemsworth, Woody Harrelson, Elizabeth Banks, Julianne Moore', NULL, NULL, NULL),
(223, 'Quo Vadis', 2001, 'Jerzy Kawalerowicz', 'Storico, Drammatico', 'Produzione polacca ad alto budget altamente fedele al romanzo originale, centrata sul contrasto tra la decadenza edonistica della Roma di Nerone e la nascente fede dei primi cristiani.', 'https://image.tmdb.org/t/p/w500/rzePNmvU9Kczxu60TUoyzVED5xy.jpg', '2026-10-18T02:03:26.692321', 'Pawel Delag, Magdalena Mielcarz, Boguslaw Linda, Michal Bajor', NULL, NULL, NULL);
INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori", "slug", "backdrop_url", "trailer_url") VALUES
(221, 'Quo Vadis', 1951, 'Mervyn LeRoy', 'Storico, Drammatico, Kolossal', 'Di ritorno dalle campagne militari, il comandante romano Marco Vinicio si innamora della cristiana Licia. Quando l''imperatore Nerone incendia Roma e accusa i cristiani, la coppia viene travolta dalle persecuzioni.', 'https://image.tmdb.org/t/p/w500/dqF1dattMNiwGjPSphu2VSi558Q.jpg', '2026-10-18T02:03:26.648582', 'Robert Taylor, Deborah Kerr, Peter Ustinov, Leo Genn', NULL, NULL, NULL),
(219, 'Quo Vadis?', 1913, 'Enrico Guazzoni', 'Storico, Drammatico', 'Nella Roma dell''imperatore Nerone, il giovane tribuno Marco Vinicio si innamora della cristiana Licia. Tra intrighi di corte, l''incendio della città e il martirio dei primi cristiani, il loro amore affronterà terribili prove.', 'https://image.tmdb.org/t/p/w500/xbA8ljsXMgOnbkN3X5li9UzFSvf.jpg', '2026-10-18T02:03:26.575471', 'Amleto Novelli, Gustavo Serena, Lea Giunchi, Bruto Castellani', NULL, NULL, NULL),
(224, 'Spartacus', 1960, 'Stanley Kubrick', 'Storico, Drammatico, Avventura', 'Nel I secolo a.C., il gladiatore trace Spartaco guida una vasta ribellione di schiavi contro la Repubblica romana. Dopo aver sconfitto diverse legioni e radunato migliaia di seguaci in cerca di libertà, l''esercito dei ribelli si scontra con le ambizioni politiche del patrizio Marco Licinio Crasso, determinato a schiacciare la rivolta per consolidare il proprio potere su Roma.', 'https://image.tmdb.org/t/p/w500/nqU4xAn3ygWA4fvXSBufRwdGhpr.jpg', '2026-10-18T13:31:43.100209', 'Kirk Douglas, Laurence Olivier, Jean Simmons, Charles Laughton, Peter Ustinov, John Gavin, Tony Curtis', NULL, NULL, NULL),
(232, 'Home Sweet Home Alone - Mamma, ho perso l''aereo (Home Sweet Home Alone)', 2021, 'Dan Mazer', 'Commedia, Film per famiglie', 'Il giovanissimo Max Mercer viene accidentalmente lasciato a casa da solo quando la sua famiglia parte per il Giappone. Deve proteggere la sua abitazione da una coppia di coniugi in difficoltà finanziarie che tenta di recuperare un prezioso cimelio di famiglia.', 'https://image.tmdb.org/t/p/w500/fP3VvqUjEBjawxZHL4sYCq2ZdJD.jpg', '2026-10-23T13:14:06.720403', 'Archie Yates, Ellie Kemper, Rob Delaney, Aisling Bea, Kenan Thompson', NULL, NULL, NULL),
(227, 'Mamma, ho perso l''aereo (Home Alone)', 1990, 'Chris Columbus', 'Commedia, Film per famiglie', 'Il piccolo Kevin McCallister viene sbadatamente dimenticato a casa dalla famiglia in partenza per le vacanze di Natale a Parigi. Rimasto solo, deve difendere la propria abitazione da due maldestri ladri d''appartamento usando ingegnose trappole.', 'https://image.tmdb.org/t/p/w500/onTSipZ8R3bliBdKfPtsDuHTdlL.jpg', '2026-10-23T13:14:06.497613', 'Macaulay Culkin, Joe Pesci, Daniel Stern, Catherine O''Hara, John Heard', NULL, NULL, NULL),
(234, 'Ultima notte a Soho', 2021, 'Edgar Wright', 'Horror, Mistero, Thriller', 'Eloise, ventenne cresciuta con la nonna dopo il suicidio della madre, arriva a Londra con il sogno di diventare stilista. Ha il mito della Swingin'' London e della musica anni ''60, che ascolta continuamente su vecchi 33 giri portatili. Dopo un''infelice esperienza nello studentato della scuola di moda in cui è stata ammessa, si trasferisce in un appartamento di Soho affittato da un''anziana signora. Qui, durante lunghe notti agitate, Eloise sogna di tornare nel passato, nella Londra che ama di più, dove incontra Sandie, un''aspirante cantante che vive il glamour di una città colorata ed esaltante. Poco alla volta, però, Eloise confonde la propria personalità con quella di Sandie e ne scopre la vita in realtà miserabile, scivolando tra realtà e incubo in un''esperienza spaventosa.', 'https://image.tmdb.org/t/p/w500/mNuXKuiywifooo8LnAzMy0W4ZiK.jpg', '2026-10-24T14:57:49.238234', 'Thomasin McKenzie, Anya Taylor-Joy, Matt Smith, Rita Tushingham, Michael Ajao, Synnøve Karlsen, Pauline McLynn', NULL, NULL, NULL),
(225, 'L''ultimo samurai (The Last Samurai)', 2003, 'Edward Zwick', 'Azione, Drammatico, Storico', 'Nel 1876 il veterano della guerra civile americana Nathan Algren viene assoldato dall''imperatore giapponese per addestrare il nuovo esercito secondo i metodi occidentali e sedare la ribellione guidata dal samurai Katsumoto. Catturato dai ribelli, Algren scopre il loro stile di vita e il codice d''onore dei samurai, finendo per abbracciare la loro causa contro la modernizzazione forzata e spietata del Paese.', 'https://image.tmdb.org/t/p/w500/hHYbOZVogfOIVg4FEF2Hs2UUNHs.jpg', '2026-10-21T20:28:35.78698', 'Tom Cruise, Ken Watanabe, Koyuki, Hiroyuki Sanada, Shin Koyamada, Timothy Spall, Billy Connolly', NULL, NULL, NULL),
(226, 'L''ultimo samurai (Ôkami yo rakujitsu o)', 1974, 'Kenji Misumi', 'Azione, Drammatico, Storico', 'Durante il periodo del Bakumatsu e il declino dello shogunato Tokugawa, un maestro di spada fedele alla tradizione samurai si trova diviso tra amicizia, dovere e il turbine dei conflitti sanguinosi che segnano la nascita del Giappone moderno.', 'https://image.tmdb.org/t/p/w500/o4WHApeJWxu3QVYRbDzg1cEtGfd.jpg', '2026-10-21T20:28:35.826744', 'Hideki Takahashi, Ken Ogata, Keiko Matsuzaka, Kiwako Taichi, Teruhiko Aoi', NULL, NULL, NULL),
(230, 'Mamma, ho allagato la casa (Home Alone 4: Taking Back the House)', 2002, 'Rod Daniel', 'Commedia, Film per famiglie', 'Kevin McCallister trascorre il Natale nella villa super tecnologica della nuova fidanzata del padre. Lì dovrà impedire il rapimento di un giovane principe da parte del suo vecchio nemico Marv e della sua nuova complice.', 'https://image.tmdb.org/t/p/w500/zfm0UYbIpOpL8ak9tf655h3GWS2.jpg', '2026-10-23T13:14:06.654706', 'Mike Weinberg, French Stewart, Missi Pyle, Barbara Babcock', NULL, NULL, NULL),
(229, 'Mamma, ho preso il morbillo (Home Alone 3)', 1997, 'Raja Gosnell', 'Commedia, Film per famiglie', 'Il piccolo Alex è costretto a rimanere a casa con il morbillo. Si troverà a dover affrontare quattro pericolosi criminali internazionali intenzionati a recuperare un prezioso microchip militare nascosto all''interno di un''auto radiocomandata finita per sbaglio nelle sue mani.', 'https://image.tmdb.org/t/p/w500/s1PwvbnNicaxT6wdlMZJqrW0yQt.jpg', '2026-10-23T13:14:06.612786', 'Alex D. Linz, Olek Krupa, Rya Kihlstedt, Scarlett Johansson', NULL, NULL, NULL),
(228, 'Mamma, ho riperso l''aereo - Mi sono smarrito a New York (Home Alone 2: Lost in New York)', 1992, 'Chris Columbus', 'Commedia, Film per famiglie', 'Durante la confusione dell''imbarco per le vacanze natalizie in Florida, Kevin si imbarca per errore su un volo diretto a New York. Nella grande mela si ritroverà ad affrontare nuovamente i ladri Harry e Marv, evasi nel frattempo dal carcere.', 'https://image.tmdb.org/t/p/w500/eYKQJmrEyANdUcE7nJ7PQ6XARaO.jpg', '2026-10-23T13:14:06.551817', 'Macaulay Culkin, Joe Pesci, Daniel Stern, Catherine O''Hara, Tim Curry', NULL, NULL, NULL),
(231, 'Mamma, ho visto i fantasmi! (Home Alone: The Holiday Heist)', 2012, 'Peter Hewitt', 'Commedia, Film per famiglie', 'Finn si trasferisce con la famiglia in una nuova casa nel Maine che crede infestata dai fantasmi. Quando i genitori rimangono bloccati fuori città, Finn deve proteggere la dimora da una banda di tre ladri d''arte a caccia di un dipinto dal valore inestimabile.', 'https://image.tmdb.org/t/p/w500/nsRl6M33UjKNpHDIRoGW81WX89H.jpg', '2026-10-23T13:14:06.677956', 'Christian Martyn, Jodelle Ferland, Malcolm McDowell, Debi Mazar', NULL, NULL, NULL),
(235, 'Mamma ho perso il lavoro', 2008, 'Vince Di Meglio', 'Commedia, Dramma, Romance', 'After he''s fired from his job, an everyday guy faces pressure from his wife to have a baby and from his mom, who has decided to move in with the young couple.', 'https://image.tmdb.org/t/p/w500/2vLLJG71kmrCcTbnIztn13NHKZF.jpg', '2026-10-24T15:53:17.012565', 'Diane Keaton, Dax Shepard, Liv Tyler, Ken Howard, Jerry Lambert, Selma Stern, Mike White', NULL, NULL, NULL),
(236, 'L''esercito delle 12 scimmie', 1995, 'Terry Gilliam', 'Fantascienza, Thriller, Mistero', 'L''Esercito delle 12 scimmie è un piccolo gioiellino fantascientifico del 1995 che si focalizza sulla disperazione di un singolo uomo, condannato a essere il prescelto per trovare un rimedio alla situazione disastrosa dell''umanità, in un futuro ormai abitato da una razza umana rassegnata. Nel 2035 gli esseri umani vivono nel sottosuolo, terrorizzati dall''ambiente esterno, portatore di un virus mortale che li ha decimati, rendendo il pianeta Terra un luogo dove i prigionieri sono diventati loro stessi. Anche se solo in modo approssimativo, gli scienziati di quel terribile futuro hanno reso possibile il viaggio nel tempo, unica possibilità per poter mettere le mani sul virus e crearne una cura.', 'https://image.tmdb.org/t/p/w500/9WfkdEGHO8K0AF8ahbc34zMzM4e.jpg', '2026-10-24T15:59:00.865215', 'Bruce Willis, Madeleine Stowe, Brad Pitt, Christopher Plummer, David Morse, Jon Seda, Christopher Meloni', NULL, NULL, NULL),
(79, 'Guerre stellari: Episodio IV - Una nuova speranza', 1977, 'George Lucas', 'Fantascienza', 'Il giovane Luke Skywalker entra in possesso di droidi contenenti i piani segreti della Morte Nera, la potente arma dell''Impero Galattico. Guidato dal saggio maestro Jedi Obi-Wan Kenobi e affiancato dal contrabbandiere Han Solo, Luke intraprende un''audace missione per salvare la Principessa Leila. Insieme, guideranno l''Alleanza Ribelle nel disperato tentativo di distruggere la stazione imperiale.', 'https://image.tmdb.org/t/p/w500/fVqKwpvobwWy0P1UImZWIDuw4RI.jpg', '2026-09-15T19:22:13.623129', 'Mark Hamill, Harrison Ford, Carrie Fisher, Peter Cushing, Alec Guinness', NULL, NULL, NULL),
(238, 'L''esorcista', 1973, 'William Friedkin', 'Horror', 'In un quartiere tranquillo, in una casa dotata di tutti i moderni comfort, una ragazzina modello cade ammalata. La madre non può aiutarla. I medici non riescono ad elaborare una diagnosi. Temendo che le crisi di cui soffre la figlia non riguardino solo la sfera fisica, ma anche quella spirituale, la donna si rivolge a un sacerdote. L''uomo però dubita della presenza del diavolo in quella casa, in quel corpo e la debolezza delle sue convinzioni non farà altro che rendere più forte il maligno.', 'https://image.tmdb.org/t/p/w500/49uIBJqG4ugL7KC2yBhz0nCLeHG.jpg', '2026-10-25T08:34:21.259526', 'Ellen Burstyn, Linda Blair, Jason Miller, Max von Sydow, Lee J. Cobb, William O''Malley, Kitty Winn', NULL, NULL, NULL),
(239, 'Halloween - La notte delle streghe', 1978, 'John Carpenter', 'Horror, Thriller', 'Micheal, a soli 6 anni ammazza la sorella e viene internato ma dopo 15 anni fugge per recarsi al suo paese. E'' il 31 Ottobre, e secondo l''antica tradizione americana è la notte in cui si esorcizzano le streghe, grazie a questa concomitanza Micheal può mietere altre vittime.', 'https://image.tmdb.org/t/p/w500/uxLqrN38fSQEUVpM4S1suhnW3X.jpg', '2026-10-25T12:31:42.720576', 'Donald Pleasence, Jamie Lee Curtis, Nancy Kyes, P. J. Soles, Charles Cyphers, Kyle Richards, Brian Andrews', NULL, NULL, NULL),
(240, 'It - Capitolo uno', 2017, 'Andy Muschietti', 'Horror, Thriller, Dramma', 'Ottobre 1988, nella cittadina di Derry. Il piccolo Georgie esce di casa nella pioggia per far navigare la barchetta di carta preparatagli dal fratello maggiore Billy, costretto a casa dall''influenza. La barchetta scorre per i rivoli lungo i marciapiedi, ma finisce in uno scolo che conduce alla rete fognaria. Georgie, contrariato, si china a guardare nella feritoia e incontra lo sguardo del bizzarro clown che abita nelle fogne, Pennywise. Per quanto strano sia trovare un clown in quel luogo, Georgie si intrattiene con lui sin quando il clown non lo addenta e lo cattura portandolo giù con sé. Giugno 1989. A Derry vige il coprifuoco a causa delle numerose sparizioni di persone, soprattutto bambini.', 'https://image.tmdb.org/t/p/w500/ru0gDnxKzBjzrPxfRyZIuse9hfu.jpg', '2026-10-25T12:35:25.301766', 'Jaeden Martell, Jeremy Ray Taylor, Sophia Lillis, Finn Wolfhard, Chosen Jacobs, Jack Dylan Grazer, Wyatt Oleff', NULL, NULL, NULL),
(241, 'E.T. l''extra-terrestre', 1982, 'Steven Spielberg', 'Avventura, Fantascienza, Famiglia', 'Durante un sopralluogo sulla Terra per raccogliere vegetali, un gruppo di alieni viene sorpreso e uno di loro viene lasciato erroneamente al suolo per l''affrettato decollo. L''alieno, solo e smarrito, viene trovato ed ospitato da Elliott, con la complicità della sorellina Gertie e il fratello maggiore Michael. Tra i due si instaura un profondo rapporto di amicizia che li lega anche a livello emotivo. Desideroso di tornare a casa, l''alieno costruisce un rudimentale dispositivo di comunicazione per chiedere aiuto ai suoi. Gradualmente, la salute di ET peggiora, e la situazione è aggravata dall''irruzione nell''universo dei ragazzi da parte del mondo degli adulti, che vuole impossessarsi dell''alieno.', 'https://image.tmdb.org/t/p/w500/3DIwTC2A58WDtsgjaXjo2FYA1pW.jpg', '2026-10-25T14:09:52.788971', 'Henry Thomas, Drew Barrymore, Robert MacNaughton, Peter Coyote, Dee Wallace, Erika Eleniak, K.C. Martel', NULL, NULL, NULL),
(256, 'Il miglio verde', 1999, 'Frank Darabont', 'Fantasy, Dramma, Crime', 'E'' il racconto che Paul Edgecomb fa all''amica Elaine Connelly in una casa di riposo. Sono passati circa sessanta anni da quando lavorava come capo delle guardie del braccio della morte nel penitenziario di Could Mountain. Durante la grande depressione, nel carcere del sud degli Usa, Edgecomb si occupava di quattro assassini che attendevano di compiere la loro ultima passeggiata lungo il ''Miglio verde'', il corridoio rivestito di linoleum verde che li avrebbe condotti nella stanza della sedia elettrica. Fra questi c''era anche John Coffrey, un ragazzone nero condannato per l''omicidio di due gemelline di nove anni. Nonostante avesse le dimensioni e la forza per uccidere chiunque, Coffrey aveva un carattere semplice e ingenuo: era davvero lui il colpevole?', 'https://image.tmdb.org/t/p/w500/kptqTcldosy8JPf75JT16oTYUMB.jpg', '2026-10-27T18:40:54.254755', 'Tom Hanks, David Morse, Bonnie Hunt, Michael Clarke Duncan, James Cromwell, Michael Jeter, Graham Greene', NULL, NULL, NULL),
(257, 'Odissea', 2026, 'Christopher Nolan', 'Avventura, Azione, Fantasy', 'Ogni leggenda ha un prezzo. Ogni ritorno richiede un sacrificio. Mentre il mare diventa il suo più grande nemico, Ulisse affronta un cammino fatto di illusioni, battaglie e prove impossibili. Un''epica odissea che mette alla prova il coraggio di un uomo contro il volere degli dèi.', 'https://image.tmdb.org/t/p/w500/qQhInj9fw3S2bMbiEujVldthgKe.jpg', '2026-10-27T19:53:28.942003', 'Matt Damon, Tom Holland, Anne Hathaway, Robert Pattinson, Himesh Patel, Charlize Theron, John Leguizamo', NULL, NULL, NULL),
(258, 'Biancaneve e i sette nani', 1938, 'David Hand', 'Fantasy, Animazione, Famiglia', 'La perfida regina ordina al suo cacciatore di uccidere Biancaneve che lo specchio parlante ha definito la più bella del reame. La ragazza fugge. Guidata dagli animaletti del bosco, arriva alla casa dei sette nani. Eolo, Mammolo, Pisolo, Brontolo, Dotto, Gongolo e Cucciolo la accolgono e la proteggono. Quando la regina, trasformatasi in strega, arriva per ucciderla, i nanetti inseguono la cattiva che precipita da un burrone. Biancaneve, vegliata dai suoi amici come morta, torna in vita quando viene baciata dal giovane principe innamorato.', 'https://image.tmdb.org/t/p/w500/pXji7b98MIliRsylaBeCBaRbcmA.jpg', '2026-10-28T12:08:47.691061', 'Adriana Caselotti, Lucille La Verne, Harry Stockwell, Roy Atwell, Pinto Colvig, Otis Harlan, Scotty Mattraw', NULL, NULL, NULL),
(259, 'Wonka', 2023, 'Paul King', 'Commedia, Famiglia, Fantasy', 'Basato sullo straordinario protagonista de La Fabbrica di Cioccolato, il romanzo per bambini più iconico dell’autore Roald Dahl nonché uno dei libri per bambini più venduti di tutti i tempi, Wonka racconta la meravigliosa storia di come il più grande inventore, mago e cioccolataio del mondo sia diventato l''amato Willy Wonka che conosciamo oggi.', 'https://image.tmdb.org/t/p/w500/7y2M1w0nWW0Z5Ph1XzED07OYUsa.jpg', '2026-10-28T12:24:08.405259', 'Timothée Chalamet, Calah Lane, Keegan-Michael Key, Hugh Grant, Paterson Joseph, Olivia Colman, Tom Davis', NULL, NULL, NULL),
(260, 'Io sono nessuno', 2021, 'Илья Найшуллер', 'Azione, Thriller', 'Hutch Mansell, padre e marito sottostimato e trascurato, è abituato a non reagire a nessuna umiliazione. Quando una notte due ladri irrompono nella sua abitazione in periferia, rifiuta di difendere se stesso o la sua famiglia, sperando di prevenire violenze maggiori. Il figlio adolescente Blake è deluso dal suo comportamento e la moglie Becca comincia ad allontanarsi maggiormente da lui. All''indomani dell''accaduto, la rabbia che Hutch cova esplode spingendolo a manifestare tutta la violenza di cui è capace. Si ritroverà allora a dover difendere come meglio può la sua famiglia da un pericoloso avversario e ad assicurarsi di non essere mai più sottovalutato da nessuno.', 'https://image.tmdb.org/t/p/w500/iECT5xNf72P7cx9LDMrEwhGYD5O.jpg', '2026-10-28T12:36:21.655962', 'Bob Odenkirk, Алексей Серебряков, Connie Nielsen, Christopher Lloyd, Michael Ironside, Colin Salmon, RZA', NULL, NULL, NULL),
(261, 'Io sono nessuno 2', 2025, 'Timo Tjahjanto', 'Azione, Thriller, Crime', 'Il padre di periferia Hutch Mansell, un ex assassino letale, viene riportato nel suo passato violento dopo aver sventato un''invasione domestica, innescando una catena di eventi che svela i segreti sul passato di sua moglie Becca e sul suo.', 'https://image.tmdb.org/t/p/w500/8RXDbeVG9Tb0z8FWPph77uJsTkd.jpg', '2026-10-28T12:37:24.569805', 'Bob Odenkirk, Connie Nielsen, John Ortiz, Colin Hanks, RZA, Colin Salmon, Christopher Lloyd', NULL, NULL, NULL),
(262, 'L''ultima missione: Project Hail Mary', 2026, 'Phil Lord', 'Fantascienza, Avventura', 'L’insegnante di scienze Ryland Grace si sveglia su un’astronave lontano anni luce da casa senza alcun ricordo di chi sia o di come sia arrivato lì. Con il riaffiorare della sua memoria, torna alla luce lo scopo della sua missione: risolvere l’enigma della misteriosa sostanza che sta causando il collasso del Sole. Dovrà fare affidamento sulle sue conoscenze scientifiche e sulle sue capacità di pensare fuori dagli schemi per salvare dall’estinzione la vita sulla Terra, mentre un''inaspettata amicizia gli farà capire che non è solo in questa impresa.', 'https://image.tmdb.org/t/p/w500/gPC1X3mwqwX50Ye3qwwPt7iW3Ma.jpg', '2026-10-28T12:38:13.237179', 'Ryan Gosling, Sandra Hüller, James Ortiz, Lionel Boyce, Milana Vayntrub, Ken Leung, Priya Kansara', NULL, NULL, NULL),
(263, 'Robin Hood - Il prezzo del sangue', 2026, 'Michael Sarnoski', 'Avventura, Dramma, Azione', 'Il principe dei ladri, il difensore degli oppressi, l’eroe che ruba ai ricchi per dare ai poveri. Sono tutte bugie: Robin Hood non è mai stato un paladino della giustizia, ma solo un efferato bandito, e le sue “allegre scorribande” erano vere e proprie carneficine. Ma quando dedichi la tua vita al crimine, alla violenza e alla menzogna, devi essere pronto a pagarne il prezzo…', 'https://image.tmdb.org/t/p/w500/knUCsVWsLv5583lsvs2cP1VRrGx.jpg', '2026-10-28T12:41:38.251495', 'Hugh Jackman, Jodie Comer, Bill Skarsgård, Murray Bartlett, Noah Jupe, Jade Croot, Faith Delaney', NULL, NULL, NULL),
(264, 'Disclosure Day', 2026, 'Steven Spielberg', 'Fantascienza, Thriller', 'Se scoprissi che non siamo soli, se qualcuno te lo mostrasse, te lo dimostrasse, questo ti spaventerebbe?', 'https://image.tmdb.org/t/p/w500/72Yx1uisLLJy5k2P5OzBkRdEIjp.jpg', '2026-10-28T12:43:04.451307', 'Emily Blunt, Josh O''Connor, Colin Firth, Eve Hewson, Colman Domingo, Wyatt Russell, Henry Lloyd-Hughes', NULL, NULL, NULL),
(265, 'Cena con delitto - Knives Out', 2019, 'Rian Johnson', 'Commedia, Crime, Mistero', 'Quando il noto scrittore di gialli Harlan Thrombey viene trovato morto nella sua tenuta poco dopo il suo 85° compleanno, il detective Benoit Blanc, curioso e disinvolto, viene misteriosamente reclutato per investigare sull''accaduto. Dalla disfunzionale famiglia della vittima al suo devoto entourage, Blanc si muove attraverso una fitta rete di bugie, segreti e non detti, per scoprire quale sia la verità dietro la prematura morte dell''autore.', 'https://image.tmdb.org/t/p/w500/q2sh3RJ3rhRDYlJV4ZrMzzZ9Ye7.jpg', '2026-10-28T12:54:08.199601', 'Daniel Craig, Chris Evans, Ana de Armas, Jamie Lee Curtis, Michael Shannon, Don Johnson, Toni Collette', NULL, NULL, NULL),
(266, 'Glass Onion - Knives Out', 2022, 'Rian Johnson', 'Commedia, Crime, Mistero', 'L''egocentrico multimilardiario Miles Bron, proprietario della Alpha Industries, invita i suoi amici a una fuga sulla sua isola greca privata. Quando qualcuno viene trovato morto, l''investigatore Benoit Blanc si occupa del caso.', 'https://image.tmdb.org/t/p/w500/yhCxL5ebwiBwkmYrjL8gqJBZKNS.jpg', '2026-10-28T12:55:28.049428', 'Daniel Craig, Edward Norton, Janelle Monáe, Kathryn Hahn, Leslie Odom Jr., Kate Hudson, Dave Bautista', NULL, NULL, NULL),
(267, 'Wake Up Dead Man - Knives Out', 2025, 'Rian Johnson', 'Thriller, Mistero, Commedia', 'Il detective Benoit Blanc fa squadra con un giovane prete zelante per indagare su un crimine perfettamente impossibile nella chiesa di una piccola città dal passato oscuro.', 'https://image.tmdb.org/t/p/w500/db8j0xU82lzWKX0SXrPY5tFrzwA.jpg', '2026-10-28T12:56:21.058627', 'Daniel Craig, Josh O''Connor, Glenn Close, Josh Brolin, Mila Kunis, Jeremy Renner, Kerry Washington', NULL, NULL, NULL),
(268, 'Una battaglia dopo l’altra', 2025, 'Paul Thomas Anderson', 'Thriller, Crime, Commedia', 'Un gruppo di ex rivoluzionari si riunisce quando un loro perfido nemico riemerge dal loro passato, dopo sedici anni di silenzio. Il gruppo avrà il duro compito di salvare la figlia di uno di loro, prima che accada l''inevitabile.', 'https://image.tmdb.org/t/p/w500/3TjxuSfBSkhB8OvBov7Dk4L0Bcd.jpg', '2026-10-28T12:59:14.749928', 'Leonardo DiCaprio, Sean Penn, Chase Infiniti, Benicio Del Toro, Regina Hall, Teyana Taylor, Wood Harris', NULL, NULL, NULL),
(269, 'Tre uomini e una gamba', 1997, 'Aldo Baglio', 'Commedia', 'I tre amici Aldo, Giovanni e Giacomo si mettono in viaggio verso il sud Italia per il matrimonio di uno di loro con la futura moglie. Durante il tragitto il terzetto affronta varie peripezie, tra le quali l''incontro con una ragazza di cui Giacomo si innamora e il trasporto di una gamba di legno al suocero.', 'https://image.tmdb.org/t/p/w500/aUQhhVkB1XXUZ9MPGborY6MFYI8.jpg', '2026-10-28T15:55:16.856602', 'Aldo Baglio, Giovanni Storti, Giacomo Poretti, Marina Massironi, Carlo Croccolo, Maria Pia Casilio, Luciana Littizzetto', NULL, NULL, NULL),
(270, 'La leggenda di Al, John e Jack', 2002, 'Massimo Venier', 'Commedia, Crime', 'New York 1959. I tre gangster Al, John e Jack hanno il compito di uccidere Frankie per conto del boss. Sbagliano bersaglio e il boss da a loro un''altra possibilità: tenere d''occhio una persona a lui cara. Ma la fortuna non è dalla loro parte....', 'https://image.tmdb.org/t/p/w500/t7Xb04P1uCUJ1LADWD5RfqWGyDu.jpg', '2026-10-28T15:55:30.493609', 'Aldo Baglio, Giovanni Storti, Giacomo Poretti, Aldo Maccione, Antonio Catania, Giovanni Esposito, Ivano Marescotti', NULL, NULL, NULL),
(271, 'Così è la vita', 1998, 'Massimo Venier', 'Commedia', 'Soprannominato Bancomat per le sue imprese di falsificatore di carte di credito, Aldo sequestra in auto a Milano prima Giacomo, poliziotto di debole professionalità, e poi Giovanni, inventore di giocattoli. I tre se ne vanno in giro per mezza Italia (i monti dell''Abruzzo, in realtà), prima braccati dalla polizia e poi creduti morti. Diventano amici fino all''epilogo a sorpresa in chiave surrealista...', 'https://image.tmdb.org/t/p/w500/zcZxzcl79S3gaWWDGGHcFkjT9m2.jpg', '2026-10-28T15:55:50.279404', 'Aldo Baglio, Giovanni Storti, Giacomo Poretti, Marina Massironi, Antonio Catania, Francesco Pannofino, Giovanni Cacioppo', NULL, NULL, NULL),
(272, 'Chiedimi se sono felice', 2000, 'Giovanni Storti', 'Commedia', 'Aldo, Giovanni e Giacomo, tre grandi amici, sbarcano il lunario lavorando rispettivamente come comparsa nelle opere liriche, statua vivente ai Grandi Magazzini, doppiatore di ruoli irrelevanti. Ma sono anche tre aspiranti attori di teatro con un sogno nel cassetto: mettere in scena una loro particolare versione di "Cyrano de Bergerac".', 'https://image.tmdb.org/t/p/w500/7DtDnWwmZAI3dYUKNPsRy24SxV3.jpg', '2026-10-28T15:56:03.364537', 'Aldo Baglio, Giovanni Storti, Giacomo Poretti, Marina Massironi, Silvana Fallisi, Antonio Catania, Giuseppe Battiston', NULL, NULL, NULL),
(273, 'Tu la conosci Claudia?', 2004, 'Massimo Venier', 'Commedia', 'Giovanni, un uomo abitudinario la cui massima aspirazione è vedere "Passaparola" sul divano, magari con accanto la moglie Claudia.  Aldo, un tassista innamorato, innamoratissimo di Claudia.  Giacomo, un uomo solo, separato dalla moglie, rimasto un po'' troppo adolescente. Un giorno conosce Claudia e la sua vita cambia.  E'' la stessa Claudia a raccontarci di loro a partire da un prologo che non va perso per nessun motivo.', 'https://image.tmdb.org/t/p/w500/4MbovTjSHv2AvcK39qUaEYeNuyl.jpg', '2026-10-28T15:56:18.517114', 'Aldo Baglio, Giovanni Storti, Giacomo Poretti, Paola Cortellesi, Ottavia Piccolo, Sandra Ceccarelli, Marco Messeri', NULL, NULL, NULL),
(274, 'Dirty Dancing - Balli proibiti', 1987, 'Emile Ardolino', 'Dramma, Musica, Romance', 'Aspettandosi la solita noia che accompagna un''estate nelle Catskills con la sua famiglia, la diciassettenne Frances "Baby" Houseman si ritrova nei panni di una ballerina professionista con l''amore che bussa inaspettatamente.', 'https://image.tmdb.org/t/p/w500/4wj0T7FSD2FohE1IHAXU3brpL4U.jpg', '2026-10-28T16:39:33.768258', 'Jennifer Grey, Patrick Swayze, Jerry Orbach, Cynthia Rhodes, Jack Weston, Jane Brucker, Kelly Bishop', NULL, NULL, NULL),
(275, 'Qualcosa è cambiato', 1997, 'James L. Brooks', 'Dramma, Commedia, Romance', 'Lui è un misantropo razzista, villano, paranoico, ossessionato da tic e complessi. Ma nella sua eccentrica vita stanno per entrare un pittore omosessuale con il suo delizioso cagnolino e una ragazza-madre che fa la cameriera.', 'https://image.tmdb.org/t/p/w500/tmwubiSQ4IwJbRqSoyNFb7tMAVg.jpg', '2026-10-28T16:43:56.113395', 'Jack Nicholson, Helen Hunt, Greg Kinnear, Cuba Gooding Jr., Shirley Knight, Jesse James, Yeardley Smith', NULL, NULL, NULL),
(276, 'Arrivano i prof', 2018, 'Ivan Silvestrini', 'Commedia', 'Mentre (quasi) tutti festeggiano le promozioni all''esame di maturità, al liceo Alessandro Manzoni c''è grande preoccupazione: solo il 12% degli studenti è riuscito a conseguire il diploma. Il Manzoni ha un primato assoluto: è il peggior liceo d''Italia. Non sapendo più che soluzioni adottare, il Preside accoglie la proposta del Provveditore e decide di fare un ultimo, estremo, rischioso tentativo: reclutare i peggiori insegnanti in circolazione selezionati dall''algoritmo ministeriale nella speranza che dove hanno fallito i migliori, possano riuscire i peggiori. Obiettivo: avere almeno il 50% di promossi.', 'https://image.tmdb.org/t/p/w500/mBc8UOa5VxdgLfY5qYWZvuboJKq.jpg', '2026-10-28T17:27:20.515261', 'Claudio Bisio, Lino Guanciale, Maurizio Nichetti, Maria Di Biase, Andrea Pennacchi, Pietro Ragusa, Alessio Sakara', NULL, NULL, NULL),
(277, 'The Rock', 1996, 'Michael Bay', 'Azione, Avventura, Thriller', 'The Rock veniva chiamata la prigione di Alcatraz, chiusa nel 1963. La leggenda racconta che mai un solo detenuto sia riuscito a evadere da quella "rocca" situata proprio nel mezzo della baia di San Francisco. È proprio in quella prigione, divenuta meta turistica, che un generale dei marines nasconde tre missili con testate di gas nervino: vuole protestare per come il governo ha trattato i reduci del Vietnam. Se non gli daranno un centinaio di milioni di dollari farà esplodere i missili su San Francisco. A risolvere la situazione vengono chiamati un chimico e un ex agente inglese, l''unico detenuto che sia riuscito, trent''anni prima, a evadere da Alcatraz. Complice un certo pentimento del generale, i due riescono nell''impresa.', 'https://image.tmdb.org/t/p/w500/leBDsXawQQ6ue7xlB6fIjXEZMZz.jpg', '2026-10-29T22:03:56.35466', 'Sean Connery, Nicolas Cage, Ed Harris, John Spencer, David Morse, William Forsythe, Michael Biehn', NULL, NULL, NULL),
(278, 'La fabbrica di cioccolato', 2005, 'Tim Burton', 'Avventura, Commedia, Famiglia, Fantasy', 'Charlie Bucket, proviene da una famiglia povera, e spende la maggior parte del suo tempo a sognare la cioccolata che adora, ma che di rado può permettersela. La sua vita cambia quando Willy Wonka, proprietario di una famosissima fabbrica di cioccolato, mette in palio cinque biglietti, nascosti in cinque barrette di cioccolato. I bambini che troveranno uno di questi biglietti potranno fare un tour nella fantastica fabbrica di cioccolato. Charlie trova miracolosamente un biglietto vincente...', 'https://image.tmdb.org/t/p/w500/w2Q8Zx1RCM0aAuG36nOXXJ6pV0u.jpg', '2026-10-29T22:19:53.729848', 'Johnny Depp, Freddie Highmore, David Kelly, Helena Bonham Carter, Noah Taylor, Missi Pyle, James Fox', NULL, NULL, NULL),
(279, 'Ritorno al futuro', 1985, 'Robert Zemeckis', 'Avventura, Commedia, Fantascienza', 'Marty McFly è stato catapultato per errore nel 1955, grazie alla macchina del tempo ideata dal suo amico scienziato Doc. Non avendo più "carburante" per poter tornare nel futuro si rivolge alla versione più giovane di Doc, che nonostante l''incredulità iniziale si farà in quattro per aiutarlo. Ma nel 1955 non è solo Doc ad essere più giovane, Marty infatti si imbatte casualmente nei suoi genitori, all''epoca teenager, ma l''incontro aggiungerà altri problemi.', 'https://image.tmdb.org/t/p/w500/isqoi7kuUsR5Drlqdh4ZfMULgox.jpg', '2026-10-29T22:28:51.673722', 'Michael J. Fox, Christopher Lloyd, Crispin Glover, Lea Thompson, Claudia Wells, Thomas F. Wilson, Marc McClure', NULL, NULL, NULL),
(280, 'Ritorno al futuro - Parte II', 1989, 'Robert Zemeckis', 'Avventura, Commedia, Fantascienza', 'Il film comincia dove terminava il primo capitolo, ovvero con Marty e Jennifer che partono insieme allo scienziato Doc, inventore della macchina del tempo, per il 2015 allo scopo di evitare che il futuro dei loro figli possa essere in pericolo. Ma la situazione precipita e ad essere in pericolo non è più il futuro, ma il passato. Marty dovrà tornare nuovamente nel 1955 e...', 'https://image.tmdb.org/t/p/w500/AbwX5BzdmfA0WFBxBF909Gf4Sop.jpg', '2026-10-29T22:29:15.985437', 'Michael J. Fox, Christopher Lloyd, Lea Thompson, Thomas F. Wilson, Elisabeth Shue, James Tolkan, Jeffrey Weissman', NULL, NULL, NULL),
(281, 'Ritorno al futuro - Parte III', 1990, 'Robert Zemeckis', 'Avventura, Commedia, Fantascienza', 'Per questa terza, conclusiva, puntata della trilogia, Marty McFly è costretto a tornare indietro nel tempo fino al 1885 per salvare Doc, che vi era stato catapultato al termine del secondo capitolo. Questa volta tornare nel futuro sarà ancora più difficile.', 'https://image.tmdb.org/t/p/w500/iBfwdp2Sp4aWH9QaHUqFq25sxIU.jpg', '2026-10-29T22:29:47.144293', 'Michael J. Fox, Christopher Lloyd, Mary Steenburgen, Thomas F. Wilson, Lea Thompson, Elisabeth Shue, Matt Clark', NULL, NULL, NULL),
(282, 'Le ali della libertà', 1994, 'Frank Darabont', 'Dramma, Crime', 'Siamo nel 1946. Processato per l''omicidio della moglie e del suo amante, Andy, un bancario del New England, viene condannato a un doppio ergastolo e recluso nel penitenziario di Shawshank. All''inizio è vittima delle violenze dei reclusi, poi però diventa il consulente finanziario delle guardie. Scopre così che il direttore falsifica i libri contabili intestando i conti a un fittizio Randall Stevens. Fuggito di prigione attraverso un tunnel costruito negli anni, Andy assume l''identità di Randall Stevens, denuncia il direttore e va in Messico.', 'https://image.tmdb.org/t/p/w500/9OxcvTJwZDjQTFvY2NxiwnSrQS6.jpg', '2026-10-29T22:34:52.192377', 'Tim Robbins, Morgan Freeman, Bob Gunton, William Sadler, Clancy Brown, Gil Bellows, James Whitmore', NULL, NULL, NULL),
(283, 'Qualcuno volò sul nido del cuculo', 1975, 'Miloš Forman', 'Dramma', 'Candle McMurphy, arrestato per piccoli reati, viene portato in una clinica psichiatrica: tenta di fingersi pazzo per sfuggire al carcere. Qui viene a contatto con gli altri pazienti dei quali diventa ben presto il beniamino: si prende gioco delle sedute di psicoanalisi, si improvvisa telecronista, organizza una piccola gita in barca. L''ospedale è diretto dalla ferrea capoinfermiera, la signorina Ratched che ha organizzato la vita dei pazienti secondo regole di intransigente disciplina.', 'https://image.tmdb.org/t/p/w500/hpg2j8FhnnmbiRpoOU09M0sffJu.jpg', '2026-10-29T22:35:23.746538', 'Jack Nicholson, Brad Dourif, Louise Fletcher, Danny DeVito, William Redfield, Scatman Crothers, Christopher Lloyd', NULL, NULL, NULL),
(284, 'Butch Cassidy', 1969, 'George Roy Hill', 'Western, Crime, Dramma', 'Butch e Sundance sono due rapinatori che dopo ogni colpo, si rifugiano da una maestra innamorata di Sundance e corteggiata da Butch. Ma un giorno la Union Pacific, bersaglio di una loro rapina assolda un gruppo di guardie private ed allora i due rapinatori sono costretti a cambiare aria...', 'https://image.tmdb.org/t/p/w500/7T9YNd236L9JXLeNTayHZgTrSHJ.jpg', '2026-10-29T22:35:52.914477', 'Paul Newman, Robert Redford, Katharine Ross, Strother Martin, Henry Jones, Jeff Corey, George Furth', NULL, NULL, NULL),
(285, 'La stangata', 1973, 'George Roy Hill', 'Commedia, Crime, Dramma', 'Johnny Hooker e il suo amico Luther Coleman sono due truffatori di strada. Dopo aver raggirato il corriere del potente gangster Doyle Lonnegan, Luther viene ucciso per ritorsione e Hooker è costretto a fuggire e a nascondersi. Desiderando vendicare Luther, il giovane chiede aiuto ad un vecchio amico del defunto, Henry Gondorff, uno dei più bravi ed esperti truffatori degli Stati Uniti. Insieme organizzano una "stangata" ai danni di Lonnegan, creando una finta agenzia di scommesse in cui il boss crede di poter vincere facilmente delle ingenti somme di denaro, grazie a informazioni riservate.', 'https://image.tmdb.org/t/p/w500/jnD4EA8uULiNGxk96jfheznoEwz.jpg', '2026-10-29T22:36:17.989296', 'Paul Newman, Robert Redford, Robert Shaw, Charles Durning, Ray Walston, Eileen Brennan, Harold Gould', NULL, NULL, NULL),
(286, 'Psyco', 1960, 'Alfred Hitchcock', 'Horror, Thriller, Mistero', 'Marion Crane, impiegata in una società immobiliare, scappa con 40.000$ rubati dalle casse della ditta. Durante la fuga verso casa del fidanzato però, decide di fermarsi nel Motel gestito dal giovane Norman Bates e dalla madre, che però vive rintanata nella casa attigua al Motel stesso.  Il capolavoro di Alfred Hitchcock.', 'https://image.tmdb.org/t/p/w500/tdqX0MWaFHuGwUygYn7j6eluOdP.jpg', '2026-10-29T22:36:46.116801', 'Anthony Perkins, Janet Leigh, Vera Miles, John Gavin, Martin Balsam, John McIntire, Simon Oakland', NULL, NULL, NULL),
(287, 'Il delitto perfetto', 1954, 'Alfred Hitchcock', 'Thriller, Crime, Dramma', 'Margot è sposata con Tony, ma i loro rapporti non sono certo idilliaci: lui vive alle spalle di lei perché è benestante e perché è un fannullone, ed inoltre lei è innamorata di uno scrittore americano e medita il divorzio, che sarebbe la rovina per suo marito. Così Tony medita di uccidere Margot per intascare i suoi soldi e vivere di rendita.', 'https://image.tmdb.org/t/p/w500/feVfUSdS9k39GSqJjeMLlafV8M6.jpg', '2026-10-29T22:37:29.651728', 'Ray Milland, Grace Kelly, Robert Cummings, John Williams, Anthony Dawson, Leo Britt, Patrick Allen', NULL, NULL, NULL),
(288, 'Gli uccelli', 1963, 'Alfred Hitchcock', 'Horror, Thriller', 'Melanie Daniels incontra Mitch Brenner in un negozio di animali di San Francisco. Lui vorrebbe comprare una coppia di inseparabili per regalarli a sua sorella per il suo compleanno, lei finge di essere una commessa del negozio, lui non le crede, ma sta al gioco. Melanie decide poi di comprare una coppia di inseparabili e di andare a Bodega Bay, un tranquillo paesino costiero, dove Mitch passa i suoi fine settimana con la sorellina e la madre, per fargli una sorpresa. Al suo arrivo viene attaccata da un gabbiano, e sarà il primo di una lunga, inspiegabile serie di attacchi da parte degli uccelli...', 'https://image.tmdb.org/t/p/w500/omnOJCmTGJoxCRJorWIEweu1JTN.jpg', '2026-10-29T22:38:04.403178', 'Tippi Hedren, Rod Taylor, Jessica Tandy, Suzanne Pleshette, Veronica Cartwright, Ethel Griffies, Charles McGraw', NULL, NULL, NULL),
(289, 'Capitani coraggiosi', 1937, 'Victor Fleming', 'Avventura, Dramma, Famiglia', 'Frank Burton Cheyne, un ricco industriale trascura il figlio adolescente Harvey, al punto da trasformarlo in un ribelle arrogante e raccontafrottole. Harvey per i suoi modi arroganti, a scuola viene evitato da tutti, finché un giorno nella tipografia dell''istituto è coinvolto in una zuffa con un suo coetaneo, e ha la peggio. Il Direttore e il Maestro di Harvey fanno visita al padre, comunicandogli la decisione di sospenderlo per tre mesi, raccontandogli la verità sul comportamento di suo figlio, Frank capisce che è ora di riprendere in mano la situazione, prima che sia troppo tardi. Frank porta con se il figlio Harvey in una crociera su una delle sue navi, ma anche li per fare lo sbruffone con due ragazzini ruzzola in mare. Per sua fortuna viene ripescato da Manuel Fidello, un pescatore di professione che lo tira a bordo della sua barca, lo rianima e lo porta sul peschereccio da cui è partito.', 'https://image.tmdb.org/t/p/w500/xez8YMw0BhIS7bY0f1rxfdzQcX9.jpg', '2026-10-29T22:39:42.126243', 'Freddie Bartholomew, Spencer Tracy, Lionel Barrymore, Melvyn Douglas, Charley Grapewin, Mickey Rooney, John Carradine', NULL, NULL, NULL),
(290, 'Norimberga', 2025, 'James Vanderbilt', 'Storia, Dramma', 'All’indomani della Seconda guerra mondiale, mentre il mondo è ancora sconvolto dagli orrori dell’Olocausto, al tenente colonnello Douglas Kelley, psichiatra dell’esercito americano, viene affidato un incarico senza precedenti: valutare la sanità mentale di Hermann Göring, il famigerato ex braccio destro di Hitler, e di altri alti gerarchi nazisti. Allo stesso tempo, gli Alleati — guidati dal giudice Robert H. Jackson — affrontano l’impresa titanica di istituire un tribunale internazionale, per far sì che il regime nazista risponda dei propri crimini di fronte alla storia. Nel silenzio delle celle, Kelley ingaggia un intenso duello psicologico con Göring, uomo carismatico e manipolatore. Da quello scontro emerge una domanda che ancora oggi tormenta la coscienza del mondo:stavano eseguendo ordini, erano pazzi… o semplicemente malvagi? Sul palcoscenico della storia si apre così il processo di Norimberga, un evento che ha cambiato per sempre la storia e l’umanità.', 'https://image.tmdb.org/t/p/w500/ucZHG8KD2A9Czl1aZz1f4bIvbLR.jpg', '2026-10-30T19:14:57.279267', 'Rami Malek, Russell Crowe, Michael Shannon, Leo Woodall, John Slattery, Richard E. Grant, Mark O''Brien', NULL, NULL, NULL),
(291, 'Oppenheimer', 2023, 'Christopher Nolan', 'Dramma, Storia, Guerra', 'La storia del ruolo di J. Robert Oppenheimer, i cui studi condussero alle scoperte legate alla bomba atomica, con il conseguente utilizzo durante le stragi di Hiroshima e Nagasaki durante la Seconda Guerra Mondiale.', 'https://image.tmdb.org/t/p/w500/fRtaxfyynWMJI6DhejyA6JOzVTB.jpg', '2026-10-30T19:15:25.217907', 'Cillian Murphy, Emily Blunt, Matt Damon, Robert Downey Jr., Florence Pugh, Josh Hartnett, Casey Affleck', NULL, NULL, NULL),
(292, 'Jojo Rabbit', 2019, 'Taika Waititi', 'Commedia, Guerra, Dramma', 'Jojo, un bambino cresciuto dalla sola madre, ha come unico alleato il suo amico immaginario Adolf Hitler. Il suo ingenuo patriottismo viene però messo alla prova quando incontra una ragazzina che stravolge le sue convinzioni sul mondo, costringendolo ad affrontare le sue paure più grandi.', 'https://image.tmdb.org/t/p/w500/2vv0tEFH10YG3hMRCOhiWsw7bOk.jpg', '2026-10-30T19:15:43.65732', 'Roman Griffin Davis, Thomasin McKenzie, Scarlett Johansson, Taika Waititi, Sam Rockwell, Rebel Wilson, Alfie Allen', NULL, NULL, NULL),
(293, 'Joker', 2019, 'Todd Phillips', 'Crime, Thriller, Dramma', 'Arthur Fleck vive con l''anziana madre in un palazzone fatiscente e sbarca il lunario facendo pubblicità per la strada travestito da clown, in attesa di avere il giusto materiale per realizzare il desiderio di fare il comico. La sua vita, però, è una tragedia: ignorato, calpestato, bullizzato, preso in giro da da chiunque, ha sviluppato un tic nervoso che lo fa ridere a sproposito incontrollabilmente, rendendolo inquietante e allontanando ulteriormente da lui ogni possibile relazione sociale. Ma un giorno Arthur non ce la fa più e reagisce violentemente, pistola alla mano. Mentre la polizia di Gotham City dà la caccia al clown killer, la popolazione lo elegge a eroe metropolitano, simbolo della rivolta degli oppressi contro l''arroganza dei ricchi.', 'https://image.tmdb.org/t/p/w500/y1AthYH1r2j4N4cYn2HdrEGgrnJ.jpg', '2026-10-30T19:16:18.592482', 'Joaquin Phoenix, Robert De Niro, Zazie Beetz, Frances Conroy, Brett Cullen, Shea Whigham, Bill Camp', NULL, NULL, NULL),
(294, 'Parasite', 2019, '봉준호', 'Commedia, Thriller, Dramma', 'Tutta la famiglia di Ki-taek è senza lavoro. Ki-taek è particolarmente interessata allo stile di vita della ricchissima famiglia Park. Un giorno, suo figlio riesce a farsi assumere dai Park e le due famiglie si ritrovano così intrecciate da una serie di eventi incontrollabili.', 'https://image.tmdb.org/t/p/w500/mMM8kcfspicib7AmPTvf97Rarwn.jpg', '2026-10-30T19:16:34.166517', 'Song Kang-ho, 이선균, Cho Yeo-jeong, Choi Woo-shik, 박소담, 이정은, Jang Hye-jin', NULL, NULL, NULL),
(295, 'Coco', 2017, 'Lee Unkrich', 'Famiglia, Animazione, Musica, Avventura', 'Nonostante il divieto di musica che dura da generazioni nella sua famiglia, Miguel sogna di diventare un musicista affermato come il suo idolo, Ernesto de la Cruz. Disperato di dimostrare il suo talento, Miguel si ritrova nella splendida e colorata Terra dei Morti, seguendo una misteriosa catena di eventi. Lungo il cammino incontra il fascinante imbroglione Hector e insieme partono per un viaggio straordinario per svelare la vera storia della famiglia di Miguel.', 'https://image.tmdb.org/t/p/w500/l5qUox5uroubMi8sihD9RGPbcwO.jpg', '2026-10-30T19:16:48.745867', 'Anthony Gonzalez, Gael García Bernal, Benjamin Bratt, Alanna Ubach, Renée Victor, Jaime Camil, Alfonso Arau', NULL, NULL, NULL),
(296, 'The Nice Guys', 2016, 'Shane Black', 'Commedia, Crime, Azione', 'Nella Los Angeles degli anni ‘70, libertina, stravagante e decisamente trendy, un investigatore privato, Holland March (Ryan Gosling), e un detective senza scrupoli, Jackson Healy (Russell Crowe), si alleano per risolvere il caso di una ragazza scomparsa e la morte di una porno star che apparentemente non sembrerebbero correlate: scopriranno che un semplice omicidio nasconde il caso del secolo!', 'https://image.tmdb.org/t/p/w500/clq4So9spa9cXk3MZy2iMdqkxP2.jpg', '2026-10-30T19:17:17.577086', 'Russell Crowe, Ryan Gosling, Angourie Rice, Matt Bomer, Margaret Qualley, Yaya DaCosta, Keith David', NULL, NULL, NULL),
(297, 'I segreti di Wind River', 2017, 'Taylor Sheridan', 'Crime, Mistero, Thriller', 'Cory Lambert, esperto inseguitore e cacciatore, scopre il corpo congelato di una ragazza adolescente. Fa allora squadra con Jane Banner, nuova agente dell''Fbi, per capire cosa sia accaduto alla giovane e chi sia il responsabile di un così macabro crimine. Man mano che l''indagine si approfondisce, la vita dei due investigatori è sempre più a rischio.', 'https://image.tmdb.org/t/p/w500/5OI9QQ24lrrS1IGB6RVuPL5GcZl.jpg', '2026-10-30T19:17:41.93064', 'Jeremy Renner, Elizabeth Olsen, Gil Birmingham, Graham Greene, Jon Bernthal, Kelsey Asbille, Teo Briones', NULL, NULL, NULL),
(298, 'Revenant - Redivivo', 2015, 'Alejandro G. Iñárritu', 'Western, Dramma, Avventura', 'Sono gli anni Venti del diciannovesimo secolo. Soldati, esploratori, cacciatori di pelli, mercenari solcano i territori ancora sconosciuti d''America per trarne profitto. Glass è l''uomo che meglio di tutti i suoi compagni di spedizione conosce la terra impervia in cui si sono inoltrati. Il suo compito è riportare la compagnia al forte e tutto ciò che lo preoccupa è proteggere suo figlio, un ragazzo indiano. Lo scontro con un grizzly lo lascia in condizioni prossime alla fine. Il più arrogante della compagnia, Fitzgerald, si offre di restare per dargli sepoltura, ma lo tradisce orribilmente. La volontà di vendicarsi rimetterà in piedi Glass e darà inizio ad un''odissea leggendaria.', 'https://image.tmdb.org/t/p/w500/cw8HPomOzNql3l4xdaJJ8HGIZds.jpg', '2026-10-30T19:17:56.128077', 'Leonardo DiCaprio, Tom Hardy, Domhnall Gleeson, Will Poulter, Forrest Goodluck, Duane Howard, Arthur Redcloud', NULL, NULL, NULL),
(299, 'American Sniper', 2014, 'Clint Eastwood', 'Guerra, Azione', 'Il cecchino Chris Kyle viene inviato in Iraq con una sola missione: proteggere i propri compagni. Grazie alla sua precisione millimetrica e alla sue gesta eroiche salverà innumerevoli vite guadagnandosi il soprannome di "Legend". Tuttavia, la sua reputazione cresce anche dietro le linee nemiche facendolo diventare uno degli obiettivi primari. Nonostante ciò, riuscirà a far ritorno a casa scoprendo che la guerra è qualcosa che difficilmente riuscirà a lasciarsi alle spalle.', 'https://image.tmdb.org/t/p/w500/AdYOjcPT5PHyDsyxBgjCLtIepQR.jpg', '2026-10-30T19:19:06.889908', 'Bradley Cooper, Sienna Miller, Kyle Gallner, Cole Konis, Ben Reed, Elise Robertson, Keir O''Donnell', NULL, NULL, NULL),
(300, 'Edge of Tomorrow - Senza domani', 2014, 'Doug Liman', 'Azione, Fantascienza', 'La storia di “Edge of Tomorrow” si svolge in un futuro prossimo in cui una razza aliena ha colpito la Terra con un implacabile assalto che nessuno esercito al mondo riesce a respingere. Il tenente William Cage è un ufficiale che non ha mai partecipato neppure a un giorno di combattimento quando viene inviato senza tanti complimenti a compiere una missione suicida. Ucciso in pochi minuti, incredibilmente Cage si risveglia ed è costretto a combattere e a morire ancora e ancora, in un continuo loop temporale. Ma a ogni scontro Cage diventa sempre più abile nell’affrontare il nemico, insieme alla combattente delle Forze Speciali Rita Vrataski. Mentre Cage e Rita continuano la lotta contro gli alieni, la ripetizione di ogni battaglia li fa avvicinare sempre più alla soluzione per annientare il nemico.', 'https://image.tmdb.org/t/p/w500/AbzpU4ookiyWFmiq1bTZwjNl7Y1.jpg', '2026-10-30T19:19:34.048684', 'Tom Cruise, Emily Blunt, Brendan Gleeson, Bill Paxton, Jonas Armstrong, Tony Way, Kick Gurry', NULL, NULL, NULL),
(301, 'All is lost - Tutto è perduto', 2013, 'J.C. Chandor', 'Azione, Avventura, Dramma', 'Perso in mezzo all’Oceano Indiano, il viaggiatore solitario senza identità (Redford) si accorge che il suo yacht di 14 metri inizia ad imbarcare acqua dopo aver urtato contro un container che galleggiava in alto mare. Con il navigatore e la radio fuori uso, l’uomo si ritrova nel mezzo di una violenta tempesta. Nonostante la riparazione dei danni allo scafo e la sua intuizione da esperto marinaio unita ad una forza che smentisce la sua età, l’uomo riesce a malapena a sopravvivere alla tempesta. Avendo a disposizione un sestante ed alcune carte nautiche, per tracciare una rotta verso la salvezza, è costretto ad affidarsi unicamente alle correnti oceaniche nella speranza di incrociare delle barche di passaggio. Sotto un sole battente, accerchiato dagli squali e con le riserve alimentari che iniziavano a scarseggiare, l’ intraprendente marinaio si è trovato molto spesso faccia a faccia con la morte.', 'https://image.tmdb.org/t/p/w500/phZLbxYVfE98S0d1G3HdUCc7fqc.jpg', '2026-10-30T19:20:08.976986', 'Robert Redford', NULL, NULL, NULL),
(302, 'Django Unchained', 2012, 'Quentin Tarantino', 'Dramma, Western', 'Stati Uniti del Sud, alla vigilia della guerra civile. Il cacciatore di taglie di origine tedesca dottor King Schultz, su un carretto da dentista, è alla ricerca dei fratelli Brittle, per consegnarli alle autorità piuttosto morti che vivi e incassare la ricompensa. Per scovarli, libera dalle catene lo schiavo Django, promettendogli la libertà a missione completata. Tra i due uomini nasce così un sodalizio umano e professionale che li conduce attraverso l''America delle piantagioni e degli orrori razzisti alla ricerca dei criminali in fuga e della moglie di Django, Broomhilda, venduta come schiava a qualche possidente negriero.', 'https://image.tmdb.org/t/p/w500/igYptikalrjsMueMx6rz15lE4Ts.jpg', '2026-10-30T19:20:35.345275', 'Jamie Foxx, Christoph Waltz, Leonardo DiCaprio, Kerry Washington, Samuel L. Jackson, Walton Goggins, Dennis Christopher', NULL, NULL, NULL),
(303, 'Vita di Pi', 2012, 'Ang Lee', 'Avventura, Dramma', 'Il giovane Piscine Molitor Patel, detto Pi, è cresciuto con la famiglia a contatto con lo zoo paterno, mescolando fin dall''infanzia sogno e realtà. Quando il padre ha esigenze di denaro e sceglie di trasferirsi in Canada per vendere lo zoo, Pi ancora non può intuire cosa lo attenderà nelle vastità oceaniche. Di fronte a una tempesta terrificante, la nave affonda, lasciando in breve tempo Pi con un''unica compagna di viaggio: la tigre Richard Parker, l''animale più temuto dello zoo paterno. Pi potrà solo fare affidamento alla propria intelligenza per poter sopravvivere e convivere con la tigre.', 'https://image.tmdb.org/t/p/w500/hQc6NHCshzZmi7cR6ggQMKlf17i.jpg', '2026-10-30T19:20:52.491293', 'Suraj Sharma, Irrfan Khan, Ayush Tandon, Gautam Belur, आदिल हुसैन, Tabu, Ayaan Khan', NULL, NULL, NULL),
(304, 'Midnight in Paris', 2011, 'Woody Allen', 'Fantasy, Commedia, Romance', 'Una storia romantica ambientata a Parigi, nella quale s''intrecciano le vicende di una famiglia, in Francia per affari, e di due giovani fidanzati prossimi alle nozze; tutti alle prese con esperienze che cambieranno per sempre le loro vite. Il film è anche la storia del grande amore di un giovane uomo per una città, Parigi, e dell''illusione di tutti coloro che pensano che se avessero avuto una vita diversa sarebbero stati molto più felici.', 'https://image.tmdb.org/t/p/w500/hfdsTXO6wIJ9uywIgnqzNYDWYQK.jpg', '2026-10-30T19:21:11.445601', 'Owen Wilson, Rachel McAdams, Kathy Bates, Kurt Fuller, Adrien Brody, Carla Bruni, Marion Cotillard', NULL, NULL, NULL),
(305, 'Il cigno nero', 2010, 'Darren Aronofsky', 'Dramma, Thriller, Horror', 'Nina è una ballerina del New York City Ballet che sogna il "ruolo" e un amore che spezzi l''adolescenza mai finita. Incalzata dalla madre, si sottopone ad un allenamento sotto lo sguardo di Thomas Leroy. Coreografo appassionato e deciso a farne una stella, Leroy le assegna la parte della protagonista nella sua versione del "Lago dei cigni". Sul palcoscenico Nina sarà Odette. Eterea e piena di grazia Nina incarna alla perfezione il candore del cigno bianco e con difficoltà il suo doppio nero e tenebroso, che in una superba variazione ingannerà il suo principe e la voterà al suicidio. La ricerca del suo lato oscuro e della consapevolezza della propria sessualità la condurranno verso una tempesta emozionale e all''incontro con Lily, insidiosa rivale in nero. Dietro le quinte Nina si strugge e si predispone a ''doppiare'' il suo cigno bianco.', 'https://image.tmdb.org/t/p/w500/dywocnQY2FhEpDeV56Vl3yHw0oy.jpg', '2026-10-30T19:25:20.521796', 'Natalie Portman, Mila Kunis, Vincent Cassel, Barbara Hershey, Winona Ryder, Benjamin Millepied, Ksenia Solo', NULL, NULL, NULL),
(306, 'Inception', 2010, 'Christopher Nolan', 'Azione, Fantascienza, Crime', 'Dom Cobb possiede una qualifica speciale: è in grado di inserirsi nei sogni altrui per prelevare i segreti nascosti nel più profondo del subconscio. Viene contattato da Saito, un potentissimo industriale di origine giapponese, il quale gli chiede di tentare l''operazione opposta. Non deve prelevare pensieri celati ma inserire un''idea che si radichi nella mente di una persona. Costui è Robert Fischer Jr. il quale, alla morte dell''anziano e dittatoriale genitore, dovrà convincersi che l''unica cosa che può fare è distruggere l''impero ereditato. Saito avrà allora campo libero. In cambio offrirà a Cobb la possibilità di rientrare negli Stati Uniti dove è ricercato per omicidio. Cobb accetta e si fa affiancare da un team di cui entra a far parte la giovane Ariane, architetto abilissimo nella costruzione di spazi virtuali.', 'https://image.tmdb.org/t/p/w500/5QHWgqaBxZI1eM5e3YhyKzY5o3z.jpg', '2026-10-30T19:25:49.902889', 'Leonardo DiCaprio, Joseph Gordon-Levitt, Ken Watanabe, Tom Hardy, Elliot Page, Dileep Rao, Cillian Murphy', NULL, NULL, NULL),
(307, 'Shutter Island', 2010, 'Martin Scorsese', 'Dramma, Thriller, Mistero', 'Nel 1954, i due agenti federali Teddy Daniels e Chuck Aule vengono inviati all''istituto mentale Ashecliffe di Shutter Island, al largo della costa est, per indagare sull''improvvisa scomparsa di Rachel Solando, una pericolosa infanticida. Il direttore dell''istituto, il dottor Cawley, e i vari infermieri sostengono che la madre assassina si sia come dileguata dalla sua stanza senza lasciare alcuna traccia, ma l''agente Daniels nutre fin dal principio dei forti sospetti sullla gestione dell''ospedale da parte del dottor Cawley e del suo medico assistente, il dottor Naehring. Un uragano costringe i due agenti a protrarre il soggiorno sull''isola, durante il quale le indagini proseguono e particolari sempre più inquietanti emergono, mentre Daniels continua ad avere delle visioni che riguardano la moglie defunta e le sue esperienze di guerra contro gli ufficiali nazisti.', 'https://image.tmdb.org/t/p/w500/kgPRqDDr5RFkIly6CJrBPHYs2qS.jpg', '2026-10-30T19:26:07.336201', 'Leonardo DiCaprio, Mark Ruffalo, Ben Kingsley, Max von Sydow, Michelle Williams, Emily Mortimer, Patricia Clarkson', NULL, NULL, NULL),
(308, 'Avatar', 2009, 'James Cameron', 'Fantascienza, Azione, Avventura', 'Jake Sully è un marine costretto su una sedia a rotelle che accetta di trasferirsi sul pianeta Pandora in sostituzione del fratello morto, la cui missione era quella di esplorare il pianeta. Essendo l''atmosfera del pianeta tossica per gli umani sono stati creati degli esseri simili ai nativi Na''vi che possono essere ''guidati'' dagli umani. Pandora è un enorme giacimento di un minerale prezioso per la Terra dove le fonti di energia sono azzerate. Gli indigeni Na''vi non hanno intenzione di essere colonizzati. Il compito iniziale dell''avatar di Jake sarà quello di conoscerne usi e costumi e di farsi accettare all''interno delle comunità indigene. Jake conosce così Neytiri, una guerriera Na''vi figlia del capo tribù. Da lei impara a divenire un guerriero molto diverso dal marine che è stato e se ne innamora ricambiato.', 'https://image.tmdb.org/t/p/w500/cu6CTvQqVvaTUmWNGWydpf7EzmV.jpg', '2026-10-30T19:26:56.005175', 'Sam Worthington, Zoe Saldaña, Sigourney Weaver, Stephen Lang, Michelle Rodriguez, Giovanni Ribisi, Joel David Moore', NULL, NULL, NULL),
(309, 'Avatar: Fuoco e cenere', 2025, 'James Cameron', 'Fantascienza, Avventura, Fantasy', 'In seguito alla devastante guerra contro la RDA e alla perdita del loro figlio maggiore, Jake Sully e Neytiri affrontano una nuova minaccia su Pandora: il Popolo della Cenere, una tribù Na''vi violenta e assetata di potere guidata dagli spietati Varang. La famiglia di Jake deve lottare per la propria sopravvivenza e per il futuro di Pandora in un conflitto che li spinge ai loro limiti emotivi e fisici.', 'https://image.tmdb.org/t/p/w500/kvivMhuEuzXuaj0UMjAAmrXVvWn.jpg', '2026-10-30T19:27:46.621905', 'Sam Worthington, Zoe Saldaña, Sigourney Weaver, Stephen Lang, Oona Chaplin, Jack Champion, Kate Winslet', NULL, NULL, NULL),
(310, 'Avatar: La via dell''acqua', 2022, 'James Cameron', 'Azione, Avventura, Fantascienza', 'Jake vive felicemente la sua vita insieme a Neytiri ma Pandora nasconde ancora numerosi misteri. Quando una vecchia, familiare minaccia torna ad affacciarsi per terminare quel che era stato iniziato un tempo, Jake dovrà nuovamente collaborare con l''esercito dei Na''vi per proteggere il loro incredibile pianeta. In veste di patriarca si ritroverà a dover combattere una dura guerra contro gli umani. Jake e Neytiri saranno pertanto costretti a lasciare la loro casa ed esplorare varie regioni di Pandora...', 'https://image.tmdb.org/t/p/w500/idul2fSUPkk0EHP92EzmES6KGW4.jpg', '2026-10-30T19:28:06.361854', 'Sam Worthington, Zoe Saldaña, Sigourney Weaver, Stephen Lang, Kate Winslet, Cliff Curtis, Joel David Moore', NULL, NULL, NULL),
(311, 'Up', 2009, 'Pete Docter', 'Animazione, Commedia, Famiglia, Avventura', 'Carl Fredricksen ha trascorso tutta la vita sognando di esplorare il mondo e di vivere appieno ogni istante. Ma a 78 anni, la vita sembra essergli sfuggita di mano, finché un colpo di fortuna (e un tenace esploratore di 8 anni di nome Russell) non gli regala una nuova prospettiva.', 'https://image.tmdb.org/t/p/w500/j3Ga41uc0y3W8KbKjSfPHQiZYVn.jpg', '2026-10-30T19:29:17.309998', 'Ed Asner, Christopher Plummer, Jordan Nagai, Bob Peterson, Delroy Lindo, Jerome Ranft, John Ratzenberger', NULL, NULL, NULL),
(312, 'Il codice da Vinci', 2006, 'Ron Howard', 'Thriller, Mistero', 'Nel Museo del Louvre ha avuto luogo uno spettacolare omicidio e tutti gli indizi fanno pensare ad una setta religiosa che non si ferma davanti a niente pur di difendere una verità, la quale però non può essere nascosta ancora a lungo e il mistero rischia di essere decodificato. Per proteggere un segreto a volte basta chiedere a chi lo custodisce di non rivelarlo; tuttavia se può far crollare 2''000 anni di dogmi consolidati, bisogna mettere a tacere i suoi depositari, costasse anche la loro vita.', 'https://image.tmdb.org/t/p/w500/sBqvvYq8PSNCJD3154Vdl5e7vAs.jpg', '2026-10-30T19:50:39.462433', 'Tom Hanks, Audrey Tautou, Ian McKellen, Jean Reno, Paul Bettany, Alfred Molina, Jürgen Prochnow', NULL, NULL, NULL),
(313, 'Angeli e demoni', 2009, 'Ron Howard', 'Thriller, Mistero', 'Roma e il mondo sono in lutto per la morte del Santo Padre. Distrutto l''anello piscatorio, il camerlengo deve fare fronte al rapimento dei quattro cardinali favoriti alla successione pontificia e alla minaccia della distruzione della Città del Vaticano ad opera degli Illuminati, una confraternita venuta dal passato a rivendicare il primato della scienza sulla Chiesa e sullo Spirito. Riunito in Concistoro per eleggere il nuovo Papa, il collegio cardinalizio assolda Robert Langdon, docente di simbologia religiosa a Harvard. Nemico stimato della Chiesa, che non gli perdona la negazione dell''incarnazione del Verbo, il cavaliere accademico accetta l''investitura e parte alla volta della Capitale. Archiviati acredine e risentimento, il professore e gli uomini della Chiesa, armati di spirito e alabarda, collaboreranno alle indagini e alla risoluzione del mistero. Un mistero nascosto dentro le chiese e sotto le segrete della Città Eterna.', 'https://image.tmdb.org/t/p/w500/9Jc7YuiYVFpiJ7tbvXkRV7GTxTM.jpg', '2026-10-30T19:52:45.583465', 'Tom Hanks, Ewan McGregor, Ayelet Zurer, Stellan Skarsgård, Pierfrancesco Favino, Nikolaj Lie Kaas, Armin Mueller-Stahl', NULL, NULL, NULL),
(314, 'Gran Torino', 2008, 'Clint Eastwood', 'Dramma', 'Walt Kowalski è un veterano della guerra in Corea e non sopporta che nell''abitazione di fianco alla sua viva una famiglia di asiatici. Le uniche sue passioni, oltre alla birra, sono il suo cane e un''auto modello Gran Torino, che viene sottoposta a continua manutenzione. La sua vita cambia il giorno in cui il giovane vicino Thao, spinto da una gang, si introduce nel suo garage. Walt lo fa fuggire, ma di lì a poco tempo assisterà a una violenta irruzione dei membri della gang con inatteso sconfinamento nella sua proprietà. In quell''occasione sottrarrà Thao alla violenza del branco, ottenendo la riconoscenza della sua famiglia.', 'https://image.tmdb.org/t/p/w500/eUepSGWIJjXeMAlSnk4CSZKOTfg.jpg', '2026-10-30T19:53:12.813912', 'Clint Eastwood, Christopher Carley, Bee Vang, Ahney Her, Brian Haley, Geraldine Hughes, Dreama Walker', NULL, NULL, NULL),
(315, 'The Wrestler', 2008, 'Darren Aronofsky', 'Dramma, Romance', 'Randy "The Ram" Robinson era un wrestler professionista di rinomata fama alla fine degli anni 80''. Vent''anni dopo tira avanti esibendosi per i fans del duro wrestling nelle palestre dei licei e nelle comunità del New Jersey. Allontanatosi dalla figlia, incapace di sostenere un vero rapporto, Randy vive per il brivido dello show, per l''adrenalina del combattimento e per l''adorazione dei fans che gli rimangono. Colto da un infarto durante un combattimento, il dottore gli dice di eliminare gli steroidi e di sospendere i combattimenti di wrestling. Costretto a lasciare lo show-business, Randy comincia a riflettere sulla sua vita. Prova a riallacciare i rapporti con sua figlia e inizia una relazione con una spogliarellista ormai non più giovanissima. Per un periodo le cose funzionano; tuttavia il richiamo della ribalta è troppo forte per lui e Randy si cimenta ancora una volta nel combattimento sul ring.', 'https://image.tmdb.org/t/p/w500/A0Uq6fZG9UVbaFZmwF593ESz8LE.jpg', '2026-10-30T19:53:52.990735', 'Mickey Rourke, Marisa Tomei, Evan Rachel Wood, Mark Margolis, Todd Barry, Wass Stevens, Judah Friedlander', NULL, NULL, NULL),
(316, 'The Hurt Locker', 2008, 'Kathryn Bigelow', 'Dramma, Thriller, Guerra', 'I 40 giorni al fronte, in Iraq, di una squadra di artificieri e sminatori dell''esercito statunitense, unità speciale con elevatissimo tasso di mortalità. Quando tutto quel che resta del suo predecessore finisce in una "cassetta del dolore", pronta al rimpatrio, a capo della EOD (unità per la dismissione di esplosivi) arriva il biondo William James, un uomo che ha disinnescato un numero incredibile di bombe e sembra non conoscere la paura della morte. Uno che non conta i giorni, un volontario che ha scelto quel lavoro e da esso si è lasciato assorbire fino al punto di non ritorno.', 'https://image.tmdb.org/t/p/w500/9XaL18pWKcQO2M581832MjHlldD.jpg', '2026-10-30T19:54:20.932738', 'Jeremy Renner, Anthony Mackie, Brian Geraghty, David Morse, Guy Pearce, Evangeline Lilly, Ralph Fiennes', NULL, NULL, NULL),
(317, 'Io sono leggenda', 2007, 'Francis Lawrence', 'Dramma, Fantascienza, Thriller', 'New York, 2012. Un virus creato per curare il cancro, ha trasformato le persone in creature cannibali che temono la lice del sole. La città è deserta e l''unico sopravvissuto è il dottor Robert Neville, immune al virus che tenta di trovare un siero che potrebbe salvare l''umanità.', 'https://image.tmdb.org/t/p/w500/lrHsksAln0IxYFfZVgW6iRTaUsi.jpg', '2026-10-30T19:55:04.091755', 'Will Smith, Alice Braga, Charlie Tahan, Dash Mihok, Salli Richardson-Whitfield, Willow Smith, Emma Thompson', NULL, NULL, NULL),
(318, 'Il petroliere', 2007, 'Paul Thomas Anderson', 'Dramma', 'Daniel Plainview è un cercatore d''argento che, alla fine dell''800 trova il petrolio nell''Ovest degli Stati Uniti. La sua ricchezza diventa considerevole, ma l''uomo, sempre più accecato da una misantropia assoluta, allontanerà da sé anche il figlio, precipitando sempre più nell''avidità del possesso.', 'https://image.tmdb.org/t/p/w500/2eH78Nz708yFVrcaZAE2bspY5q5.jpg', '2026-10-30T19:57:35.32566', 'Daniel Day-Lewis, Paul Dano, Kevin J. O''Connor, Ciarán Hinds, Dillon Freasier, Hope Elizabeth Reeves, Colleen Foy', NULL, NULL, NULL),
(319, 'Hot Fuzz', 2007, 'Edgar Wright', 'Crime, Azione, Commedia', 'Vittima dell''invidia dei colleghi e dei superiori, l''agente Nicholas Angel, pluridecorato, viene considerato un esaltato. Con la scusa di una promozione, così, i suoi superiori cercano di allontanarlo il più possibile da Londra, spedendolo in un paesino a 250 km di distanza, dove non accade nulla di emozionante, almeno apparentemente... Seguendo la pista di alcune morti che sembrano casuali, Angel s''imbatte finalmente in un caso "succulento"...', 'https://image.tmdb.org/t/p/w500/xY1DI4NJGgwbP5dqjPHgQWB4Elb.jpg', '2026-10-30T19:58:06.944451', 'Simon Pegg, Nick Frost, Jim Broadbent, Paddy Considine, Rafe Spall, Kevin Eldon, Olivia Colman', NULL, NULL, NULL),
(320, 'Apocalypto', 2006, 'Mel Gibson', 'Azione, Dramma, Storia', 'Negli anni del declino del regno Maya, i governanti sono convinti che per tornare a prosperare basterà costruire nuovi templi e fare numerosi sacrifici umani. Ma Zampa di giaguaro, un giovane selezionato essere ucciso sull''altare, decide di tentare di sfuggire al suo destino...', 'https://image.tmdb.org/t/p/w500/8z6coUJwLrM9akjheUeTTQ8Bgxx.jpg', '2026-10-30T19:58:25.366353', 'Rudy Youngblood, Raoul Max Trujillo, Gerardo Taracena, Iazua Larios, Antonio Monroy, María Isabel Díaz Lago, Dalia Hernández', NULL, NULL, NULL),
(325, 'Scoop', 2006, 'Woody Allen', 'Commedia, Mistero', 'Sondra è una giornalista in erba che riceve dal fantasma di un famoso reporter, appena morto, alcune informazioni su un serial killer ancora in libertà. Sebbene grazie a circostanze ben poco credibili, Sondra ha in mano l’occasione della sua vita e insieme al mago da avanspettacolo Sid Waterman inizia a seguire le tracce del presunto assassino, l’aristocratico e affascinante Peter Lyman.', 'https://image.tmdb.org/t/p/w500/vyQD8AHtA3zK5ufHI5l6CQ4o4TD.jpg', '2026-10-30T20:00:20.77688', 'Scarlett Johansson, Woody Allen, Hugh Jackman, Ian McShane, Charles Dance, Romola Garai, Kevin McNally', NULL, NULL, NULL),
(321, 'Grindhouse - A prova di morte', 2007, 'Quentin Tarantino', 'Azione, Thriller', 'Tre ragazze Jungle Julia, Shanna e Arlene, tutte molto carine, si divertono a passare le serate tra due locali di Austin, Texas, il "Guero''s" e il "Texas Chili Parlor", dove attirano gli sguardi indiscreti degli avventori. Tra i tanti camionisti e motociclisti presenti al locale c''è Stuntman Mike un killer misogino schizofrenico che si diverte a uccidere le ragazze a bordo di una truccatissima vettura. Una sera, Mike prende di mira le tre amiche e, a loro insaputa, le seduce per poi condurle verso la sua arma, posteggiata vicino il Guero''s...', 'https://image.tmdb.org/t/p/w500/kf493fwH6DM9sNZ798Qf9NnSsBG.jpg', '2026-10-30T19:59:08.372984', 'Kurt Russell, Zoë Bell, Rosario Dawson, Vanessa Ferlito, Sydney Tamiia Poitier, Tracie Thoms, Rose McGowan', NULL, NULL, NULL),
(322, 'The Prestige', 2006, 'Christopher Nolan', 'Dramma, Mistero, Fantascienza', 'Due giovani maghi apprendisti, Robert Angier e Alfred Borden, vengono istruiti e seguiti da Cutter, un ingegnere illusionista ed ex mago, ma durante un numero in cui una donna viene legata e messa in una cassa di vetro piena d''acqua, qualcosa va storto e Angier incolperà l''amico dell''accaduto, tentando di vendicarsi. Inizia così un crudele gioco tra i due uomini su chi sia il migliore e la rivalità si trasformerà pian piano in ossessione.', 'https://image.tmdb.org/t/p/w500/1GjRCeZoE251tWkYc3erwjpdBpU.jpg', '2026-10-30T19:59:29.891736', 'Hugh Jackman, Christian Bale, Michael Caine, Piper Perabo, Rebecca Hall, Scarlett Johansson, Samantha Mahurin', NULL, NULL, NULL),
(329, 'Cinderella Man - Una ragione per lottare', 2005, 'Ron Howard', 'Romance, Dramma, Storia', 'Ispirato alla vera storia del pugile Jim Braddock che, nel periodo della Grande Depressione, per sfamare la famiglia tentò la fortuna con la boxe. Braddock passò velocemente dalla miseria alla gloria quando, nel 1935, riuscì a battere in un combattimento epico di 15 riprese il campione del mondo dei pesi massimi Max Baer.', 'https://image.tmdb.org/t/p/w500/6TeNVIUGkCh9ZaTysb94Blhbram.jpg', '2026-10-30T20:02:21.448149', 'Russell Crowe, Renée Zellweger, Paul Giamatti, Craig Bierko, Paddy Considine, Bruce McGill, David Huband', NULL, NULL, NULL),
(323, 'The Departed - Il bene e il male', 2006, 'Martin Scorsese', 'Dramma, Thriller, Crime', 'Boston. È in atto una guerra tra la polizia locale e una banda della malavita organizzata. Billy Costigan, giovane poliziotto in incognito, riceve l''incarico di infiltrarsi nella gang capeggiata dal boss Frank Costello. Mentre Billy guadagna rapidamente la fiducia di Costello, Colin Sullivan, giovane criminale incallito infiltrato nel dipartimento di polizia come informatore della gang, guadagna una posizione di rilievo nell''unità speciale di investigazione. Sia Billy che Colin vivono questa doppia vita come un''esperienza alienante, ma appena appare chiara l''esistenza di una talpa, sia all''interno della polizia che fra i gangster, entrambi dovranno, in una corsa contro il tempo, scoprire l''identità dell''altro per salvarsi.', 'https://image.tmdb.org/t/p/w500/oTIEFn7Xf3bZ6HZP3yRF8CzzmYQ.jpg', '2026-10-30T19:59:39.637171', 'Leonardo DiCaprio, Matt Damon, Jack Nicholson, Mark Wahlberg, Martin Sheen, Ray Winstone, Vera Farmiga', NULL, NULL, NULL),
(324, 'Scoop', 2024, 'Philip Martin', 'Dramma', 'Questa drammatizzazione ispirata a eventi reali racconta come le donne di Newsnight hanno ottenuto la famigerata intervista con il principe Andrea.', 'https://image.tmdb.org/t/p/w500/ib3H2ZSeVRTAmd7EtGWV31LswaZ.jpg', '2026-10-30T20:00:01.400329', 'Gillian Anderson, Billie Piper, Rufus Sewell, Keeley Hawes, Romola Garai, Richard Goulding, Amanda Redman', NULL, NULL, NULL),
(326, 'The Illusionist - L''illusionista', 2006, 'Neil Burger', 'Fantasy, Dramma, Thriller, Romance', 'Siamo all''inizio del XX secolo, in Austria. Eisenheim è un adolescente innamorato (e ricambiato) della bella Sophie: la ragazza però, è promessa sposa del Principe Leopoldo, erede al trono. I due sono costretti a separarsi ed Eisenheim scompare dalla circolazione. Quindici anni dopo, il ragazzo è cresciuto e strega Vienna con spettacoli nei quali mette in mostra le sue incredibili doti di illusionista: una sera incontra Sophie, e l''amore si riaccende, ma il Principe Leopoldo, aiutato dall''Ispettore Generale Uhl, capo della Polizia, fa di tutto per stroncare una volta per tutte la relazione.', 'https://image.tmdb.org/t/p/w500/bGvkZZtWymiN3am617tpExQ0ow1.jpg', '2026-10-30T20:01:05.223755', 'Edward Norton, Paul Giamatti, Jessica Biel, Rufus Sewell, Eddie Marsan, Aaron Taylor-Johnson, Eleanor Tomlinson', NULL, NULL, NULL),
(327, 'Munich', 2005, 'Steven Spielberg', 'Dramma, Storia, Thriller', 'Durante le Olimpiadi del 1972 di Monaco il commando di estremisti palestinesi Settembre Nero prende in ostaggio e poi uccide gli atleti israeliani. A seguito dell''attentato, una squadra di cinque uomini viene segretamente incaricata dal governo di stanare e uccidere i responsabili. Avner, ex ufficiale del Mossad, figlio di un patriota, accetta di essere a capo della missione: per un lungo periodo dovrà abbandonare la sua identità e i suoi affetti...', 'https://image.tmdb.org/t/p/w500/5APB21LvvshIZFDtGBsNMOp6SJL.jpg', '2026-10-30T20:01:35.926694', 'Eric Bana, Daniel Craig, Ciarán Hinds, Mathieu Kassovitz, Hanns Zischler, Ayelet Zurer, Geoffrey Rush', NULL, NULL, NULL),
(328, 'La guerra dei mondi', 2005, 'Steven Spielberg', 'Avventura, Thriller, Fantascienza', 'I marziani hanno deciso di invadere la Terra perché il loro pianeta è diventato invivibile e la razza umana è costretta ad affrontare una dura guerra per la sopravvivenza. Anche Ray Ferrier, ormai da tempo separato dalla sua famiglia, si trova coinvolto nella battaglia per difendere a tutti i costi i suoi figli dai violenti attacchi degli extra-terrestri...', 'https://image.tmdb.org/t/p/w500/reQUXXUd0WeoIJiSvYjlGLRGpXR.jpg', '2026-10-30T20:01:57.50929', 'Tom Cruise, Dakota Fanning, Miranda Otto, Justin Chatwin, Tim Robbins, Rick Gonzalez, Yul Vazquez', NULL, NULL, NULL),
(330, 'A History of Violence', 2005, 'David Cronenberg', 'Dramma, Thriller, Crime', 'Tom Stall è il proprietario di un piccolo ristorante in una cittadina di provincia. Conduce una vita normale con la moglie e i figli fin quando un giorno si difende dall''aggressione di due feroci criminali uccidendo entrambi. La sua immagine finisce su tutti i media e spinge Carl Fogarty, un boss della mafia irlandese di Philadelpia ad andarlo a cercare.', 'https://image.tmdb.org/t/p/w500/hZRFgghyOvYkFZ6dtPtPQ97KXLg.jpg', '2026-10-30T20:04:43.840353', 'Viggo Mortensen, Maria Bello, Ed Harris, William Hurt, Ashton Holmes, Peter MacNeill, Stephen McHattie', NULL, NULL, NULL),
(331, 'Match Point', 2005, 'Woody Allen', 'Dramma, Romance, Thriller', 'L''ascesa al successo del giovane e ambizioso istruttore di tennis Chris Wilton sembra inarrestabile, grazie anche alla conquista di due donne belle e potenti che se lo contenderanno.', 'https://image.tmdb.org/t/p/w500/vHjEVTD8ucuwKSFOZJeyAnTZYli.jpg', '2026-10-30T20:04:56.696838', 'Jonathan Rhys Meyers, Scarlett Johansson, Emily Mortimer, Matthew Goode, Brian Cox, Penelope Wilton, James Nesbitt', NULL, NULL, NULL),
(332, 'Neverland - Un sogno per la vita', 2004, 'Marc Forster', 'Dramma, Fantasy', 'L’affermato drammaturgo scozzese James M. Barrie è un genio letterario dei suoi tempi ma non ne può più dei soliti vecchi temi. Inaspettatamente, trova ispirazione durante la passeggiata che fa ogni giorno per i giardini di Kensington. Lì incontra la famiglia Llewelyn Davies, quattro bambini orfani di padre e la loro bella madre. Nonostante la disapprovazione della nonna dei bambini e il risentimento di sua moglie, Barrie fa amicizia con la famiglia. Trasforma i ragazzi nei “ragazzi perduti dell’isola che non c’è”. Dalle avventure elettrizzanti dell’infanzia scaturisce il capolavoro di Barrie, Peter Pan. Al principio, la sua compagnia teatrale è scettica ma Barrie scioccherà gli attori facendoli provare con delle richieste mai sentite. Una tragica piega del destino, però, costringerà lo scrittore e le persone che ama a capire cosa davvero significa credere...', 'https://image.tmdb.org/t/p/w500/fqfx3dcYzfK6sQVRQYn9siNzBuX.jpg', '2026-10-30T20:06:01.269074', 'Johnny Depp, Kate Winslet, Julie Christie, Dustin Hoffman, Freddie Highmore, Radha Mitchell, Kate Maberly', NULL, NULL, NULL),
(333, 'Million Dollar Baby', 2004, 'Clint Eastwood', 'Dramma', 'Maggie Fitzgerald fa la cameriera, ha passato i trent''anni ma ancora sogna di affermarsi come boxeuse, e ha anche incontrato l''allenatore che fa al caso suo. Peccato che Frankie Dunn non voglia saperne di allenare una donna...', 'https://image.tmdb.org/t/p/w500/3ehWHEKe54gTpYoTZ19q2qRCCyH.jpg', '2026-10-30T20:52:23.280998', 'Clint Eastwood, Hilary Swank, Morgan Freeman, Jay Baruchel, Mike Colter, Lucia Rijker, Brían F. O''Byrne', NULL, NULL, NULL),
(334, 'Troy', 2004, 'Wolfgang Petersen', 'Azione, Avventura', 'Nel 1193 A.C., Paride, principe di Troia, rapisce Elena, regina di Sparta e moglie di Menelao. Questo sarŕ l''evento che scatenerŕ la guerra tra la Grecia micenea e Troia, una guerra lunga dieci anni che vedrà protagonisti due eroi contrapposti: Achille per i greci ed Ettore per i troiani.', 'https://image.tmdb.org/t/p/w500/6n8BiphW9fvqC6biB0RMfblqi43.jpg', '2026-10-30T20:52:33.396379', 'Brad Pitt, Orlando Bloom, Eric Bana, Brian Cox, Sean Bean, Brendan Gleeson, Diane Kruger', NULL, NULL, NULL),
(335, 'Secret Window', 2004, 'David Koepp', 'Mistero, Thriller', 'Da quando la moglie lo ha lasciato il famoso romanziere Mort Rainey è in preda ad una forte depressione e trascorre le giornate a dormire anziché a scrivere. A peggiorare le cose arriva uno psicopatico che lo accusa di aver plagiato un suo racconto. Per vendicarsi è disposto a tutto. Persino ad uccidere.', 'https://image.tmdb.org/t/p/w500/5NpdcGLZuk6AgpVrAN2f4Vmw0Yr.jpg', '2026-10-30T20:52:56.427051', 'Johnny Depp, John Turturro, Maria Bello, Timothy Hutton, Charles S. Dutton, Len Cariou, Joan Heney', NULL, NULL, NULL),
(336, 'Mystic River', 2003, 'Clint Eastwood', 'Thriller, Dramma, Mistero, Crime', 'Da ragazzini Jimmy Marcus, Sean Devine e Dave Boyle erano inseparabili. Ora, a distanza di molto tempo, i tre si ritrovano in occasione di un tragico evento: la morte della prima figlia di Jimmy. Sean, che fa il poliziotto, indaga sul fatto...', 'https://image.tmdb.org/t/p/w500/3D5VS7oWduCmwNLNmRClqGKOgZa.jpg', '2026-10-30T20:53:20.695795', 'Sean Penn, Tim Robbins, Kevin Bacon, Laurence Fishburne, Marcia Gay Harden, Laura Linney, Kevin Chapman', NULL, NULL, NULL);
INSERT INTO public.films ("id", "titolo", "anno", "regista", "genere", "trama", "poster_url", "creato_il", "attori", "slug", "backdrop_url", "trailer_url") VALUES
(337, 'La passione di Cristo', 2004, 'Mel Gibson', 'Dramma', 'Le ultime dodici ore di vita di Gesù, dall''orto degli ulivi, all''arresto e la condanna a morte. La decisione di Ponzio Pilato di affidare la scelta alla folla, la flagellazione e, infine, la crocifissione.', 'https://image.tmdb.org/t/p/w500/arQvRafRtfyEQqBZ4qAjuYuYsyo.jpg', '2026-10-30T20:53:51.079963', 'Jim Caviezel, Maia Morgenstern, Christo Jivkov, Francesco De Vito, Monica Bellucci, Mattia Sbragia, Toni Bertorelli', NULL, NULL, NULL),
(376, 'Grand Budapest Hotel', 2014, 'Wes Anderson', 'Commedia, Dramma', 'Una ragazza depone una chiave di una stanza d''hotel ai piedi del busto dedicato a uno scrittore scomparso. Lo stesso scrittore racconta delle origini del suo romanzo. Un uomo oramai anziano e stanco racconta in un albergo semi deserto ad un giovane scrittore la storia di Gustave H., il leggendario concierge del Grand Budapest Hotel, e del suo giovane protetto Zero, alle prese con il furto e il recupero di un dipinto rinascimentale inestimabile e la battaglia per un enorme patrimonio di famiglia.', 'https://image.tmdb.org/t/p/w500/tY8gmrOOzhJxfBLQNOxjbuSR52b.jpg', '2026-11-04T19:53:20.792057', 'Ralph Fiennes, F. Murray Abraham, Tony Revolori, Adrien Brody, Willem Dafoe, Mathieu Amalric, Jeff Goldblum', NULL, NULL, NULL),
(338, 'Prova a prendermi', 2002, 'Steven Spielberg', 'Dramma, Crime', 'Frank W. Abagnale Jr. è il tipico ragazzo americano di buona famiglia degli anni ''60. Ma l''improvviso dissesto finanziario del padre e il divorzio dei genitori lo costringono ad andarsene di casa. Ma come sbarcare il lunario? Ad esempio ottenendo una divisa da pilota Pan Am, falsificando assegni della compagnia aerea e comprandosi una macchina marcatrice per alterare i numeri degli stessi. In poco tempo Frank, che cambia identità più velocemente dei propri abiti, diventa una delle priorità dell''Fbi ed in particolare dell''agente Hanratty, esperto in frodi bancarie e come il suo antagonista solo al mondo.', 'https://image.tmdb.org/t/p/w500/j0Ab2kETKLFISnddShJA6LffxuO.jpg', '2026-10-30T20:54:20.529487', 'Leonardo DiCaprio, Tom Hanks, Christopher Walken, Martin Sheen, Nathalie Baye, Amy Adams, James Brolin', NULL, NULL, NULL),
(339, 'Gangs of New York', 2002, 'Martin Scorsese', 'Dramma, Storia, Crime', 'New York, 1846. Nel quartiere di Five Points una cruenta battaglia tra gang sancisce il trionfo di William Cutting - detto Billy the Butcher, capo dei nativi americani - e la morte di Padre Vallon, protettore degli emigranti. Sedici anni dopo il figlio di questi, Amsterdam, esce dal riformatorio fermamente deciso a ingraziarsi l’assassino di suo padre per poi ottenere vendetta. Conosciuto Billy, Amsterdam ne viene in pratica adottato e arriva a salvargli la vita. Una volta scoperto e sfigurato, si risolverà a combattere apertamente contro di lui, ma sono gli anni della Guerra Civile: l’ultimo scontro tra le gang sarà decisamente superato in violenza e ferocia dall’intervento delle truppe inviate a far rispettare la coscrizione obbligatoria.', 'https://image.tmdb.org/t/p/w500/zaUzyruncix1oAQLlaG0Q8WQBbY.jpg', '2026-10-30T20:54:32.708898', 'Leonardo DiCaprio, Daniel Day-Lewis, Cameron Diaz, Jim Broadbent, John C. Reilly, Henry Thomas, Liam Neeson', NULL, NULL, NULL),
(340, 'Signs', 2002, 'M. Night Shyamalan', 'Thriller, Fantascienza, Horror', 'Il reverendo Graham Hess vive a Bucks County in Pennsylvania con i suoi due figlioletti e il fratello un po’ svanito. Sua moglie è morta in un incidente e da quel momento l’uomo ha perso la fede. Un giorno scopre degli ampi cerchi tracciati nei campi intorno alla sua fattoria. Il fenomeno si manifesta anche in India e, successivamente, in tutto il mondo. E’ opera di alieni particolarmente pericolosi e abili nel non farsi individuare. Qualcuno di loro si muove anche nei pressi della fattoria. Graham riuscirà a venire a capo del mistero. M. Night Shyamalan si muove con sicurezza nel territorio del paranormale e del contatto con gli alieni.', 'https://image.tmdb.org/t/p/w500/4Jv4RWBvi0F3DIXNfVF1Ldooy86.jpg', '2026-10-30T20:54:50.72383', 'Mel Gibson, Joaquin Phoenix, Rory Culkin, Abigail Breslin, Cherry Jones, M. Night Shyamalan, Patricia Kalember', NULL, NULL, NULL),
(341, 'Minority Report', 2002, 'Steven Spielberg', 'Fantascienza, Azione, Thriller', 'Siamo nel 2054, a Washington, dove è stato messo a punto un sistema capace di prevedere i crimini, dunque prevenirli. Niente di particolarmente tecnologico: semplicemente tre umani dotati di capacità paranormali. Si chiamano pre-cog, da precognitives. Vivono in una piscina e hanno visioni che poi trasmettono a un secondo livello, a un''unità di pronto intervento, il cui eroe è John Anderton. Ma ecco che i veggenti a un certo punto indicano proprio John come futuro omicida di un tale che non conosce. Dunque il detective comincia la caccia a se stesso, naturalmente c''è la possibilità di qualche trucco, qualcuno per esempio potrebbe fabbricare non false prove, ma false visioni. Da qui una corsa contro il tempo, che è breve', 'https://image.tmdb.org/t/p/w500/8EUnGlnPlleaNHt5dLGPK5GubQT.jpg', '2026-10-30T20:55:14.591758', 'Tom Cruise, Colin Farrell, Samantha Morton, Max von Sydow, Lois Smith, Peter Stormare, Tim Blake Nelson', NULL, NULL, NULL),
(342, 'Il pianista', 2002, 'Roman Polanski', 'Dramma, Guerra', 'È la storia di Wladyslaw Szpilman, pianista ebreo polacco, attraverso la Seconda Guerra Mondiale, dall’occupazione di Varsavia all’arrivo dell’Armata Rossa. Il film è diviso in due parti: la prima è incentrata sulla famiglia Szpilman, dall’iniziale mix di stupore e indignazione per le leggi razziali alla reclusione nel ghetto, infine alla deportazione; col treno che parte, e Wladyslaw che rimane giù, inizia la seconda parte, la fuga del pianista, il suo continuo cambiar nascondiglio, sempre a un passo dalla cattura, a mezzo dalla morte, a nessuno dall’orrore che in quegli anni ha avvolto Varsavia – non solo Varsavia.', 'https://image.tmdb.org/t/p/w500/zK3KyPLAQl0IRIToIaQsMxm0aR3.jpg', '2026-10-30T20:56:16.754266', 'Adrien Brody, Thomas Kretschmann, Frank Finlay, Maureen Lipman, Emilia Fox, Ed Stoppard, Julia Rayner', NULL, NULL, NULL),
(343, 'About A Boy - Un ragazzo', 2002, 'Chris Weitz', 'Dramma, Commedia, Romance', 'Will è un single, vicino ai quarant’anni: vive di rendita e il suo unico scopo nella vita sembra essere continuare a non fare niente, impiegando la maggior parte del suo tempo a cercare nuove conquiste femminili. Infatti un giorno si reca ad un incontro di genitori single, fingendosi “ragazzo-padre” solo per conquistare qualche donna sola: invece si troverà suo malgrado coinvolto nella vita di una di queste, e soprattutto di suo figlio, Marcus.', 'https://image.tmdb.org/t/p/w500/hEzs1OAhc9djI69fRUHVRgXrin.jpg', '2026-10-30T20:56:55.573904', 'Hugh Grant, Nicholas Hoult, Toni Collette, Rachel Weisz, Natalia Tena, Victoria Smurfit, Augustus Prew', NULL, NULL, NULL),
(344, 'The Greatest Hits', 2024, 'Ned Benson', 'Dramma, Musica, Romance, Fantasy', 'Harriet scopre che alcune canzoni la riportano indietro nel tempo, letteralmente. Mentre rivive una storia romantica del passato e, nel frattempo, scopre un nuovo amore nel presente attraverso il legame tra musica e memoria, si pone una domanda: cambierebbe il passato, se potesse?', 'https://image.tmdb.org/t/p/w500/cve12HkI9psBUfmkx7FeBciaQN7.jpg', '2026-10-31T14:56:53.727769', 'Lucy Boynton, Justin H. Min, David Corenswet, Austin Crute, Retta, Andie Ju, Nelly Furtado', NULL, NULL, NULL),
(345, 'L''Esorciccio', 1975, 'Ciccio Ingrassia', 'Commedia', 'Durante scavi archeologici in Iran viene rinvenuto un amuleto che finisce tra le mani del figlio decenne del sindaco di un paesino del Lazio. Il ragazzino diventa un focosissimo amatore, e ricorre quindi allo stregone Esorciccio. E come lui tutti coloro che, a turno, posseggono l''amuleto si scatenano in inverecode stranezze. Ogni tanto compare addirittura il Demonio in persona, finché Esorciccio ingoia l''oggetto diabolico.', 'https://image.tmdb.org/t/p/w500/2SWLoIVmadfNNcFnILglliTQaTN.jpg', '2026-10-31T15:23:50.004289', 'Ciccio Ingrassia, Lino Banfi, Didi Perego, Mimmo Baldi, Ubaldo Lay, Tano Cimarosa, Barbara Nascimbene', NULL, NULL, NULL),
(346, 'Seven', 1995, 'David Fincher', 'Crime, Mistero, Thriller', 'Un killer astuto e spietato sta uccidendo a raffica, nei modi più raccapriccianti, personaggi scelti con cura. Sulle sue tracce ci sono il giovane e ambizioso Mills, alla prima missione, e l''esperto Somerset, ormai prossimo alla pensione; personalità opposte che mal si tollerano a vicenda. Imparano a "convivere" man mano che la caccia all''assassino si fa più serrata e il mistero comincia a districarsi.', 'https://image.tmdb.org/t/p/w500/1XHq0Z7BkjeQ9J5CLmWD0xX0DuB.jpg', '2026-10-31T15:33:13.250536', 'Morgan Freeman, Brad Pitt, Gwyneth Paltrow, John Cassini, Peter Crombie, Reg E. Cathey, R. Lee Ermey', NULL, NULL, NULL),
(347, 'A Beautiful Mind', 2001, 'Ron Howard', 'Dramma, Romance', 'Il film si ispira alla vita di John Forbes Nash Jr. Di origini medio borghesi, Forbes nacque in una piccola città della Virginia occidentale il 13 giugno 1928 e, per oltre cinquant''anni è stato considerato un mito negli ambienti della ricerca matematica. Grazie al suo studio della teoria dei giochi, negli anni 50 diventò l''astro nascente della "nuova matematica". Poco a poco, vittima di una grave forma di schizofrenia, Nash sprofondò in un mondo tutto suo, convinto che le sue allucinazioni fossero realtà. Passò diversi anni in ospedali psichiatrici, ma durante la sua assenza, la teoria dei giochi acquistò un ruolo di importanza fondamentale nei campi dell''economia e degli affari. Nel 1994, Nash aveva riacquistato il pieno controllo della sua vita e ripreso le ricerche. In quello stesso anno venne insignito del Premio Nobel per l''economia.', 'https://image.tmdb.org/t/p/w500/bsVAjDLllFLEkuS1HwU96bbvkw5.jpg', '2026-10-31T15:35:02.457808', 'Russell Crowe, Jennifer Connelly, Ed Harris, Paul Bettany, Christopher Plummer, Adam Goldberg, Josh Lucas', NULL, NULL, NULL),
(348, 'Vanilla Sky', 2001, 'Cameron Crowe', 'Mistero, Romance, Fantascienza', 'David Aames è un uomo davvero fortunato. È giovane, è bello ed è ricco, essendo l''erede di un impero editoriale. È abituato a ottenere ciò che vuole quando vuole, finché un giorno non incontra Sofia, che scompare quando lui comprende che è la donna dei suoi sogni. La vita di David non sarà più la stessa e la cercherà in modo ossessivo a rischio di perdere tutto.', 'https://image.tmdb.org/t/p/w500/aV9cwAmpNhxlX8l64RXULc9jrqN.jpg', '2026-10-31T15:35:21.193302', 'Tom Cruise, Penélope Cruz, Cameron Diaz, Kurt Russell, Jason Lee, Noah Taylor, Timothy Spall', NULL, NULL, NULL),
(349, 'Pearl Harbor', 2001, 'Michael Bay', 'Dramma, Guerra', 'In una tranquilla domenica mattina di dicembre, mentre i bambini sono intenti nei loro giochi e le famiglie raccolte in preghiera, squadroni di aerei da guerra giapponesi sfrecciano roboanti nei cieli del paradiso hawaiano un attacco a sorpresa contro le forze armate statunitensi di base a Pearl Harbor. Pearl Harbor è la storia di un intenso amore nato sullo sfondo degli eventi del 7 dicembre 1941. Descrive le vicende di due giovani e audaci piloti e della bella e sensibile infermiera di cui sono entrambi innamorati. E'' un imponente film sulla forza dell''amore e sul coraggio del singolo messi a dura prova da un drammatico momento storico.', 'https://image.tmdb.org/t/p/w500/rU08tMQ381BRMjKSwDKiR00TNeq.jpg', '2026-10-31T15:35:41.109814', 'Ben Affleck, Josh Hartnett, Kate Beckinsale, William Lee Scott, Greg Zola, Ewen Bremner, Alec Baldwin', NULL, NULL, NULL),
(350, 'Mulholland Drive', 2001, 'David Lynch', 'Thriller, Dramma, Mistero', 'In tarda notte, una limousine percorre Mulholland Drive (una strada che attraversa le colline attorno a Los Angeles, California); al suo interno c''è una donna dai capelli scuri (interpretata da Laura Elena Harring) e due uomini; improvvisamente, l''auto si ferma ed uno dei due uomini punta una pistola contro la donna; subito dopo, però, dei pirati della strada si schiantano contro la limousine. La donna resta miracolosamente illesa, ma ha un''amnesia. Abbandona la scena dell''incidente e scende la collina che porta a Los Angeles, stendendosi nel giardino di un appartamento e mettendosi a dormire. Il giorno successivo, si sveglia e vede la proprietaria dell''appartamento, una donna di mezza età dai capelli rossi, che sta per partire.', 'https://image.tmdb.org/t/p/w500/zQKnbazscP54i6iKHfdgYdmDsLv.jpg', '2026-10-31T15:36:02.190486', 'Naomi Watts, Laura Harring, Justin Theroux, Ann Miller, Mark Pellegrino, Robert Forster, Dan Hedaya', NULL, NULL, NULL),
(351, 'La vera storia di Jack lo Squartatore', 2001, 'Albert Hughes', 'Horror, Mistero, Thriller', 'Londra, 1888. Nelle strade del quartiere di Whitechapel, Jack lo Squartatore si aggira di notte uccidendo e sventrando le prostitute. Sulle sue tracce, oltre all''intera polizia londinese, c''è l''ispettore Frederick George Abberline, l''unico che capisce subito che i delitti sono preceduti da una meticolosa e scrupolosa messa in scena. Il poliziotto, intuitivo e visionario, cerca di ricostruire il profilo di Jack anche grazie all''aiuto della prostituta Mary Kelly.', 'https://image.tmdb.org/t/p/w500/pvgnEmCPie99MOZFrkEpA73QHgg.jpg', '2026-10-31T15:36:20.561313', 'Johnny Depp, Heather Graham, Ian Holm, Robbie Coltrane, Ian Richardson, Jason Flemyng, Katrin Cartlidge', NULL, NULL, NULL),
(352, 'Chocolat', 2000, 'Lasse Hallström', 'Commedia, Dramma, Romance', 'L''apertura di un peccaminoso negozio di cioccolata da parte della giovane Vianne Rocher nel minuscolo villaggio di Lansquenet, scatena una vera e propria guerra all''interno della cittŕ, tra quelli che non vedono di buon occhio il negozio e quelli che desiderano assaporare la libertà che hanno appena scoperto.', 'https://image.tmdb.org/t/p/w500/ym4zIlPCAoD0UqOBf6NmHcK0YIi.jpg', '2026-10-31T15:36:34.238967', 'Juliette Binoche, Judi Dench, Alfred Molina, Lena Olin, Johnny Depp, Hugh O''Conor, Carrie-Anne Moss', NULL, NULL, NULL),
(353, 'Cast Away', 2000, 'Robert Zemeckis', 'Avventura, Dramma', 'È la vigilia di Natale e Chuck Noland, funzionario della Federal Express, scambia i regali con la sua fidanzata Kelly in macchina prima di salire a bordo dell''aereo per l''ennesimo viaggio di lavoro. A causa di una tempesta l''aereo si inabissa nel Pacifico. Chuck, unico sopravvissuto, naufraga su di un isola deserta dove si rende conto, poco alla volta, che dovrà restarci per molto molto tempo.', 'https://image.tmdb.org/t/p/w500/WOTDhrel5R6hDhfDhFhHmExxjO.jpg', '2026-10-31T15:36:53.034823', 'Tom Hanks, Helen Hunt, Nick Searcy, Jenifer Lewis, Geoffrey Blake, Peter Von Berg, Chris Noth', NULL, NULL, NULL),
(354, 'Rapimento e riscatto', 2000, 'Taylor Hackford', 'Thriller, Azione, Dramma', 'Per liberare un importante manager americano, preso in ostaggio da alcuni guerriglieri colombiani, un negoziatore si reca in America Latina. Ed innamorandosi della moglie del prigioniero non fa che complicare la sua missione...', 'https://image.tmdb.org/t/p/w500/4v6lGQKphnHNz3AYb72M7xfVs0a.jpg', '2026-10-31T15:37:11.658276', 'Meg Ryan, Russell Crowe, David Morse, Pamela Reed, David Caruso, Anthony Heald, Stanley Anderson', NULL, NULL, NULL),
(355, 'Unbreakable - Il predestinato', 2000, 'M. Night Shyamalan', 'Thriller, Dramma, Mistero', 'David Dunn è l''unico superstite di un disastroso incidente ferroviario; non solo è stato l''unico a salvarsi su 132 passeggeri, ma non ha riportato nemmeno un graffio. Forse soltanto la folle teoria di Elijah Price, un esperto di fumetti che si è messo in contatto con David, può spiegare la sua miracolosa invulnerabilità.', 'https://image.tmdb.org/t/p/w500/4bbHcTViomdM0j7dM0Tm0CYQF1m.jpg', '2026-10-31T15:37:34.230324', 'Bruce Willis, Samuel L. Jackson, Robin Wright, Spencer Treat Clark, Charlayne Woodard, Eamonn Walker, Leslie Stefanson', NULL, NULL, NULL),
(356, 'Memento', 2000, 'Christopher Nolan', 'Mistero, Thriller', 'Leonard Shelby è affetto da una particolare forma di amnesia che lascia intatti i vecchi ricordi ma comporta la perdita della memoria breve. Attraverso un''affannosa ricerca compiuta per mezzo dell''azione e della scrittura, che serve a registrare ciò di cui la percezione non può farsi sicuro garante, Leonard cerca l''assassino della moglie, l''ultimo ricordo che "non riesce a ricordare di dimenticare".', 'https://image.tmdb.org/t/p/w500/eyVdGf0QUnw1SBr1IMvZJj5kk6M.jpg', '2026-10-31T15:37:51.201844', 'Guy Pearce, Carrie-Anne Moss, Joe Pantoliano, Mark Boone Junior, Russ Fega, Jorja Fox, Stephen Tobolowsky', NULL, NULL, NULL),
(357, 'La tempesta perfetta', 2000, 'Wolfgang Petersen', 'Dramma, Avventura, Azione, Thriller', 'Gloucester, Massachusetts: un gruppo di pescatori, guidati dal determinato capitano Billy Tyne, dopo un periodo di magra, si dirigono al largo in cerca di maggiore fortuna; l''equipaggio del peschereccio "Andrea Gail" naviga oltre le normali rotte di pesca del New England, fino al Flemish Cap, noto per i ricchi banchi di pesce spada. Mentre si trova già in alto mare, la barca riceve l''allarme riguardo ad una tempesta che sta montando alle loro spalle, ma, decisi a non rinunciare alla ricca battuta di pesca ed ai guadagni che con essa ne ricaveranno, ignorano l''avvertimento e procedono nel loro intento. Sfortunatamente la situazione meteoreologica peggiora e l''uragano Grace è in rotta di collisione con altre due aree di bassa pressione, una proveniente da Sud, l''altra da Nord, dalla cui unione scaturisce la cosiddetta tempesta perfetta, un evento che, secondo gli esperti meteo, si verifica molto raramente.', 'https://image.tmdb.org/t/p/w500/kpQ8X4WAQJ032CYlta81B6OrZcg.jpg', '2026-10-31T15:38:31.474361', 'George Clooney, Mark Wahlberg, Diane Lane, John C. Reilly, William Fichtner, Mary Elizabeth Mastrantonio, John Hawkes', NULL, NULL, NULL),
(358, 'Il talento di Mr. Ripley', 1999, 'Anthony Minghella', 'Thriller, Crime, Dramma', '1958: Tom Ripley è un giovane americano educato di modesta estrazione. Cede il posto alle signore e ascolta rispettosamente i consigli dei più anziani. Con gli amici è allegro, non ha eguali nell''imitare i personaggi celebri, nel cantare e suonare il piano. Soprattutto tende spesso a mentire pur di mascherare la propria condizione. Un giorno durante un party la grande occasione: un ricco industriale gli chiede, dietro un cospicuo compenso, di riportare negli Stati Uniti suo figlio Dickie, che vive un esilio dorato in Italia. Tom infatti, si è sentito di spacciarsi per un suo compagno di università, avendo indossato un blazer dell''istituto fattosi prestare da un amico per l''occasione. Il giovane entra in una gigantesca avventura, raggiunge quindi Ischia, dove vive Dick Greenleaf; ne diventa amico, e conosce anche la sua bella ragazza, Marge.', 'https://image.tmdb.org/t/p/w500/g7GOx0foFBSdrzzpNGKKeoKwdqA.jpg', '2026-10-31T16:00:31.322916', 'Matt Damon, Gwyneth Paltrow, Jude Law, Cate Blanchett, Philip Seymour Hoffman, Jack Davenport, James Rebhorn', NULL, NULL, NULL),
(359, 'Il mistero di Sleepy Hollow', 1999, 'Tim Burton', 'Fantasy, Thriller, Mistero, Horror', '1799, il poliziotto Ichabod Crane viene inviato nel piccolo paese di Sleepy Hollow per indagare su una serie di omicidi commessi da un presunto cavaliere senza testa.', 'https://image.tmdb.org/t/p/w500/eX61VBYV1mh4AARjogZ4WIZeGaQ.jpg', '2026-10-31T16:00:54.430138', 'Johnny Depp, Christina Ricci, Miranda Richardson, Michael Gambon, Casper Van Dien, Jeffrey Jones, Richard Griffiths', NULL, NULL, NULL),
(360, 'The Sixth Sense - Il sesto senso', 1999, 'M. Night Shyamalan', 'Mistero, Thriller, Dramma', 'Un famoso psichiatra infantile in un momento difficile della propria vita fa amicizia con un bambino che sembra avere dei problemi. Presosi a cuore il caso, l''uomo riesce a entrarvi in confidenza e a scoprire che è disturbato da visioni: il piccolo asserisce infatti di poter vedere la gente morta.', 'https://image.tmdb.org/t/p/w500/1Dth4Jbh7FzPguUIddmK43deTCy.jpg', '2026-10-31T16:01:15.769956', 'Bruce Willis, Haley Joel Osment, Toni Collette, Olivia Williams, Trevor Morgan, Donnie Wahlberg, Peter Anthony Tambakis', NULL, NULL, NULL),
(361, 'Non aprite quella porta', 1974, 'Tobe Hooper', 'Horror', 'Mentre è in corso una serie di misteriose razzie nei cimiteri della zona, Sally (Marilyn Burns), assieme al fratello paraplegico Franklin (Paul A. Partain) e a un gruppo di amici, parte per una vacanza in camper alla vecchia casa abbandonata del nonno. Prima di arrivarci, i ragazzi danno un passaggio a uno strano autostoppista con cui hanno un alterco prima di sbatterlo fuori. Dopo aver dato un’occhiata alla casa, i ragazzi si separano e due di loro, Pam (Teri McMinn) e Kirk (William Vail), si imbattono in un’altra casa apparentemente abbandonata che vogliono visitare. Ma Kirk viene ucciso e Pam viene trascinata dentro la casa e impalata in un gancio da macellaio da un essere gigantesco con una maschera di cuoio in faccia (Gunnar Hansen). E gli altri dovranno cercare di salvarsi lottando contro una famiglia di cannibali.', 'https://image.tmdb.org/t/p/w500/8giqGVVX5UaQbmXM7ZEpGR9Xp8.jpg', '2026-10-31T17:42:12.957518', 'Marilyn Burns, Allen Danziger, Paul A. Partain, William Vail, Teri McMinn, Edwin Neal, Jim Siedow', NULL, NULL, NULL),
(362, 'The Next Three Days', 2010, 'Paul Haggis', 'Romance, Dramma, Thriller, Crime', 'John Brennan, la moglie Lara e il loro piccolo Luke fanno colazione con amore e con gioia, quando la polizia irrompe con un mandato d''arresto per omicidio a carico della donna. Per tre anni, il marito le fa visita quotidianamente, certo che sia tutto un abbaglio, che la giustizia le ridarà la sua casa e la sua vita. Persino più certo della moglie, che lei quell''atto non l''abbia commesso, che non avrebbe mai potuto. Quando anche l''ultimo appello viene respinto e Lara tenta il sudicio, John, tranquillo insegnante di letteratura e padre di famiglia, decide che se non sarà la legge a fare uscire sua moglie di prigione, sarà lui.', 'https://image.tmdb.org/t/p/w500/nCl2I0yGwKop0qBIpwXWJA7zQPP.jpg', '2026-10-31T18:11:11.235874', 'Russell Crowe, Elizabeth Banks, Ty Simpkins, Brian Dennehy, Helen Carey, Olivia Wilde, Daniel Stern', NULL, NULL, NULL),
(363, 'Mickey 17', 2025, '봉준호', 'Fantascienza, Commedia, Avventura', 'Mickey 17 è un "sacrificabile", un impiegato usa e getta, in una spedizione umana inviata a colonizzare il mondo ghiacciato Niflheim. Dopo la morte di un''iterazione, un nuovo corpo viene rigenerato con la maggior parte dei suoi ricordi intatti.', 'https://image.tmdb.org/t/p/w500/2JQBZs01ahsOiANQ7Fs8MN9zBY4.jpg', '2026-11-02T17:28:58.933202', 'Robert Pattinson, Naomi Ackie, Steven Yeun, Mark Ruffalo, Toni Collette, Anamaria Vartolomei, Daniel Henshall', NULL, NULL, NULL),
(364, 'Primetime', 2026, 'Lance Oppenheim', 'Dramma, Thriller', 'Nel 2006 il giornalista Chris Hansen si prepara a fare la storia della televisione con To Catch a Predator, il controverso format che, attraverso operazioni sotto copertura e telecamere nascoste, smaschera in diretta tv predatori sessuali colti sul fatto. Mentre il programma diventa un fenomeno nazionale e il suo conduttore un’icona del pubblico, il confine tra informazione, giustizia e spettacolo si fa sempre più ambiguo e il cortocircuito fra cronaca, intrattenimento e voyeurismo televisivo sempre più insostenibile.', 'https://image.tmdb.org/t/p/w500/sqArsDFYFryd5iKuoxLvr4y5NZv.jpg', '2026-11-03T15:40:51.541371', 'Robert Pattinson, Merritt Wever, Skyler Gisondo, Matthew Maher, Phoebe Bridgers, Victor Brunette, Bokeem Woodbine', NULL, NULL, NULL),
(365, 'Chi ha incastrato Roger Rabbit', 1988, 'Robert Zemeckis', 'Fantasy, Animazione, Commedia, Crime', 'In uno studio cinematografico due cartoon stanno recitando una scena: Baby Herman, un poppante tutto pepe e pieno di trovate, e il suo baby-sitter, il coniglio Roger, che per togliere il piccolo da situazioni rischiose si mette in grossi guai. Nonostante l''impegno Roger non soddisfa il regista con la sua interpretazione: egli infatti è assillato da preoccupazioni familiari, teme che la sua bellissima moglie Jessica lo tradisca col padrone di Cartoonia, Marvin Acme. Viene incaricato di trovare le prove del tradimento il detective privato Eddie Valiant, sempre senza soldi e mezzo alcolizzato da quando suo fratello Teddy fu ucciso cinque anni prima da un cartoon. Eddie riesce a trovare ciò che cercava e per Roger è la disperazione: questi lascia l''ufficio del produttore Mr. Maroon in preda ad una nera desolazione e nulla può fare per consolarlo Valiant che ne ha compassione. La polizia trova il cadavere di Acme e dà subito la colpa a Roger...', 'https://image.tmdb.org/t/p/w500/5KZOkoKzj5wfJOGdWZYy4O4LLY2.jpg', '2026-11-03T15:41:59.435628', 'Bob Hoskins, Christopher Lloyd, Joanna Cassidy, Charles Fleischer, Kathleen Turner, Stubby Kaye, Alan Tilvern', NULL, NULL, NULL),
(366, 'Il silenzio degli innocenti', 1991, 'Jonathan Demme', 'Crime, Thriller, Dramma', 'Dal romanzo omonimo di Thomas Harris. Una giovane recluta dell''FBI è incaricata di far visita in carcere a Hannibal Lecter, psichiatra pluriomicida, per ottenere informazioni su un assassino psicopatico che ha ucciso e scuoiato cinque donne.', 'https://image.tmdb.org/t/p/w500/jCS4Iw1bGGhSEdzFeUq8CX8UoiC.jpg', '2026-11-03T15:42:40.872438', 'Jodie Foster, Anthony Hopkins, Scott Glenn, Ted Levine, Anthony Heald, Brooke Smith, Diane Baker', NULL, NULL, NULL),
(367, 'Ti uccideranno', 2026, 'Кирилл Соколов', 'Azione, Commedia, Horror', '"Ti uccideranno" porta sul grande schermo un horror-action-comedy ad alto tasso di adrenalina e intriso di sangue, in cui una giovane donna deve sopravvivere alla notte al Virgil, dove è stata da poco assunta come domestica, senza sapere che quell’edificio nasconde un passato inquietante fatto di inspiegabili sparizioni.  Ne nasce uno scontro cinematografico audace e senza freni, tra uccisioni efferate e un umorismo nerissimo.', 'https://image.tmdb.org/t/p/w500/jCe5etBmMuTf2TXgYvv0EDUj4BZ.jpg', '2026-11-03T16:04:48.901821', 'Zazie Beetz, Patricia Arquette, Myha''la, Paterson Joseph, Tom Felton, Heather Graham, Willie Ludik', NULL, NULL, NULL),
(368, 'Predator: Badlands', 2025, 'Dan Trachtenberg', 'Azione, Fantascienza, Avventura', 'Nel futuro, su un pianeta remoto, un giovane Predatore, emarginato dal suo clan, trova un alleato improbabile in Thia e intraprende un viaggio pericoloso alla ricerca del nemico supremo.', 'https://image.tmdb.org/t/p/w500/zn14Felr0VlFg6A86IUx4PDt2E7.jpg', '2026-11-03T17:36:34.142835', 'Elle Fanning, Dimitrius Schuster-Koloamatangi, Ravi Narayan, Michael Homick, Stefan Grube, Reuben De Jong, Cameron Brown', NULL, NULL, NULL),
(369, 'Last Breath', 2025, 'Alex Parkinson', 'Thriller, Dramma', 'Last Breath segue un esperto sommozzatore delle profondità marine mentre combatte gli elementi furiosi per salvare il suo compagno di equipaggio intrappolato a centinaia di metri sotto la superficie dell''oceano.', 'https://image.tmdb.org/t/p/w500/mKP5zZ8NjUf68D0qte9LyIA0C6k.jpg', '2026-11-03T17:42:36.676418', 'Woody Harrelson, Simu Liu, Finn Cole, Cliff Curtis, Mark Bonnar, MyAnna Buring, Josef Altin', NULL, NULL, NULL),
(370, 'Locked - In trappola', 2025, 'David Yarovesky', 'Horror, Thriller', 'Un ladruncolo riesce a forzare la serratura di un SUV di lusso, ma quando è dentro all''abitacolo si rende conto di essere incappato in una trappola complessa e mortale, tesagli da una figura misteriosa.', 'https://image.tmdb.org/t/p/w500/nn2TyHzFpOszdqgAQuAmS2WSxYe.jpg', '2026-11-03T17:43:07.765091', 'Bill Skarsgård, Anthony Hopkins, Ashley Cartwright, Michael Eklund, Navid Charkhi, Sofia Tesema, Emma Kombe', NULL, NULL, NULL),
(371, 'La trama fenicia', 2025, 'Wes Anderson', 'Commedia, Avventura, Thriller', 'Sopravvissuto ad un incidente aereo per la sesta volta in tutta la sua vita, il magnate internazionale Zsa-zsa Korda tenta di ricucire i rapporti con sua figlia Liesl, nel frattempo diventata suora, che non vede da troppo tempo.', 'https://image.tmdb.org/t/p/w500/90yhkAmFHypazSdnR0LXSf5e6h0.jpg', '2026-11-03T17:44:00.43822', 'Benicio Del Toro, Mia Threapleton, Michael Cera, Riz Ahmed, Tom Hanks, Bryan Cranston, Mathieu Amalric', NULL, NULL, NULL),
(372, 'Una pallottola spuntata', 2025, 'Akiva Schaffer', 'Commedia, Crime, Azione', 'Solo un uomo ha le pall....ottole giuste per guidare la squadra di polizia e salvare il mondo. Il tenente Frank Drebin Jr. (Liam Neeson) è pronto a raccogliere l''eredità del padre', 'https://image.tmdb.org/t/p/w500/tL8WM2MW87Sf48QctGHIpnnNSWK.jpg', '2026-11-03T17:45:21.81834', 'Liam Neeson, Pamela Anderson, Paul Walter Hauser, Danny Huston, CCH Pounder, Kevin Durand, Liza Koshy', NULL, NULL, NULL),
(373, 'Death of a Unicorn', 2025, 'Alex Scharfman', 'Horror, Fantasy, Commedia', 'Elliot, dirigente vedovo di un''azienda farmaceutica, si reca con la figlia Ridley nella fastosa tenuta del suo capo, Odell Leopold. Guidando a gran velocità per il grave ritardo accumulato, Elliot finisce per investire un animale che si era fermato in mezzo alla strada: solo che non si tratta di un animale qualsiasi, ma di un unicorno. Quando la famiglia Leopold comprende che il sangue degli animali magici ha delle proprietà curative, pensa di sfruttare la scoperta a scopo commerciale. Nessuno però ha fatto i conti con l''ira di mamma e papà unicorno, assetati di vendetta.', 'https://image.tmdb.org/t/p/w500/k3Nuu7Z5PuC6UxVIl2xbGhFvIjj.jpg', '2026-11-03T17:45:58.726686', 'Paul Rudd, Jenna Ortega, Will Poulter, Richard E. Grant, Téa Leoni, Sunita Mani, Steve Park', NULL, NULL, NULL),
(374, 'Una pallottola spuntata', 1988, 'David Zucker', 'Commedia, Crime', 'Il cattivo Vincent Ludwig organizza un attentato contro la Regina Elisabetta, in visita in città. L''imbranato tenente di polizia Frank Drebin sospetta fin dall''inizio che ci sia qualcosa di losco in quel Ludwig e, avendo capito cosa sta tramando, cerca di mettergli i bastoni fra le ruote e salvare la regina.', 'https://image.tmdb.org/t/p/w500/psaW7ECMBTmBjI83FhLgIyhCG6e.jpg', '2026-11-04T17:54:50.873466', 'Leslie Nielsen, Priscilla Presley, Ricardo Montalban, George Kennedy, O. J. Simpson, Susan Beaubian, Nancy Marchand', NULL, NULL, NULL),
(375, 'Mediterraneo', 1991, 'Gabriele Salvatores', 'Commedia, Romance, Guerra', 'Avventure, amori e tribolazioni di otto soldati del Regio Esercito Italiano che nel giugno 1941 sono mandati a presidiare un''isoletta greca dell''Egeo dove rimangono sino all''inverno del 1943, dimenticandosi degli avvenimenti bellici in corso. Uno degli otto non tornerà. Senza ambizioni storiche, è una favola, un racconto di formazione, un apologo sull''amicizia virile, sul desiderio di fuga (è dedicato “a tutti quelli che stanno scappando”), sulle difficoltà di crescere. Chiude un''ideale trilogia sul viaggio e su una generazione, quella del regista, formata da Marrakech Express e Turné. Un bel gioco di squadra attoriale e un''accattivante mistura di buffo e patetico con molti stereotipi e qualche leziosaggine ruffiana. Girato nell''isola di Kastellorizo (Megisti in greco). Oscar per il film straniero.', 'https://image.tmdb.org/t/p/w500/wfJ2flMchZPQCSdt8h3ZQNSW7Ym.jpg', '2026-11-04T19:50:24.931552', 'Diego Abatantuono, Claudio Bigagli, Giuseppe Cederna, Claudio Bisio, Gigio Alberti, Ugo Conti, Memo Dini', NULL, NULL, NULL);
